			const sourceDefault = Parser.getTagSource("race");
			raceSource ||= opts.isLower ? sourceDefault.toLowerCase() : sourceDefault;
			source ||= opts.isLower ? sourceDefault.toLowerCase() : sourceDefault;
			return {
				name,
				raceName,
				raceSource,
				source,
				displayName,
			};
