Renderer.generic = class {
	/**
	 * @param ent
	 * @param [opts]
	 * @param [opts.isSkipNameRow]
	 * @param [opts.isSkipPageRow]
	 * @param [opts.dataProp]
	 * @param [opts.page]
	 */
	static getCompactRenderedString (ent, opts) {
		opts = opts || {};

		const styleHint = VetoolsConfig.get("styleSwitcher", "style");

		const prerequisite = Renderer.utils.prerequisite.getHtml(ent.prerequisite, {styleHint});

		return `
		${opts.dataProp && opts.page ? Renderer.utils.getExcludedTr({entity: ent, dataProp: opts.dataProp, page: opts.page}) : ""}
		${opts.isSkipNameRow ? "" : Renderer.utils.getNameTr(ent, {page: opts.page})}
		<tr><td colspan="6" class="ve-pb-2">
		${prerequisite ? `<p>${prerequisite}</p>` : ""}
		${Renderer.get().setFirstSection(true).render({entries: ent.entries})}
		</td></tr>
		${opts.isSkipPageRow ? "" : Renderer.utils.getPageTr(ent)}`;
	}

	/* -------------------------------------------- */

	// region Mirror the schema
	static FEATURE__SKILLS_ALL = Object.keys(Parser.SKILL_TO_ATB_ABV).sort(SortUtil.ascSortLower);

	static FEATURE__TOOLS_ARTISANS = [
		"alchemist's supplies",
		"brewer's supplies",
		"calligrapher's supplies",
		"carpenter's tools",
		"cartographer's tools",
		"cobbler's tools",
		"cook's utensils",
		"glassblower's tools",
		"jeweler's tools",
		"leatherworker's tools",
		"mason's tools",
		"painter's supplies",
		"potter's tools",
		"smith's tools",
		"tinker's tools",
		"weaver's tools",
		"woodcarver's tools",
	];
	static FEATURE__TOOLS_MUSICAL_INSTRUMENTS = [
		"bagpipes",
		"drum",
		"dulcimer",
		"flute",
		"horn",
		"lute",
		"lyre",
		"pan flute",
		"shawm",
		"viol",
	];
	static FEATURE__TOOLS_GAMING_SETS = [
		"dragonchess set",
		"dice set",
		"playing card set",
		"three-dragon ante set",
	];
	static _FEATURE__TOOL_GROUPS = new Set([
		"artisan's tools",
		"gaming set",
		"musical instrument",
		"vehicles",
	]);
	static FEATURE__TOOLS_ALL = [
		"artisan's tools",
		...this.FEATURE__TOOLS_ARTISANS,

		"disguise kit",
		"forgery kit",

		"gaming set",
		...this.FEATURE__TOOLS_GAMING_SETS,

		"herbalism kit",

		"musical instrument",
		...this.FEATURE__TOOLS_MUSICAL_INSTRUMENTS,

		"navigator's tools",
		"thieves' tools",
		"poisoner's kit",
		"vehicles",
		"vehicles (land)",
		"vehicles (water)",
		"vehicles (air)",
		"vehicles (space)",
	];

	static _FEATURE__LANGUAGES_ALL = [...Parser.LANGUAGES_ALL, "Other"].map(it => it.toLowerCase());
	static _FEATURE__LANGUAGES_STANDARD__CHOICE_OBJ = {
		from: [
			...Parser.LANGUAGES_STANDARD
				.map(it => ({
					name: it.toLowerCase(),
					prop: "languageProficiencies",
					group: "languagesStandard",
				})),
			...Parser.LANGUAGES_EXOTIC
				.map(it => ({
					name: it.toLowerCase(),
					prop: "languageProficiencies",
					group: "languagesExotic",
				})),
			...Parser.LANGUAGES_SECRET
				.map(it => ({
					name: it.toLowerCase(),
					prop: "languageProficiencies",
					group: "languagesSecret",
				})),
		],
		groups: {
			languagesStandard: {
				name: "Standard Languages",
			},
			languagesExotic: {
				name: "Exotic Languages",
				hint: "With your DM's permission, you can choose an exotic language.",
			},
			languagesSecret: {
				name: "Secret Languages",
				hint: "With your DM's permission, you can choose a secret language.",
			},
		},
	};

	static FEATURE__SAVING_THROWS_ALL = [...Parser.ABIL_ABVS];
	// endregion

	/* -------------------------------------------- */

	// region Should mirror the schema
	static _SKILL_TOOL_LANGUAGE_KEYS__SKILL_ANY = new Set(["anySkill"]);
	static _SKILL_TOOL_LANGUAGE_KEYS__TOOL_ANY = new Set(["anyTool", "anyArtisansTool", "anyGamingSet", "anyMusicalInstrument"]);
	static _SKILL_TOOL_LANGUAGE_KEYS__LANGAUGE_ANY = new Set(["anyLanguage", "anyStandardLanguage", "anyExoticLanguage", "anyRareLanguage"]);
	// endregion

	static getSkillSummary ({skillProfs, skillToolLanguageProfs, isShort = false}) {
		return this._summariseProfs({
			profGroupArr: skillProfs,
			skillToolLanguageProfs,
			setValid: new Set(this.FEATURE__SKILLS_ALL),
			setValidAny: this._SKILL_TOOL_LANGUAGE_KEYS__SKILL_ANY,
			anyAlt: "anySkill",
			isShort,
			hoverTag: "skill",
		});
	}

	static getToolSummary ({toolProfs, skillToolLanguageProfs, isShort = false}) {
		return this._summariseProfs({
			profGroupArr: toolProfs,
			skillToolLanguageProfs,
			setValid: new Set(this.FEATURE__TOOLS_ALL),
			setValidAny: this._SKILL_TOOL_LANGUAGE_KEYS__TOOL_ANY,
			anyAlt: "anyTool",
			isShort,
		});
	}

	static getLanguageSummary ({languageProfs, skillToolLanguageProfs, isShort = false}) {
		return this._summariseProfs({
			profGroupArr: languageProfs,
			skillToolLanguageProfs,
			setValid: new Set(this._FEATURE__LANGUAGES_ALL),
			setValidAny: this._SKILL_TOOL_LANGUAGE_KEYS__LANGAUGE_ANY,
			anyAlt: "anyLanguage",
			isShort,
		});
	}

	static _summariseProfs ({profGroupArr, skillToolLanguageProfs, setValid, setValidAny, anyAlt, isShort, hoverTag}) {
		if (!profGroupArr?.length && !skillToolLanguageProfs?.length) return {summary: "", collection: []};

		const collectionSet = new Set();

		const handleProfGroup = (profGroup, {isValidate = true} = {}) => {
			let sep = ", ";

			const toJoin = Object.entries(profGroup)
				.sort(([kA], [kB]) => this._summariseProfs_sortKeys(kA, kB))
				.filter(([k, v]) => v && (!isValidate || setValid.has(k) || setValidAny.has(k)))
				.map(([k, v], i) => {
					const vMapped = this.getMappedAnyProficiency({keyAny: k, countRaw: v}) ?? v;

					if (k === "choose") {
						sep = "; ";

						const chooseProfs = vMapped.from
							.filter(s => !isValidate || setValid.has(s))
							.map(s => {
								collectionSet.add(this._summariseProfs_getCollectionKey(s, anyAlt));
								return this._summariseProfs_getEntry({str: s, isShort, hoverTag});
							});
						return `${isShort ? `${i === 0 ? "C" : "c"}hoose ` : ""}${v.count || 1} ${isShort ? `of` : `from`} ${chooseProfs.joinConjunct(", ", " or ")}`;
					}

					collectionSet.add(this._summariseProfs_getCollectionKey(k, anyAlt));
					return this._summariseProfs_getEntry({str: k, isShort, hoverTag});
				});

			return toJoin.join(sep);
		};

		const summary = [
			...(profGroupArr || [])
				// Skip validation (i.e. allow homebrew/etc.) for the specific proficiency array
				.map(profGroup => handleProfGroup(profGroup, {isValidate: false})),
			...(skillToolLanguageProfs || [])
				.map(profGroup => handleProfGroup(profGroup)),
		]
			.filter(Boolean)
			.join(` <i>or</i> `);

		return {summary, collection: [...collectionSet].sort(SortUtil.ascSortLower)};
	}

	static _summariseProfs_getCollectionKey (k, anyAlt) {
		return k === anyAlt ? "any" : k;
	}

	static _summariseProfs_sortKeys (a, b, {setValidAny = null} = {}) {
		if (a === b) return 0;
		if (a === "choose") return 2;
		if (b === "choose") return -2;
		if (setValidAny) {
			if (setValidAny.has(a)) return 1;
			if (setValidAny.has(b)) return -1;
		}
		return SortUtil.ascSort(a, b);
	}

	static _summariseProfs_getEntry ({str, isShort, hoverTag}) {
		if (!isShort && hoverTag) return `{@${hoverTag} ${str.toTitleCase()}}`;
		const [name, , displayName] = str.split("|");
		return (displayName || name).toTitleCase();
	}

	/* -------------------------------------------- */

	/**
	 * @param keyAny
	 * @param countRaw
	 * @param {?object} mappedAnyObjects
	 */
	static getMappedAnyProficiency ({keyAny, countRaw, mappedAnyObjects = null}) {
		const mappedCount = !isNaN(countRaw) ? Number(countRaw) : 1;
		if (mappedCount <= 0) return null;

		switch (keyAny) {
			case "anySkill": return {
				name: mappedCount === 1 ? `Any Skill` : `Any ${mappedCount} Skills`,
				from: this.FEATURE__SKILLS_ALL
					.map(it => ({name: it, prop: "skillProficiencies"})),
				count: mappedCount,
			};
			case "anyTool": return {
				name: mappedCount === 1 ? `Any Tool` : `Any ${mappedCount} Tools`,
				from: this.FEATURE__TOOLS_ALL
					// "anyTool" should map to "any specific tool", not "any group of tools"
					.filter(it => !this._FEATURE__TOOL_GROUPS.has(it))
					.map(it => ({name: it, prop: "toolProficiencies"})),
				count: mappedCount,
			};
			case "anyArtisansTool": return {
				name: mappedCount === 1 ? `Any Artisan's Tool` : `Any ${mappedCount} Artisan's Tools`,
				from: this.FEATURE__TOOLS_ARTISANS
					.map(it => ({name: it, prop: "toolProficiencies"})),
				count: mappedCount,
			};
			case "anyMusicalInstrument": return {
				name: mappedCount === 1 ? `Any Musical Instrument` : `Any ${mappedCount} Musical Instruments`,
				from: this.FEATURE__TOOLS_MUSICAL_INSTRUMENTS
					.map(it => ({name: it, prop: "toolProficiencies"})),
				count: mappedCount,
			};
			case "anyGamingSet": return {
				name: mappedCount === 1 ? `Any Gaming Set` : `Any ${mappedCount} Gaming Sets`,
				from: this.FEATURE__TOOLS_GAMING_SETS
					.map(it => ({name: it, prop: "toolProficiencies"})),
				count: mappedCount,
			};
			case "anyLanguage": return {
				name: mappedCount === 1 ? `Any Language` : `Any ${mappedCount} Languages`,
				...(
					mappedAnyObjects?.[keyAny]
					|| {
						from: this._FEATURE__LANGUAGES_ALL
							.map(it => ({name: it, prop: "languageProficiencies"})),
					}
				),
				count: mappedCount,
			};
			case "anyStandardLanguage": return {
				name: mappedCount === 1 ? `Any Standard Language` : `Any ${mappedCount} Standard Languages`,
				...(
					mappedAnyObjects?.[keyAny]
					|| {
						...MiscUtil.copyFast(this._FEATURE__LANGUAGES_STANDARD__CHOICE_OBJ), // Use a generic choice object, as rules state DM can allow choosing any
					}
				),
				count: mappedCount,
			};
			case "anyExoticLanguage": return {
				name: mappedCount === 1 ? `Any Exotic Language` : `Any ${mappedCount} Exotic Languages`,
				...(
					mappedAnyObjects?.[keyAny]
					|| {
						...MiscUtil.copyFast(this._FEATURE__LANGUAGES_STANDARD__CHOICE_OBJ), // Use a generic choice object, as rules state DM can allow choosing any
					}
				),
				count: mappedCount,
			};
			case "anyRareLanguage": return {
				name: mappedCount === 1 ? `Any Rare Language` : `Any ${mappedCount} Rare Languages`,
				...(
					mappedAnyObjects?.[keyAny]
					|| {
						...MiscUtil.copyFast(this._FEATURE__LANGUAGES_STANDARD__CHOICE_OBJ), // Emulate the 2014 choice rulings
					}
				),
				count: mappedCount,
			};
			case "anySavingThrow": return {
				name: mappedCount === 1 ? `Any Saving Throw` : `Any ${mappedCount} Saving Throws`,
				from: this.FEATURE__SAVING_THROWS_ALL
					.map(it => ({name: it, prop: "savingThrowProficiencies"})),
				count: mappedCount,
			};

			case "anyWeapon": throw new Error(`Property handling for "anyWeapon" is unimplemented!`);
			case "anyArmor": throw new Error(`Property handling for "anyArmor" is unimplemented!`);

			default: return null;
		}
	}

	/* -------------------------------------------- */

	static getRenderableDurationEntriesMeta (durations, {styleHint} = {}) {
		styleHint ||= VetoolsConfig.get("styleSwitcher", "style");

		const ptSrcStatus = styleHint === "classic" ? "" : `|${Parser.SRC_XPHB}`;

		let hasSubOr = false;

		const outParts = durations
			.map(duration => {
				const ptCondition = duration.condition ? ` (${duration.condition})` : "";

				switch (duration.type) {
					case "special":
						if (duration.concentration) return `{@status Concentration${ptSrcStatus}}`;
						return `Special${ptCondition}`;
					case "instant":
						return `Instantaneous${ptCondition}`;
					case "timed":
						return `${duration.concentration ? `{@status Concentration${ptSrcStatus}}, ` : ""}${duration.concentration ? "u" : duration.duration.upTo ? "U" : ""}${duration.concentration || duration.duration.upTo ? "p to " : ""}${duration.duration.amount} ${duration.duration.amount === 1 ? duration.duration.type : `${duration.duration.type}s`}${ptCondition}`;
					case "permanent": {
						if (!duration.ends) return `Permanent${ptCondition}`;

						const endsToJoin = duration.ends.map(m => Parser.spEndTypeToFull(m));
						hasSubOr = hasSubOr || endsToJoin.length > 1;
						return `Until ${endsToJoin.joinConjunct(", ", " or ")}${ptCondition}`;
					}
				}
			});

		return {
			entryDuration: `${outParts.joinConjunct(hasSubOr ? "; " : ", ", " or ")}${durations.length > 1 ? " (see below)" : ""}`,
		};
	}

	/* -------------------------------------------- */

	static hasToken (ent, {isIgnoreImplicit = false} = {}) {
		const fromEntity = ent.tokenUrl // TODO(Future) legacy; remove
			|| ent.token // An explicit token
			|| ent.tokenHref // An explicit token URL (local or external)
		;
		if (fromEntity || isIgnoreImplicit) return !!fromEntity;
		return ent.hasToken; // An implicit token
	}

	static getTokenUrl (ent, mediaDir, {isIgnoreImplicit = false, isUrlEncode = false} = {}) {
		if (ent.tokenUrl) return ent.tokenUrl; // TODO(Future) legacy; remove
		if (ent.token) return Renderer.get().getMediaUrl("img", `${mediaDir}/${ent.token.source}/${Parser.nameToTokenName(ent.token.name, {isUrlEncode})}.webp`);
		if (ent.tokenHref) return Renderer.utils.getEntryMediaUrl(ent, "tokenHref", "img", {isUrlEncode});
		if (isIgnoreImplicit) return null;
		return Renderer.get().getMediaUrl("img", `${mediaDir}/${ent.source}/${Parser.nameToTokenName(ent.name, {isUrlEncode})}.webp`);
	}
};

Renderer.redirect = class {
	static _P_LOADING_VERSION_REDIRECT_LOOKUP = null;
	static _VERSION_REDIRECT_LOOKUP = null;

	static async pInit () {
		this._P_LOADING_VERSION_REDIRECT_LOOKUP ||= DataUtil.loadJSON(`${Renderer.get().baseUrl}data/generated/gendata-tag-redirects.json`);
		const lookup = await this._P_LOADING_VERSION_REDIRECT_LOOKUP;
		this._VERSION_REDIRECT_LOOKUP ||= lookup;
	}

	static async pGetRedirectByHash (page, hash) {
		await this.pInit();
		return this.getRedirectByHash(page, hash);
	}

	static async pGetRedirectByUid (prop, uid) {
		await this.pInit();
		return this.getRedirectByUid(prop, uid);
	}

	/* -------------------------------------------- */

	static getRedirectByHash (page, hash) {
		if (!this._VERSION_REDIRECT_LOOKUP) throw new Error(`Not initialized!`);

		const fromLookup = MiscUtil.get(this._VERSION_REDIRECT_LOOKUP, page, hash);
		if (!fromLookup) return null;

		const hashNxt = fromLookup.hash || fromLookup;
		const pageNxt = fromLookup.page || page;
		const decodedNxt = UrlUtil.autoDecodeHash(hashNxt, {page: pageNxt});

		const pagePropsNxt = UrlUtil.PAGE_TO_PROPS[pageNxt] || [pageNxt];
		if (pagePropsNxt.some(prop => ExcludeUtil.isExcluded(hashNxt, prop, decodedNxt.source, {isNoCount: true}))) return null;

		return {page: pageNxt, hash: hashNxt, source: decodedNxt.source, name: decodedNxt.name};
	}

	static getRedirectByUid (prop, uid) {
		const page = UrlUtil.PROP_TO_PAGE[prop];
		if (!page) throw new Error(`Unhandled prop "${prop}"`);

		const tag = Parser.getPropTag(prop);
		const unpacked = DataUtil.proxy.unpackUid(prop, uid, tag, {isLower: true});
		const hash = UrlUtil.URL_TO_HASH_BUILDER[prop](unpacked);

		return this.getRedirectByHash(page, hash);
	}
};

Renderer.hover = class {
	static LinkMeta = class {
		constructor ({mode = "hover"}) {
			this.mode = mode;

			this.doReset();
		}

		doReset () {
			this.isAttended = false;

			this.isLoading = false;
			this.isDelayed = false;
			this.isPermanent = false;

			this.windowMeta = null;

			this._tmpEvt = null;
		}

		isHeldOpen ({mode = null} = {}) {
			if (mode != null && this.mode !== mode) return false;
			return this.isAttended || this.isPermanent;
		}

		getPopTempEvt ({evtDefault = null} = {}) {
			const evt = this._tmpEvt || evtDefault;
			this._tmpEvt = null;
			return evt;
		}
	};

	static _BAR_HEIGHT = 16;

	static _linkCache = {};
	static _eleCache = new Map();
	static _entryCache = {};
	static _isInit = false;
	static _dmScreen = null;
	static _lastId = 0;
	static _contextMenu = null;
	static _contextMenuLastClicked = null;

	static bindDmScreen (screen) { this._dmScreen = screen; }

	static _getNextId () { return ++Renderer.hover._lastId; }

	static _doInit () {
		if (Renderer.hover._isInit) return;
		Renderer.hover._isInit = true;

		document.body.addEventListener("click", () => {
			Renderer.hover.cleanTempWindows();
		});

		Renderer.hover._contextMenu = ContextUtil.getMenu([
			new ContextUtil.Action(
				"Maximize All",
				() => {
					veEm(`.ve-hoverborder[data-perm="true"]`).forEach(ele => ele.vee.attr("data-display-title", "false"));
				},
			),
			new ContextUtil.Action(
				"Minimize All",
				() => {
					veEm(`.ve-hoverborder[data-perm="true"]`).forEach(ele => ele.vee.attr("data-display-title", "true"));
				},
			),
			null,
			new ContextUtil.Action(
				"Close Others",
				() => {
					const hoverId = Renderer.hover._contextMenuLastClicked?.hoverId;
					Renderer.hover._doCloseAllWindows({hoverIdBlocklist: new Set([hoverId])});
				},
			),
			new ContextUtil.Action(
				"Close All",
				() => Renderer.hover._doCloseAllWindows(),
			),
		]);
	}

	/* -------------------------------------------- */

	static cleanTempWindows () {
		for (const [key, meta] of Renderer.hover._eleCache.entries()) {
			// If this is an element-less "permanent" show (i.e. a "predefined" window) which has been closed
			if (!meta.isPermanent && meta.windowMeta && typeof key === "number") {
				meta.windowMeta.doClose();
				Renderer.hover._eleCache.delete(key);
				continue;
			}

			if (!meta.isPermanent && meta.windowMeta && !document.body.contains(key)) {
				meta.windowMeta.doClose();
				continue;
			}

			if (meta.mode !== "hover") continue;

			if (!meta.isPermanent && meta.isAttended && meta.windowMeta) {
				// Check if any elements have failed to clear their hovering status on mouse move
				const bounds = key.getBoundingClientRect();
				if (EventUtil._mouseX < bounds.x
					|| EventUtil._mouseY < bounds.y
					|| EventUtil._mouseX > bounds.x + bounds.width
					|| EventUtil._mouseY > bounds.y + bounds.height) {
					meta.windowMeta.doClose();
				}
			}
		}
	}

	/* -------------------------------------------- */

	static _doCloseAllWindows ({hoverIdBlocklist = null} = {}) {
		Object.entries(Renderer.hover._WINDOW_METAS)
			.filter(([hoverId, meta]) => hoverIdBlocklist == null || !hoverIdBlocklist.has(Number(hoverId)))
			.forEach(([, meta]) => meta.doClose());
	}

	/* -------------------------------------------- */

	static _getSetMeta ({key, mode}) {
		if (!Renderer.hover._eleCache.has(key)) Renderer.hover._eleCache.set(key, new Renderer.hover.LinkMeta({mode}));
		return Renderer.hover._eleCache.get(key);
	}

	static _handleGenericShowStart ({ele, mode, isPermanent = false}) {
		Renderer.hover.cleanTempWindows();

		const meta = Renderer.hover._getSetMeta({key: ele, mode});

		// Another handler has this element
		if (meta.isHeldOpen()) return null;
		if (meta.isLoading && meta.mode !== mode) return null;

		meta.mode = mode;
		meta.isAttended = true;

		// (Re-entering refreshes attendance without starting another load)
		if (meta.isLoading) return null;

		meta.isLoading = true;
		meta.isPermanent ||= isPermanent;

		// Set the cursor to a waiting spinner
		ele.style.cursor = "progress";

		return meta;
	}

	static _doPredefinedShowStart ({entryId}) {
		Renderer.hover.cleanTempWindows();

		const meta = Renderer.hover._getSetMeta({key: entryId});

		meta.isPermanent = true;

		return meta;
	}

	static getHoverElementAttributes (
		{
			page,
			source,
			hash,
			preloadId = null,
			isFauxPage = false,
			isAllowRedirect = false,
		},
	) {
		return [
			`onmouseover="Renderer.hover.pHandleLinkMouseOver(event, this)"`,
			`onmouseleave="Renderer.hover.handleLinkMouseLeave(event, this)"`,
			`onmousemove="Renderer.hover.handleLinkMouseMove(event, this)"`,
			`onclick="Renderer.hover.handleLinkClick(event, this${isFauxPage ? `, {isForceOpenPermanent: true}` : ``})"`,
			`onwheel="Renderer.hover.handleLinkWheel(event, this)"`,
			`ondragstart="Renderer.hover.handleLinkDragStart(event, this)"`,
			`data-vet-page="${page.qq()}"`,
			`data-vet-source="${source.qq()}"`,
			`data-vet-hash="${hash.qq()}"`,
			preloadId != null ? `data-vet-preload-id="${`${preloadId}`.qq()}"` : "",
			isFauxPage ? `data-vet-is-faux-page="true"` : "",
			isAllowRedirect ? `data-vet-is-allow-redirect="true"` : "",
			Renderer.hover.getPreventTouchString(),
		]
			.filter(Boolean)
			.join(" ");
	}

	static getLinkElementData (ele) {
		return {
			page: ele.getAttribute("data-vet-page"),
			source: ele.getAttribute("data-vet-source"),
			hash: ele.getAttribute("data-vet-hash"),
			preloadId: ele.getAttribute("data-vet-preload-id"),
			isFauxPage: ele.getAttribute("data-vet-is-faux-page") === "true",
			isAllowRedirect: ele.getAttribute("data-vet-is-allow-redirect") === "true",
		};
	}

	// (Baked into render strings)
	static async pHandleLinkMouseOver (evt, ele, opts) {
		this._doInit();

		const meta = this._handleGenericShowStart({
			ele,
			mode: "hover",
			isPermanent: !!evt.shiftKey || !!opts?.isForceOpenPermanent,
		});
		if (meta == null) return;

		const contentInfo = await this._pGetLinkContentInfo({
			ele,
			opts,
			isFluff: EventUtil.isCtrlMetaKey(evt),
		});
		meta.isLoading = false;

		if (opts?.isDelay) {
			meta.isDelayed = true;
			ele.style.cursor = "help";
			await MiscUtil.pDelay(1100);
			meta.isDelayed = false;
		}

		ele.style.cursor = "";

		if (!meta.isHeldOpen({mode: "hover"})) return;

		const position = this.getWindowPositionFromEvent(meta.getPopTempEvt({evtDefault: evt}), {isPreventFlicker: !meta.isPermanent});

		this._doShowContent({
			meta,
			contentInfo,
			position,
			win: evt.view?.window,
		});
	}

	static _pHandleLinkFocus_isActiveFocus ({ele}) {
		return ele.ownerDocument.activeElement === ele;
	}

	static async pHandleLinkFocus (evt, ele, opts) {
		this._doInit();

		const meta = this._handleGenericShowStart({
			ele,
			mode: "focus",
		});
		if (meta == null) return;

		const contentInfo = await this._pGetLinkContentInfo({
			ele,
			opts,
			isFluff: false,
		});
		meta.isLoading = false;

		ele.style.cursor = "";

		if (!this._pHandleLinkFocus_isActiveFocus({ele})) return;

		if (!meta.isHeldOpen({mode: "focus"})) return;

		const {left, top} = ele.getBoundingClientRect();
		const position = opts?.position ?? this.getWindowPositionExactVisibleBottom(left, top, {evt});

		this._doShowContent({
			meta,
			contentInfo,
			position,
			win: evt.view?.window,
		});
	}

	/* -------------------------------------------- */

	static async _pGetLinkContentInfo_pGetLinkVersionRedirectMeta ({page, source, hash, preloadId, customHashId, isAllowRedirect}) {
		if (!isAllowRedirect || preloadId || customHashId) return null;
		if (VetoolsConfig.get("styleSwitcher", "style") === "classic") return null;

		return Renderer.redirect.pGetRedirectByHash(page, hash);
	}

	static _pGetLinkContentInfo_doVerifyToRender ({toRender, page, source, hash, preloadId, customHashId, isFluff}) {
		if (toRender) return;
		throw new Error(`Failed to load renderable content for: page="${page}" source="${source}" hash="${hash}" preloadId="${preloadId}" customHashId="${customHashId}" isFluff="${isFluff}"`);
	}

	static async _pGetLinkContentInfo_pGetToRender ({isFluff, page, source, hash, preloadId, customHashId}) {
		// FIXME(Future) remove in favor of `customHashId`
		if (preloadId != null) {
			let toRender;

			switch (page) {
				case UrlUtil.PG_BESTIARY: {
					const {_scaledCr: scaledCr, _scaledSpellSummonLevel: scaledSpellSummonLevel, _scaledClassSummonLevel: scaledClassSummonLevel} = Renderer.monster.getUnpackedCustomHashId(preloadId);

					const baseMon = await DataLoader.pCacheAndGet(page, source, hash);
					if (scaledCr != null) {
						toRender = await ScaleCreature.scale(baseMon, scaledCr);
					} else if (scaledSpellSummonLevel != null) {
						toRender = await ScaleSpellSummonedCreature.scale(baseMon, scaledSpellSummonLevel);
					} else if (scaledClassSummonLevel != null) {
						toRender = await ScaleClassSummonedCreature.scale(baseMon, scaledClassSummonLevel);
					}
					break;
				}

				default: throw new Error("Unimplemented!");
			}

			this._pGetLinkContentInfo_doVerifyToRender({toRender, page, source, hash, preloadId, customHashId, isFluff});
			return toRender;
		}

		if (customHashId) {
			const ent = await DataLoader.pCacheAndGet(page, source, hash);
			const toRender = await Renderer.hover.pApplyCustomHashId(page, ent, customHashId);
			this._pGetLinkContentInfo_doVerifyToRender({toRender, page, source, hash, preloadId, customHashId, isFluff});
			return toRender;
		}

		if (isFluff) {
			const entity = await DataLoader.pCacheAndGet(page, source, hash);
			if (!entity) return null;
			// (Note that we don't verify, as no-fluff is valid)
			return Renderer.utils.pGetProxyFluff({entity});
		}

		const toRender = await DataLoader.pCacheAndGet(page, source, hash);
		this._pGetLinkContentInfo_doVerifyToRender({toRender, page, source, hash, preloadId, customHashId, isFluff});
		return toRender;
	}

	static async _pGetLinkContentInfo ({ele, opts, isFluff}) {
		const linkData = Renderer.hover._pGetLinkContentInfo_getLinkData({ele, opts});
		let {page, source, hash} = linkData;
		const {preloadId, customHashId, isFauxPage, isAllowRedirect} = linkData;

		const redirectMeta = await this._pGetLinkContentInfo_pGetLinkVersionRedirectMeta({page, source, hash, preloadId, customHashId, isAllowRedirect});
		if (redirectMeta != null) ({page, source, hash} = redirectMeta);

		const toRender = await this._pGetLinkContentInfo_pGetToRender({isFluff, page, source, hash, preloadId, customHashId});

		return {page, source, hash, isFauxPage, isFluff, toRender};
	}

	/* -------------------------------------------- */

	static _doShowContent ({meta, contentInfo, position, win}) {
		if (meta.windowMeta) {
			meta.windowMeta.setPosition(position);
			return;
		}

		const {page, source, hash, isFauxPage, isFluff, toRender} = contentInfo;
		const eleContent = isFluff
			? Renderer.hover.getHoverContent_fluff(page, toRender)
			: Renderer.hover.getHoverContent_stats(page, toRender);

		// FIXME(Future) replace this with something maintainable
		const compactReferenceData = {
			page,
			source,
			hash,
		};

		meta.windowMeta = Renderer.hover.getShowWindow(
			eleContent,
			position,
			{
				title: toRender?.name || "",
				isPermanent: meta.isPermanent,
				pageUrl: isFauxPage ? null : `${Renderer.get().baseUrl}${page}#${hash}`,
				cbClose: () => meta.doReset(),
				isBookContent: Renderer.hover.isBookContentStyledPage(page),
				compactReferenceData,
				sourceData: toRender,
			},
		);

		if (!isFluff && !win?._IS_POPOUT) {
			const fnBind = Renderer.hover.getFnBindListenersCompact(page);
			if (fnBind && toRender) fnBind(toRender, eleContent);
		}
	}

	static _pGetLinkContentInfo_getLinkData ({ele, opts}) {
		if (opts?.isSpecifiedLinkData) {
			return {
				page: opts.page,
				source: opts.source,
				hash: opts.hash,
				preloadId: opts.preloadId,
				customHashId: opts.customHashId,
				isFauxPage: !!opts.isFauxPage,
				isAllowRedirect: !!opts.isAllowRedirect,
			};
		}

		return Renderer.hover.getLinkElementData(ele);
	}

	// (Baked into render strings)
	static handleInlineMouseOver (evt, ele, entry, opts) {
		Renderer.hover._doInit();

		entry = entry || JSON.parse(ele.getAttribute("data-vet-entry"));

		let meta = Renderer.hover._handleGenericShowStart({ele, mode: "hover", isPermanent: !!evt.shiftKey});
		if (meta == null) return;

		meta.isLoading = false;

		// Reset cursor
		ele.style.cursor = "";

		// Check if we're still hovering the entity
		if (!meta.isHeldOpen({mode: "hover"})) return;

		const win = (evt.view || {}).window;

		if (meta.windowMeta && !meta.isPermanent) {
			meta.windowMeta.doClose();
			meta.windowMeta = null;
		}

		meta.windowMeta = Renderer.hover.getShowWindow(
			Renderer.hover.getHoverContent_generic(entry, opts),
			Renderer.hover.getWindowPositionFromEvent(meta.getPopTempEvt({evtDefault: evt}), {isPreventFlicker: !meta.isPermanent}),
			{
				title: entry?.name || "",
				isPermanent: meta.isPermanent,
				pageUrl: null,
				cbClose: () => meta.doReset(),
				isBookContent: true,
				sourceData: entry,
			},
		);
	}

	static _handleLinkLeave (ele, meta, {mode}) {
		if (meta.mode !== mode) return;

		meta.isAttended = false;

		if (meta.isHeldOpen()) return;

		ele.style.cursor = "";

		if (!meta.windowMeta) return;
		meta.windowMeta.doClose();
		meta.windowMeta = null;
	}

	// (Baked into render strings)
	static handleLinkMouseLeave (evt, ele) {
		const meta = Renderer.hover._eleCache.get(ele);

		// Early-exit -- Plutonium binds this as a global `mouseout`, so avoid
		//   handling any element which we are not explicitly tracking.
		if (!meta || meta.mode !== "hover") return;

		ele.style.cursor = "";

		if (meta.isPermanent) return;

		if (evt.shiftKey) {
			meta.isPermanent = true;
			meta.windowMeta?.setIsPermanent(true);
			return;
		}

		Renderer.hover._handleLinkLeave(ele, meta, {mode: "hover"});
	}

	static handleLinkBlur (evt, ele) {
		const meta = Renderer.hover._eleCache.get(ele);
		if (!meta) return;

		Renderer.hover._handleLinkLeave(ele, meta, {mode: "focus"});
	}

	// (Baked into render strings)
	static handleLinkMouseMove (evt, ele) {
		const meta = Renderer.hover._eleCache.get(ele);

		if (!meta || meta.mode !== "hover") return;

		if (meta.isPermanent) return;

		// If loading has finished, but we're not displaying the element yet (e.g. because it has been delayed)
		if (meta.isDelayed) {
			meta._tmpEvt = evt;
			return;
		}

		if (!meta.windowMeta) return;

		meta.windowMeta.setPosition(Renderer.hover.getWindowPositionFromEvent(evt, {isPreventFlicker: !evt.shiftKey && !meta.isPermanent}));

		if (evt.shiftKey && !meta.isPermanent) {
			meta.isPermanent = true;
			meta.windowMeta.setIsPermanent(true);
		}
	}

	/**
	 * (Baked into render strings)
	 * @param evt
	 * @param ele
	 * @param entryId
	 * @param [opts]
	 * @param [opts.isBookContent]
	 * @param [opts.isLargeBookContent]
	 */
	static handlePredefinedMouseOver (evt, ele, entryId, opts) {
		opts = opts || {};

		const meta = Renderer.hover._handleGenericShowStart({ele, mode: "hover", isPermanent: !!evt.shiftKey});
		if (meta == null) return;

		Renderer.hover.cleanTempWindows();

		const toRender = Renderer.hover._entryCache[entryId];

		meta.isLoading = false;
		// Check if we're still hovering the entity
		if (!meta.isHeldOpen({mode: "hover"})) return;

		meta.windowMeta = Renderer.hover.getShowWindow(
			Renderer.hover.getHoverContent_generic(toRender, opts),
			Renderer.hover.getWindowPositionFromEvent(evt, {isPreventFlicker: !meta.isPermanent}),
			{
				title: toRender.data && toRender.data.hoverTitle != null ? toRender.data.hoverTitle : toRender.name,
				isPermanent: meta.isPermanent,
				cbClose: () => meta.doReset(),
				sourceData: toRender,
			},
		);

		// Reset cursor
		ele.style.cursor = "";
	}

	static handleLinkClick (evt, ele, {isForceOpenPermanent = false} = {}) {
		// Open faux pages as permanent hover windows
		if (isForceOpenPermanent) {
			Renderer.hover.pHandleLinkMouseOver(evt, ele, {isForceOpenPermanent});
		}

		// Close the window (if not permanent)
		// Note that this prevents orphan windows when e.g. clicking a specific variant on an Items page magicvariant
		Renderer.hover.handleLinkMouseLeave(evt, ele);
	}

	static handleLinkWheel (evt, ele) {
		if (!evt.altKey) return;

		const meta = Renderer.hover._eleCache.get(ele);
		if (!meta || meta.isPermanent) return;

		if (!meta.windowMeta) return;

		evt.stopPropagation();
		evt.preventDefault();

		const {deltaPixelsX, deltaPixelsY} = EventUtil.getDeltaPixels(evt);

		meta.windowMeta.mutScroll({deltaPixelsX, deltaPixelsY});
	}

	// (Baked into render strings)
	static handleLinkDragStart (evt, ele) {
		// Close the window
		Renderer.hover.handleLinkMouseLeave(evt, ele);

		const {page, source, hash} = Renderer.hover.getLinkElementData(ele);
		const meta = {
			type: VeCt.DRAG_TYPE_IMPORT,
			page,
			source,
			hash,
		};
		evt.dataTransfer.setData("application/json", JSON.stringify(meta));
	}

	static doPredefinedShow (entryId, opts) {
		opts = opts || {};

		const meta = Renderer.hover._doPredefinedShowStart({entryId});
		if (meta == null) return;

		Renderer.hover.cleanTempWindows();

		const toRender = Renderer.hover._entryCache[entryId];

		meta.windowMeta = Renderer.hover.getShowWindow(
			Renderer.hover.getHoverContent_generic(toRender, opts),
			Renderer.hover.getWindowPositionExact((window.innerWidth / 2) - (Renderer.hover._DEFAULT_WIDTH_PX / 2), 100),
			{
				title: toRender.data && toRender.data.hoverTitle != null ? toRender.data.hoverTitle : toRender.name,
				isPermanent: meta.isPermanent,
				cbClose: () => meta.doReset(),
				sourceData: toRender,
			},
		);
	}

	// (Baked into render strings)
	static handlePredefinedMouseLeave (evt, ele) { return Renderer.hover.handleLinkMouseLeave(evt, ele); }

	// (Baked into render strings)
	static handlePredefinedMouseMove (evt, ele) { return Renderer.hover.handleLinkMouseMove(evt, ele); }

	static _WINDOW_POSITION_PROPS_FROM_EVENT = [
		"isFromBottom",
		"isFromRight",
		"clientX",
		"window",
		"isPreventFlicker",
		"bcr",
	];

	static getWindowPositionFromEvent (evt, {isPreventFlicker = false} = {}) {
		const ele = evt.target;
		const win = evt?.view?.window || window;

		const bcr = ele.getBoundingClientRect().toJSON();

		const isFromBottom = bcr.top > win.innerHeight / 2;
		const isFromRight = bcr.left > win.innerWidth / 2;

		return {
			mode: "autoFromElement",
			isFromBottom,
			isFromRight,
			clientX: EventUtil.getClientX(evt),
			window: win,
			isPreventFlicker,
			bcr,
		};
	}

	/**
	 * @param x
	 * @param y
	 * @param [opts]
	 * @param {?Event} [opts.evt]
	 * @param {?number} [opts.offsetX]
	 * @param {?number} [opts.offsetY]
	 */
	static getWindowPositionExact (x, y, {evt = null, offsetX = null, offsetY = null} = {}) {
		return {
			window: evt?.view?.window || window,
			mode: "exact",
			x,
			y,
			offsetX,
			offsetY,
		};
	}

	static getWindowPositionExactRight (x, y, {evt = null, offsetX = null} = {}) {
		return {
			...Renderer.hover.getWindowPositionExact(x, y, {evt, offsetX}),
			mode: "exactRight",
		};
	}

	static getWindowPositionExactVisibleBottom (x, y, {evt = null, offsetX = null, offsetY = null} = {}) {
		return {
			...Renderer.hover.getWindowPositionExact(x, y, {evt, offsetX, offsetY}),
			mode: "exactVisibleBottom",
		};
	}

	static _WINDOW_METAS = {};
	static MIN_Z_INDEX = 200;
	static _MAX_Z_INDEX = 300;
	static _DEFAULT_WIDTH_PX = 600;
	static _BODY_SCROLLER_WIDTH_PX = 15;

	static _getZIndex () {
		const zIndices = Object.values(Renderer.hover._WINDOW_METAS).map(it => it.zIndex);
		if (!zIndices.length) return Renderer.hover.MIN_Z_INDEX;
		return Math.max(...zIndices);
	}

	static _getNextZIndex (hoverId) {
		const cur = Renderer.hover._getZIndex();
		// If we're already the highest index, continue to use this index
		if (hoverId != null && Renderer.hover._WINDOW_METAS[hoverId].zIndex === cur) return cur;
		// otherwise, go one higher
		const out = cur + 1;

		// If we've broken through the max z-index, try to free up some z-indices
		if (out > Renderer.hover._MAX_Z_INDEX) {
			const sortedWindowMetas = Object.entries(Renderer.hover._WINDOW_METAS)
				.sort(([kA, vA], [kB, vB]) => SortUtil.ascSort(vA.zIndex, vB.zIndex));

			if (sortedWindowMetas.length >= (Renderer.hover._MAX_Z_INDEX - Renderer.hover.MIN_Z_INDEX)) {
				// If we have too many window open, collapse them into one z-index
				sortedWindowMetas.forEach(([k, v]) => {
					v.setZIndex(Renderer.hover.MIN_Z_INDEX);
				});
			} else {
				// Otherwise, ensure one consistent run from min to max z-index
				sortedWindowMetas.forEach(([k, v], i) => {
					v.setZIndex(Renderer.hover.MIN_Z_INDEX + i);
				});
			}

			return Renderer.hover._getNextZIndex(hoverId);
		} else return out;
	}

	static _isIntersectRect (r1, r2) {
		return r1.left <= r2.right
			&& r2.left <= r1.right
			&& r1.top <= r2.bottom
			&& r2.top <= r1.bottom;
	}

	/* -------------------------------------------- */

	static async pDoShowBrowserWindow (eleContent, opts) {
		eleContent = veE({ele: eleContent});

		const dimensions = opts.fnGetPopoutSize ? opts.fnGetPopoutSize() : {width: 600, height: eleContent.vee.outerHeight()};
		const win = window.open(
			"",
			opts.title || "",
			`width=${dimensions.width},height=${dimensions.height}location=0,menubar=0,status=0,titlebar=0,toolbar=0`,
		);

		// If this is a new window, bootstrap general page elements/variables.
		// Otherwise, we can skip straight to using the window.
		if (!win._IS_POPOUT) {
			win._IS_POPOUT = true;
			win.document.write(`
				<!DOCTYPE html>
				<html lang="en" class="ve-popwindow ${typeof styleSwitcher !== "undefined" ? styleSwitcher.getClassNamesStyleTheme() : ""}"><head>
					<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
					<title>${opts.title}</title>
					${[...document.querySelectorAll(`link[rel="stylesheet"][href]`)].map(ele => ele.outerHTML).join("\n")}
					<!-- Favicons -->
					<link rel="icon" type="image/svg+xml" href="favicon.svg">
					<link rel="icon" type="image/png" sizes="256x256" href="favicon-256x256.png">
					<link rel="icon" type="image/png" sizes="144x144" href="favicon-144x144.png">
					<link rel="icon" type="image/png" sizes="128x128" href="favicon-128x128.png">
					<link rel="icon" type="image/png" sizes="64x64" href="favicon-64x64.png">
					<link rel="icon" type="image/png" sizes="48x48" href="favicon-48x48.png">
					<link rel="icon" type="image/png" sizes="32x32" href="favicon-32x32.png">
					<link rel="icon" type="image/png" sizes="16x16" href="favicon-16x16.png">

					<!-- Chrome Web App Icons -->
					<link rel="manifest" href="manifest.webmanifest">
					<meta name="application-name" content="5etools">
					<meta name="theme-color" content="#006bc4">

					<!-- Windows Start Menu tiles -->
					<meta name="msapplication-config" content="browserconfig.xml"/>
					<meta name="msapplication-TileColor" content="#006bc4">

					<!-- Apple Touch Icons -->
					<link rel="apple-touch-icon" sizes="180x180" href="apple-touch-icon-180x180.png">
					<link rel="apple-touch-icon" sizes="360x360" href="apple-touch-icon-360x360.png">
					<link rel="apple-touch-icon" sizes="167x167" href="apple-touch-icon-167x167.png">
					<link rel="apple-touch-icon" sizes="152x152" href="apple-touch-icon-152x152.png">
					<link rel="apple-touch-icon" sizes="120x120" href="apple-touch-icon-120x120.png">
					<meta name="apple-mobile-web-app-title" content="5etools">

					<!-- macOS Safari Pinned Tab and Touch Bar -->
					<link rel="mask-icon" href="safari-pinned-tab.svg" color="#006bc4">

					${PrereleaseUtil.getPopoutStyleElementHtml()}
					${BrewUtil2.getPopoutStyleElementHtml()}

					<style>
						html, body { width: 100%; height: 100%; }
						body { overflow-y: scroll; }
						.ve-hwin--popout { max-width: 100%; max-height: 100%; box-shadow: initial; width: 100%; overflow-y: auto; }
					</style>
				</head><body class="ve-rd__body-popout">
				<div class="ve-hwin hoverbox--popout ve-hwin--popout"></div>
				<script type="text/javascript" defer src="js/parser.js"></script>
				<script type="text/javascript" defer src="js/utils.js"></script>
				</body></html>
			`);

			win.Renderer = Renderer;

			win.document.close();

			win._wrpHoverContent = veE({ele: win.document}).vee.find(`.hoverbox--popout`);

			window.addEventListener("beforeunload", () => win.close());
		}

		let cpyEleContent;
		if (opts.pFnGetPopoutContent) {
			cpyEleContent = await opts.pFnGetPopoutContent();
		} else {
			// TODO(jquery) consider implementing .clonee; consider cloning registered event handlers
			cpyEleContent = veE({ele: eleContent.cloneNode(true)});
		}

		win._wrpHoverContent.innerHTML = "";
		cpyEleContent.vee.appendTo(win._wrpHoverContent);

		return win;
	}

	/* -------------------------------------------- */

	static _DRAG_TYP_NONE = 0;
	static _DRAG_TYP_RESIZE_NE = 1;
	static _DRAG_TYP_RESIZE_E = 2;
	static _DRAG_TYP_RESIZE_SE = 3;
	static _DRAG_TYP_RESIZE_S = 4;
	static _DRAG_TYP_RESIZE_SW = 5;
	static _DRAG_TYP_RESIZE_W = 6;
	static _DRAG_TYP_RESIZE_NW = 7;
	static _DRAG_TYP_RESIZE_N = 8;
	static _DRAG_TYP_MOVE = 9;

	/**
	 * @param eleContent Content to append to the window.
	 * @param position The position of the window. Can be specified in various formats.
	 * @param [opts] Options object.
	 * @param [opts.isPermanent] If the window should have the expanded toolbar of a "permanent" window.
	 * @param [opts.title] The window title.
	 * @param [opts.isBookContent] If the hover window contains book content. Affects the styling of borders.
	 * @param [opts.pageUrl] A page URL which is navigable via a button in the window header
	 * @param [opts.cbClose] Callback to run on window close.
	 * @param [opts.width] An initial width for the window.
	 * @param [opts.height] An initial height fot the window.
	 * @param [opts.pFnGetPopoutContent] A function which loads content for this window when it is popped out.
	 * @param [opts.fnGetPopoutSize] A function which gets a `{width: ..., height: ...}` object with dimensions for a
	 * popout window.
	 * @param [opts.isPopout] If the window should be immediately popped out.
	 * @param [opts.compactReferenceData] Reference (e.g. page/source/hash/others) which can be used to load the contents into the DM screen.
	 * @param [opts.sourceData] Source JSON (as raw as possible) used to construct this popout.
	 * @param [opts.isResizeOnlyWidth]
	 * @param [opts.isHideBottomBorder]
	 */
	static getShowWindow (eleContent, position, opts) {
		if (eleContent instanceof DocumentFragment) throw new Error(`Expected "eleContent" to be a node, but was a "DocumentFragment"!`);

		opts = opts || {};
		const {isHideBottomBorder, isResizeOnlyWidth} = opts;

		if (isHideBottomBorder && !isResizeOnlyWidth) throw new Error(`"isHideBottomBorder" option requires "isResizeOnlyWidth"!`);

		Renderer.hover._doInit();

		const initialWidth = opts.width == null ? Renderer.hover._DEFAULT_WIDTH_PX : opts.width;
		const initialZIndex = Renderer.hover._getNextZIndex();

		const eleHov = veT`<div class="ve-hwin"></div>`
			.vee.css({
				"right": `${-initialWidth}px`,
				"width": `${initialWidth}px`,
				"zIndex": initialZIndex,
			});
		const wrpContent = veT`<div class="ve-hwin__wrp-table"></div>`;
		if (opts.height != null) wrpContent.vee.css("height", `${opts.height}px`);
		const hovTitle = veT`<span class="ve-window-title ve-min-w-0 ve-overflow-ellipsis" title="${`${opts.title || ""}`.qq()}">${opts.title || ""}</span>`;

		const hoverWindow = {};
		const hoverId = Renderer.hover._getNextId();
		Renderer.hover._WINDOW_METAS[hoverId] = hoverWindow;
		const drag = {};
		const eventChannel = new EventTarget();
		const fnsCleanup = [];

		const brdrTopRightResize = veT`<div class="ve-hoverborder__resize-ne ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_NE, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_NE, isResizeOnlyWidth}));
		if (isResizeOnlyWidth) brdrTopRightResize.vee.hide();

		const brdrRightResize = veT`<div class="ve-hoverborder__resize-e ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_E, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_E, isResizeOnlyWidth}));

		const brdrBottomRightResize = veT`<div class="ve-hoverborder__resize-se ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_SE, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_SE, isResizeOnlyWidth}));
		if (isResizeOnlyWidth) brdrBottomRightResize.vee.hide();

		const brdrBtmResize = veT`<div class="ve-hoverborder__resize-s ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_S, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_S, isResizeOnlyWidth}));
		if (isResizeOnlyWidth) brdrBtmResize.vee.hide();

		const brdrBtm = veT`<div class="ve-hoverborder ve-hoverborder--btm ${opts.isBookContent ? "ve-hoverborder--book" : ""} ve-touch-action-none">${brdrBtmResize}</div>`;
		if (isHideBottomBorder) brdrBtm.vee.hide();

		const brdrBtmLeftResize = veT`<div class="ve-hoverborder__resize-sw ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_SW, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_SW, isResizeOnlyWidth}));
		if (isResizeOnlyWidth) brdrBtmLeftResize.vee.hide();

		const brdrLeftResize = veT`<div class="ve-hoverborder__resize-w ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_W, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_W, isResizeOnlyWidth}));

		const brdrTopLeftResize = veT`<div class="ve-hoverborder__resize-nw ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_NW, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_NW, isResizeOnlyWidth}));
		if (isResizeOnlyWidth) brdrTopLeftResize.vee.hide();

		const brdrTopResize = veT`<div class="ve-hoverborder__resize-n ve-touch-action-none"></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_N, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_RESIZE_N, isResizeOnlyWidth}));
		if (isResizeOnlyWidth) brdrTopResize.vee.hide();

		const brdrTop = veT`<div class="ve-hoverborder ve-hoverborder--top ${opts.isBookContent ? "ve-hoverborder--book" : ""} ve-touch-action-none" ${opts.isPermanent ? `data-perm="true"` : ""}></div>`
			.vee.onn("mousedown", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_MOVE, isResizeOnlyWidth}))
			.vee.onn("touchstart", (evt) => Renderer.hover._getShowWindow_handleDragMousedown({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type: this._DRAG_TYP_MOVE, isResizeOnlyWidth}))
			.vee.onn("contextmenu", (evt) => {
				Renderer.hover._contextMenuLastClicked = {
					hoverId,
				};
				ContextUtil.pOpenMenu(evt, Renderer.hover._contextMenu);
			});

		/* ----- */

		const fnMouseUp = (evt) => {
			if (drag.type === this._DRAG_TYP_NONE) return;

			if (drag.type !== this._DRAG_TYP_MOVE) {
				wrpContent.vee.css("max-height", "");
				eleHov.vee.css({"max-width": ""});
			}
			Renderer.hover._getShowWindow_adjustPosition({eleHov, wrpContent, position, eventChannel});

			if (drag.type === this._DRAG_TYP_MOVE) {
				// handle mobile button touches
				if (EventUtil.isUsingTouch() && evt.target.classList.contains("ve-hwin__top-border-icon")) {
					evt.preventDefault();
					drag.type = this._DRAG_TYP_NONE;
					veE(evt.target).vee.trigger("click");
					return;
				}

				// handle DM screen integration
				if (this._dmScreen && opts.compactReferenceData) {
					const panel = this._dmScreen.getPanelPx(EventUtil.getClientX(evt), EventUtil.getClientY(evt));
					if (!panel) return;
					this._dmScreen.setHoveringPanel(panel);
					const target = panel.getAddButtonPos();

					if (Renderer.hover._getShowWindow_isOverHoverTarget({evt, target})) {
						panel.doPopulate_Stats(opts.compactReferenceData.page, opts.compactReferenceData.source, opts.compactReferenceData.hash);
						Renderer.hover._getShowWindow_doClose({eleHov, position, fnsCleanup, hoverId, opts, hoverWindow});
					}
					this._dmScreen.resetHoveringButton();
				}
			}

			drag.type = this._DRAG_TYP_NONE;
		};

		const fnOnMouseMove = (evt) => {
			const args = {wrpContent, eleHov, drag, evt};
			switch (drag.type) {
				case this._DRAG_TYP_RESIZE_NE: Renderer.hover._getShowWindow_handleNorthDrag(args); Renderer.hover._getShowWindow_handleEastDrag(args); break;
				case this._DRAG_TYP_RESIZE_E: Renderer.hover._getShowWindow_handleEastDrag(args); break;
				case this._DRAG_TYP_RESIZE_SE: Renderer.hover._getShowWindow_handleSouthDrag(args); Renderer.hover._getShowWindow_handleEastDrag(args); break;
				case this._DRAG_TYP_RESIZE_S: Renderer.hover._getShowWindow_handleSouthDrag(args); break;
				case this._DRAG_TYP_RESIZE_SW: Renderer.hover._getShowWindow_handleSouthDrag(args); Renderer.hover._getShowWindow_handleWestDrag(args); break;
				case this._DRAG_TYP_RESIZE_W: Renderer.hover._getShowWindow_handleWestDrag(args); break;
				case this._DRAG_TYP_RESIZE_NW: Renderer.hover._getShowWindow_handleNorthDrag(args); Renderer.hover._getShowWindow_handleWestDrag(args); break;
				case this._DRAG_TYP_RESIZE_N: Renderer.hover._getShowWindow_handleNorthDrag(args); break;
				case this._DRAG_TYP_MOVE: {
					const diffX = drag.startX - EventUtil.getClientX(evt);
					const diffY = drag.startY - EventUtil.getClientY(evt);
					eleHov
						.vee.css({
							"left": `${drag.baseLeft - diffX}px`,
							"top": `${drag.baseTop - diffY}px`,
						});
					drag.startX = EventUtil.getClientX(evt);
					drag.startY = EventUtil.getClientY(evt);
					drag.baseTop = parseFloat(eleHov.vee.css("top").slice(0, -2));
					drag.baseLeft = parseFloat(eleHov.vee.css("left").slice(0, -2));

					// handle DM screen integration
					if (this._dmScreen) {
						const panel = this._dmScreen.getPanelPx(EventUtil.getClientX(evt), EventUtil.getClientY(evt));
						if (!panel) return;
						this._dmScreen.setHoveringPanel(panel);
						const target = panel.getAddButtonPos();

						if (Renderer.hover._getShowWindow_isOverHoverTarget({evt, target})) this._dmScreen.setHoveringButton(panel);
						else this._dmScreen.resetHoveringButton();
					}
					break;
				}
			}
		};

		position.window.document.addEventListener("mouseup", fnMouseUp);
		position.window.document.addEventListener("touchend", fnMouseUp);
		position.window.document.addEventListener("mousemove", fnOnMouseMove);
		position.window.document.addEventListener("touchmove", fnOnMouseMove);
		fnsCleanup
			.push(() => {
				position.window.document.removeEventListener("mouseup", fnMouseUp);
				position.window.document.removeEventListener("touchend", fnMouseUp);
				position.window.document.removeEventListener("mousemove", fnOnMouseMove);
				position.window.document.removeEventListener("touchmove", fnOnMouseMove);
			});

		/* ----- */

		const fnOnResize = () => Renderer.hover._getShowWindow_adjustPosition({eleHov, wrpContent, position, eventChannel});

		position.window.addEventListener("resize", fnOnResize);
		fnsCleanup
			.push(() => {
				position.window.removeEventListener("resize", fnOnResize);
			});

		/* ----- */

		brdrTop.vee.attr("data-display-title", false);
		brdrTop.vee.onn("dblclick", () => Renderer.hover._getShowWindow_doToggleMinimizedMaximized({brdrEleTop: brdrTop, eleHov}));
		brdrTop.vee.appends(hovTitle);
		const brdEleTopRhs = veT`<div class="ve-flex ve-ml-auto ve-no-shrink"></div>`.vee.appendTo(brdrTop);

		if (opts.pageUrl && !position.window._IS_POPOUT && !Renderer.get().isInternalLinksDisabled()) {
			const btnGotoPage = veT`<a class="ve-hwin__top-border-icon glyphicon glyphicon-modal-window" title="Go to Page" href="${opts.pageUrl}"></a>`
				.vee.appendTo(brdEleTopRhs);
		}

		if (!position.window._IS_POPOUT && !opts.isPopout) {
			const btnPopout = veT`<span class="ve-hwin__top-border-icon glyphicon glyphicon-new-window hvr__popout" title="Open as Popup Window"></span>`
				.vee.onn("click", evt => {
					evt.stopPropagation();
					return Renderer.hover._getShowWindow_pDoPopout({eleHov, position, fnsCleanup, hoverId, opts, hoverWindow, eleContent}, {evt});
				})
				.vee.appendTo(brdEleTopRhs);
		}

		if (opts.sourceData) {
			const btnPopout = veE({
				tag: "span",
				clazz: `ve-hwin__top-border-icon ve-hwin__top-border-icon--text`,
				title: "Show Source Data",
				txt: "{}",
				click: evt => {
					evt.stopPropagation();
					evt.preventDefault();

					Renderer.hover.getShowWindow(
						Renderer.hover.getHoverContent_statsCode(opts.sourceData),
						Renderer.hover.getWindowPositionFromEvent(evt),
						{
							title: [opts.sourceData._displayName || opts.sourceData.name, "Source Data"].filter(Boolean).join(" \u2014 "),
							isPermanent: true,
							isBookContent: true,
						},
					);
				},
			});
			brdEleTopRhs.vee.appends(btnPopout);
		}

		const btnClose = veT`<span class="ve-hwin__top-border-icon glyphicon glyphicon-remove" title="Close (CTRL to Close All)"></span>`
			.vee.onn("click", (evt) => {
				evt.stopPropagation();

				if (EventUtil.isCtrlMetaKey(evt)) {
					Renderer.hover._doCloseAllWindows();
					return;
				}

				Renderer.hover._getShowWindow_doClose({eleHov, position, fnsCleanup, hoverId, opts, hoverWindow});
			})
			.vee.appendTo(brdEleTopRhs);

		wrpContent.vee.appends(eleContent);

		eleHov
			.vee.appends(brdrTopResize)
			.vee.appends(brdrTopRightResize)
			.vee.appends(brdrRightResize)
			.vee.appends(brdrBottomRightResize)
			.vee.appends(brdrBtmLeftResize)
			.vee.appends(brdrLeftResize)
			.vee.appends(brdrTopLeftResize)

			.vee.appends(brdrTop)
			.vee.appends(wrpContent)
			.vee.appends(brdrBtm);

		veE({ele: position.window.document.body})
			.vee.appends(eleHov);

		Renderer.hover._getShowWindow_setPosition({eleHov, wrpContent, position, eventChannel}, position);

		hoverWindow.zIndex = initialZIndex;
		hoverWindow.setZIndex = Renderer.hover._getNextZIndex.bind(this, {eleHov, hoverWindow});

		hoverWindow.setPosition = Renderer.hover._getShowWindow_setPosition.bind(this, {eleHov, wrpContent, position, eventChannel});
		hoverWindow.mutScroll = Renderer.hover._getShowWindow_mutScroll.bind(this, {eleHov, wrpContent, position});
		hoverWindow.setIsPermanent = Renderer.hover._getShowWindow_setIsPermanent.bind(this, {opts, brdrEleTop: brdrTop});
		hoverWindow.doClose = Renderer.hover._getShowWindow_doClose.bind(this, {eleHov, position, fnsCleanup, hoverId, opts, hoverWindow});
		hoverWindow.doMaximize = Renderer.hover._getShowWindow_doMaximize.bind(this, {brdrEleTop: brdrTop, eleHov});
		hoverWindow.doZIndexToFront = Renderer.hover._getShowWindow_doZIndexToFront.bind(this, {eleHov, hoverWindow, hoverId});

		hoverWindow.getPosition = Renderer.hover._getShowWindow_getPosition.bind(this, {eleHov, hoverWindow, wrpContent, position});

		hoverWindow.setContent = (eleContentNxt) => {
			wrpContent.vee.empty().vee.appends(eleContentNxt);
			eleContent = eleContentNxt;
		};

		hoverWindow.eventChannel = eventChannel;

		if (opts.isPopout) {
			hoverWindow.pPoppingOut = Renderer.hover._getShowWindow_pDoPopout({eleHov, position, fnsCleanup, hoverId, opts, hoverWindow, eleContent});
		}

		return hoverWindow;
	}

	static _getShowWindow_doClose ({eleHov, position, fnsCleanup, hoverId, opts, hoverWindow}) {
		eleHov.remove();

		fnsCleanup.splice(0).forEach(fn => fn());

		delete Renderer.hover._WINDOW_METAS[hoverId];

		if (opts.cbClose) opts.cbClose(hoverWindow);
	}

	static _getShowWindow_handleDragMousedown ({hoverWindow, hoverId, eleHov, drag, wrpContent}, {evt, type, isResizeOnlyWidth}) {
		if (evt.button === 0) evt.preventDefault();

		hoverWindow.zIndex = Renderer.hover._getNextZIndex(hoverId);
		eleHov.vee.css({"z-index": hoverWindow.zIndex});
		drag.type = type;
		drag.startX = EventUtil.getClientX(evt);
		drag.startY = EventUtil.getClientY(evt);
		drag.baseTop = parseFloat(eleHov.vee.css("top").slice(0, -2));
		drag.baseLeft = parseFloat(eleHov.vee.css("left").slice(0, -2));
		if (!isResizeOnlyWidth) drag.baseHeight = wrpContent.vee.outerHeight();
		drag.baseWidth = parseFloat(eleHov.vee.css("width").slice(0, -2));

		if (type !== this._DRAG_TYP_MOVE) {
			wrpContent.vee.css({
				...(isResizeOnlyWidth ? {} : {"height": `${drag.baseHeight}px`}),
				"max-height": "initial",
			});
			eleHov.vee.css({"max-width": "initial"});
		}
	}

	static _getShowWindow_isOverHoverTarget ({evt, target}) {
		return EventUtil.getClientX(evt) >= target.left
			&& EventUtil.getClientX(evt) <= target.left + target.width
			&& EventUtil.getClientY(evt) >= target.top
			&& EventUtil.getClientY(evt) <= target.top + target.height;
	}

	static _getShowWindow_handleNorthDrag ({wrpContent, eleHov, drag, evt}) {
		const diffY = Math.max(drag.startY - EventUtil.getClientY(evt), 80 - drag.baseHeight); // prevent <80 height, as this will cause the box to move downwards
		wrpContent.vee.css("height", `${drag.baseHeight + diffY}px`);
		eleHov.vee.css({"top": `${drag.baseTop - diffY}px`});
		drag.startY = EventUtil.getClientY(evt);
		drag.baseHeight = wrpContent.vee.outerHeight();
		drag.baseTop = parseFloat(eleHov.vee.css("top").slice(0, -2));
	}

	static _getShowWindow_handleEastDrag ({wrpContent, eleHov, drag, evt}) {
		const diffX = drag.startX - EventUtil.getClientX(evt);
		eleHov.vee.css({"width": `${drag.baseWidth - diffX}px`});
		drag.startX = EventUtil.getClientX(evt);
		drag.baseWidth = parseFloat(eleHov.vee.css("width").slice(0, -2));
	}

	static _getShowWindow_handleSouthDrag ({wrpContent, eleHov, drag, evt}) {
		const diffY = drag.startY - EventUtil.getClientY(evt);
		wrpContent.vee.css("height", `${drag.baseHeight - diffY}px`);
		drag.startY = EventUtil.getClientY(evt);
		drag.baseHeight = wrpContent.vee.outerHeight();
	}

	static _getShowWindow_handleWestDrag ({wrpContent, eleHov, drag, evt}) {
		const diffX = Math.max(drag.startX - EventUtil.getClientX(evt), 150 - drag.baseWidth);
		eleHov
			.vee.css({
				"width": `${drag.baseWidth + diffX}px`,
				"left": `${drag.baseLeft - diffX}px`,
			});
		drag.startX = EventUtil.getClientX(evt);
		drag.baseWidth = parseFloat(eleHov.vee.css("width").slice(0, -2));
		drag.baseLeft = parseFloat(eleHov.vee.css("left").slice(0, -2));
	}

	static _getShowWindow_doToggleMinimizedMaximized ({brdrEleTop, eleHov}) {
		const curState = brdrEleTop.vee.attr("data-display-title");
		const isNextMinified = curState === "false";
		brdrEleTop.vee.attr("data-display-title", isNextMinified);
		brdrEleTop.vee.attr("data-perm", true);
		eleHov.vee.toggleClass("ve-hwin--minified", isNextMinified);
	}

	static _getShowWindow_doMaximize ({brdrEleTop, eleHov}) {
		brdrEleTop.vee.attr("data-display-title", false);
		eleHov.vee.toggleClass("ve-hwin--minified", false);
	}

	static async _getShowWindow_pDoPopout ({eleHov, position, fnsCleanup, hoverId, opts, hoverWindow, eleContent}, {evt} = {}) {
		const winPopup = await Renderer.hover.pDoShowBrowserWindow(eleContent, opts);
		Renderer.hover._getShowWindow_doClose({eleHov, position, fnsCleanup, hoverId, opts, hoverWindow});
		hoverWindow._winPopup = winPopup;
	}

	static _getShowWindow_setPosition ({eleHov, wrpContent, position, eventChannel}, positionNxt) {
		switch (positionNxt.mode) {
			case "autoFromElement": {
				const bcr = eleHov.getBoundingClientRect();

				if (positionNxt.isFromBottom) eleHov.vee.css({"top": `${positionNxt.bcr.top - (bcr.height + 10)}px`});
				else eleHov.vee.css({"top": `${positionNxt.bcr.top + positionNxt.bcr.height + 10}px`});

				if (positionNxt.isFromRight) eleHov.vee.css({"left": `${(positionNxt.clientX || positionNxt.bcr.left) - (bcr.width + 10)}px`});
				else eleHov.vee.css({"left": `${(positionNxt.clientX || (positionNxt.bcr.left + positionNxt.bcr.width)) + 10}px`});

				// region Sync position info when updating
				if (position !== positionNxt) {
					Renderer.hover._WINDOW_POSITION_PROPS_FROM_EVENT
						.forEach(prop => {
							position[prop] = positionNxt[prop];
						});
				}
				// endregion

				break;
			}
			case "exact":
			case "exactRight": {
				const offsetX = (
					positionNxt.mode === "exactRight"
						? -eleHov.getBoundingClientRect().width
						: 0
				)
					+ (positionNxt.offsetX || 0);
				const offsetY = positionNxt.offsetY || 0;

				eleHov.vee.css({
					"left": `${positionNxt.x + offsetX}px`,
					"top": `${positionNxt.y + offsetY}px`,
				});
				break;
			}
			case "exactVisibleBottom": {
				const offsetX = positionNxt.offsetX || 0;
				const offsetY = positionNxt.offsetY || 0;

				eleHov.vee.css({
					"left": `${positionNxt.x + offsetX}px`,
					"top": `${positionNxt.y + offsetY}px`,
				});

				let yPos = positionNxt.y;

				const {bottom: posBottom, height: winHeight} = eleHov.getBoundingClientRect();
				const height = position.window.innerHeight;
				if (posBottom > height) {
					yPos = position.window.innerHeight - winHeight;
					eleHov.vee.css({"top": `${yPos}px`});
				}

				break;
			}
			default: throw new Error(`Positioning mode unimplemented: "${positionNxt.mode}"`);
		}

		Renderer.hover._getShowWindow_adjustPosition({eleHov, wrpContent, position, eventChannel});
	}

	static _getShowWindow_mutScroll ({eleHov, wrpContent, position}, {deltaPixelsX, deltaPixelsY}) {
		if (!deltaPixelsX && !deltaPixelsY) return;
		wrpContent.scrollBy(deltaPixelsX, deltaPixelsY);
	}

	static _getShowWindow_adjustPosition ({eleHov, wrpContent, position, eventChannel}) {
		const bcr = eleHov.getBoundingClientRect().toJSON();
		const screenHeight = position.window.innerHeight;
		const screenWidth = position.window.innerWidth;

		// readjust position...
		// ...if vertically clipping off screen
		if (bcr.top < 0) {
			bcr.top = 0;
			bcr.bottom = bcr.top + bcr.height;
			eleHov.style.top = `${bcr.top}px`;
		} else if (bcr.top >= screenHeight - Renderer.hover._BAR_HEIGHT) {
			bcr.top = screenHeight - Renderer.hover._BAR_HEIGHT;
			bcr.bottom = bcr.top + bcr.height;
			eleHov.style.top = `${bcr.top}px`;
		}

		// ...if horizontally clipping off screen
		if (bcr.left < 0) {
			bcr.left = 0;
			bcr.right = bcr.left + bcr.width;
			eleHov.style.left = `${bcr.left}px`;
		} else if (bcr.left + bcr.width + Renderer.hover._BODY_SCROLLER_WIDTH_PX > screenWidth) {
			bcr.left = Math.max(screenWidth - bcr.width - Renderer.hover._BODY_SCROLLER_WIDTH_PX, 0);
			bcr.right = bcr.left + bcr.width;
			eleHov.style.left = `${bcr.left}px`;
		}

		// Prevent window "flickering" when hovering a link
		if (
			position.isPreventFlicker
			&& Renderer.hover._isIntersectRect(bcr, position.bcr)
		) {
			if (position.isFromBottom) {
				bcr.height = position.bcr.top - 5;
				wrpContent.style.height = `${bcr.height}px`;
			} else {
				bcr.height = screenHeight - position.bcr.bottom - 5;
				wrpContent.style.height = `${bcr.height}px`;
			}
		}

		eventChannel.dispatchEvent(new Event("resize"));
	}

	static _getShowWindow_getPosition ({eleHov, hoverWindow, wrpContent}) {
		if (hoverWindow._winPopup && !hoverWindow._winPopup.closed) {
			return {
				wWrpContent: veE({ele: hoverWindow._winPopup.document.body}).vee.outerWidth(),
				hWrapContent: veE({ele: hoverWindow._winPopup.document.body}).vee.outerHeight(),
			};
		}

		return {
			wWrpContent: wrpContent.vee.outerWidth(),
			hWrapContent: wrpContent.vee.outerHeight(),
		};
	}

	static _getShowWindow_setIsPermanent ({opts, brdrEleTop}, isPermanent) {
		opts.isPermanent = isPermanent;
		brdrEleTop.vee.attr("data-perm", isPermanent);
	}

	static _getShowWindow_setZIndex ({eleHov, hoverWindow}, zIndex) {
		eleHov.vee.css("z-index", zIndex);
		hoverWindow.zIndex = zIndex;
	}

	static _getShowWindow_doZIndexToFront ({eleHov, hoverWindow, hoverId}) {
		const nxtZIndex = Renderer.hover._getNextZIndex(hoverId);
		Renderer.hover._getShowWindow_setZIndex({eleHov, hoverWindow}, nxtZIndex);
	}

	static _PredefinedHoverMeta = class {
		id;
		html;
		mouseOver;
		mouseMove;
		mouseLeave;
		touchStart;
		show;

		constructor (opts) { Object.assign(this, opts); }
	};

	/**
	 * @param entry
	 * @param [opts]
	 * @param [opts.isBookContent]
	 * @param [opts.isLargeBookContent]
	 * @param [opts.depth]
	 * @param [opts.id]
	 */
	static getMakePredefinedHover (entry, opts) {
		opts = opts || {};

		const id = opts.id ?? Renderer.hover._getNextId();
		Renderer.hover._entryCache[id] = entry;
		return new this._PredefinedHoverMeta({
			id,
			html: `onmouseover="Renderer.hover.handlePredefinedMouseOver(event, this, ${id}, ${JSON.stringify(opts).escapeQuotes()})" onmousemove="Renderer.hover.handlePredefinedMouseMove(event, this)" onmouseleave="Renderer.hover.handlePredefinedMouseLeave(event, this)" ${Renderer.hover.getPreventTouchString()}`,
			mouseOver: (evt, ele) => Renderer.hover.handlePredefinedMouseOver(evt, ele, id, opts),
			mouseMove: (evt, ele) => Renderer.hover.handlePredefinedMouseMove(evt, ele),
			mouseLeave: (evt, ele) => Renderer.hover.handlePredefinedMouseLeave(evt, ele),
			touchStart: (evt, ele) => Renderer.hover.handleTouchStart(evt, ele),
			show: () => Renderer.hover.doPredefinedShow(id, opts),
		});
	}

	static updatePredefinedHover (id, entry) {
		Renderer.hover._entryCache[id] = entry;
	}

	static deletePredefinedHover (id) {
		delete Renderer.hover._entryCache[id];
	}

	static getInlineHover (entry, opts) {
		return {
			// Re-use link handlers, as the inline version is a simplified version
			html: [
				`onmouseover="Renderer.hover.handleInlineMouseOver(event, this)"`,
				`onmouseleave="Renderer.hover.handleLinkMouseLeave(event, this)"`,
				`onmousemove="Renderer.hover.handleLinkMouseMove(event, this)"`,
				`onclick="Renderer.hover.handleLinkClick(event, this)"`,
				`onwheel="Renderer.hover.handleLinkWheel(event, this)"`,
				`data-vet-entry="${JSON.stringify(entry).qq()}"`,
				`${opts ? `data-vet-opts="${JSON.stringify(opts).qq()}"` : ""}`,
				`${Renderer.hover.getPreventTouchString()}`,
			]
				.filter(Boolean)
				.join(" "),
		};
	}

	static getPreventTouchString () {
		return `ontouchstart="Renderer.hover.handleTouchStart(event, this)"`;
	}

	static handleTouchStart (evt, ele) {
		if (Renderer.hover.isSmallScreen(evt)) return;

		ele = veE({ele});

		// on large touchscreen devices only (e.g. iPads)
		// cache the link location and redirect it to void
		ele.vee.attr("data-tmp-href", ele.vee.attr("data-tmp-href") || ele.vee.attr("href"));
		ele.vee.attr("href", "javascript:void(0)");
		// restore the location after 100ms; if the user long-presses the link will be restored by the time they
		//   e.g. attempt to open a new tab
		setTimeout(() => {
			const href = ele.vee.attr("data-tmp-href");
			if (href) {
				ele.vee.attr("href", href);
				ele.vee.attr("data-tmp-href", null);
			}
		}, 100);
	}

	// region entry fetching
	static getEntityLink (
		ent,
		{
			displayText = null,
			prop = null,
			isLowerCase = false,
			isTitleCase = false,
		} = {},
	) {
		if (isLowerCase && isTitleCase) throw new Error(`"isLowerCase" and "isTitleCase" are mutually exclusive!`);

		const name = isLowerCase ? ent.name.toLowerCase() : isTitleCase ? ent.name.toTitleCase() : ent.name;

		let parts = [
			name,
			ent.source,
			displayText || "",
		];

		switch (prop || ent.__prop) {
			case "monster": {
				if (ent._isScaledCr) {
					parts.push(`${VeCt.HASH_SCALED}=${Parser.numberToCr(ent._scaledCr)}`);
				}

				if (ent._isScaledSpellSummon) {
					parts.push(`${VeCt.HASH_SCALED_SPELL_SUMMON}=${ent._scaledSpellSummonLevel}`);
				}

				if (ent._isScaledClassSummon) {
					parts.push(`${VeCt.HASH_SCALED_CLASS_SUMMON}=${ent._scaledClassSummonLevel}`);
				}

				break;
			}

			// TODO recipe?

			case "deity": {
				parts.splice(1, 0, ent.pantheon);
				break;
			}
		}

		while (parts.length && !parts.last()?.length) parts.pop();

		return Renderer.get().render(`{@${Parser.getPropTag(prop || ent.__prop)} ${parts.join("|")}}`);
	}

	static getRefMetaFromTag (str) {
		// convert e.g. `"{#itemEntry Ring of Resistance|DMG}"`
		//   to `{type: "refItemEntry", "itemEntry": "Ring of Resistance|DMG"}`
		str = str.slice(2, -1);
		const [tag, ...refParts] = str.split(" ");
		const ref = refParts.join(" ");
		const type = `ref${tag.uppercaseFirst()}`;
		return {type, [tag]: ref};
	}
	// endregion

	// region Apply custom hash IDs
	static async pApplyCustomHashId (page, ent, customHashId) {
		switch (page) {
			case UrlUtil.PG_BESTIARY: {
				const out = await Renderer.monster.pGetModifiedCreature(ent, customHashId);
				Renderer.monster.updateParsed(out);
				return out;
			}

			case UrlUtil.PG_RECIPES: return Renderer.recipe.pGetModifiedRecipe(ent, customHashId);

			default: return ent;
		}
	}
	// endregion

	static getGenericCompactRenderedString (entry, {depth = null} = {}) {
		if (entry.header != null) depth = Math.max(0, entry.header - 1);
		if (depth == null) depth = 0;

		return `
			<tr><td colspan="6" class="ve-pb-2">
			${Renderer.get().setFirstSection(true).render(entry, depth)}
			</td></tr>
		`;
	}

	static getCompactRenderedFluffString (entry, {isSkipRootName = false} = {}) {
		if (!entry.entries) return "";

		if (!isSkipRootName) {
			Renderer.get().setFirstSection(true);
			return `<tr><td colspan="6" class="ve-pb-2">
			${entry.entries.map(ent => Renderer.get().render(ent)).join("")}
			</td></tr>`;
		}

		const toRender = MiscUtil.copyFast(entry.entries);
		delete toRender[0]?.name;

		return `<tr><td colspan="6" class="ve-pb-2">
		${Renderer.get().setFirstSection(true).render({type: "entries", entries: toRender})}
		</td></tr>`;
	}

	static _getFnRenderCompact ({page, isStatic = false} = {}) {
		switch (page) {
			case "generic":
			case "hover": return Renderer.hover.getGenericCompactRenderedString.bind(Renderer.hover);
			case UrlUtil.PG_QUICKREF: return Renderer.hover.getGenericCompactRenderedString.bind(Renderer.hover);
			case UrlUtil.PG_CLASSES: return Renderer.class.getCompactRenderedString.bind(Renderer.class);
			case UrlUtil.PG_SPELLS: return Renderer.spell.getCompactRenderedString.bind(Renderer.spell);
			case "itemGroup":
			case UrlUtil.PG_ITEMS: return Renderer.item.getCompactRenderedString.bind(Renderer.item);
			case UrlUtil.PG_BESTIARY: return it => Renderer.monster.getCompactRenderedString(it, {isShowScalers: !isStatic, isScaledCr: it._originalCr != null, isScaledSpellSummon: it._isScaledSpellSummon, isScaledClassSummon: it._isScaledClassSummon});
			case UrlUtil.PG_CONDITIONS_DISEASES: return Renderer.conditionDisease.getCompactRenderedString.bind(Renderer.conditionDisease);
			case UrlUtil.PG_BACKGROUNDS: return Renderer.background.getCompactRenderedString.bind(Renderer.background);
			case UrlUtil.PG_FEATS: return Renderer.feat.getCompactRenderedString.bind(Renderer.feat);
			case UrlUtil.PG_OPT_FEATURES: return Renderer.optionalfeature.getCompactRenderedString.bind(Renderer.optionalfeature);
			case UrlUtil.PG_PSIONICS: return Renderer.psionic.getCompactRenderedString.bind(Renderer.psionic);
			case UrlUtil.PG_REWARDS: return Renderer.reward.getCompactRenderedString.bind(Renderer.reward);
			case UrlUtil.PG_RACES: return it => Renderer.race.getCompactRenderedString(it, {isStatic});
			case UrlUtil.PG_DEITIES: return Renderer.deity.getCompactRenderedString.bind(Renderer.deity);
			case UrlUtil.PG_OBJECTS: return Renderer.object.getCompactRenderedString.bind(Renderer.object);
			case UrlUtil.PG_TRAPS_HAZARDS: return Renderer.traphazard.getCompactRenderedString.bind(Renderer.traphazard);
			case UrlUtil.PG_VARIANTRULES: return Renderer.variantrule.getCompactRenderedString.bind(Renderer.variantrule);
			case UrlUtil.PG_CULTS_BOONS: return Renderer.cultboon.getCompactRenderedString.bind(Renderer.cultboon);
			case UrlUtil.PG_TABLES: return Renderer.table.getCompactRenderedString.bind(Renderer.table);
			case "name":
			case UrlUtil.PG_NAMES: return Renderer.namez.getCompactRenderedString.bind(Renderer.namez);
			case UrlUtil.PG_ENCOUNTERGEN: return Renderer.encounter.getCompactRenderedString.bind(Renderer.encounter);
			case UrlUtil.PG_VEHICLES: return Renderer.vehicle.getCompactRenderedString.bind(Renderer.vehicle);
			case UrlUtil.PG_ACTIONS: return Renderer.action.getCompactRenderedString.bind(Renderer.action);
			case UrlUtil.PG_LANGUAGES: return Renderer.language.getCompactRenderedString.bind(Renderer.language);
			case UrlUtil.PG_CHAR_CREATION_OPTIONS: return Renderer.charoption.getCompactRenderedString.bind(Renderer.charoption);
			case UrlUtil.PG_RECIPES: return Renderer.recipe.getCompactRenderedString.bind(Renderer.recipe);
			case UrlUtil.PG_HOMECRAFTS: return Renderer.homecraft.getCompactRenderedString.bind(Renderer.homecraft);
			case UrlUtil.PG_CLASS_SUBCLASS_FEATURES: return Renderer.hover.getGenericCompactRenderedString.bind(Renderer.hover);
			case UrlUtil.PG_CREATURE_FEATURES: return Renderer.hover.getGenericCompactRenderedString.bind(Renderer.hover);
			case UrlUtil.PG_DECKS: return Renderer.deck.getCompactRenderedString.bind(Renderer.deck);
			case UrlUtil.PG_BASTIONS: return Renderer.bastion.getCompactRenderedString.bind(Renderer.bastion);
			// region props
			case "classfeature":
			case "classFeature":
				return Renderer.hover.getGenericCompactRenderedString.bind(Renderer.hover);
			case "subclassfeature":
			case "subclassFeature":
				return Renderer.hover.getGenericCompactRenderedString.bind(Renderer.hover);
			case "citation": return Renderer.hover.getGenericCompactRenderedString.bind(Renderer.hover);
			// endregion
			default:
				if (Renderer[page]?.getCompactRenderedString) return Renderer[page].getCompactRenderedString.bind(Renderer[page]);
				if (page?.endsWith("Fluff")) return Renderer.hover.getCompactRenderedFluffString.bind(Renderer.hover);
				return null;
		}
	}

	static getFnRenderCompact (page, {isStatic = false} = {}) {
		const fn = this._getFnRenderCompact({page, isStatic});
		if (!fn) return null;
		return (...args) => Renderer.get().withSetRenderHeaderIndex(false, () => fn(...args));
	}

	static getFnBindListenersCompact (page, {overrides = {}} = {}) {
		if (overrides[page]) return overrides[page];

		switch (page) {
			case UrlUtil.PG_BESTIARY: return Renderer.monster.bindListenersCompact.bind(Renderer.monster);
			case UrlUtil.PG_RACES: return Renderer.race.bindListenersCompact.bind(Renderer.race);
			default: return null;
		}
	}

	/* -------------------------------------------- */

	static _isSizedScreen ({evt, minWidth = null, maxWidth = null}) {
		if (typeof window === "undefined") return false;

		if (minWidth == null && maxWidth == null) throw new Error(`At least one of "minWidth" and "maxWidth" must be specified!`);

		evt = evt || {};
		const win = (evt.view || {}).window || window;

		if (maxWidth != null && win.innerWidth > maxWidth) return false;
		if (minWidth != null && win.innerWidth < minWidth) return false;
		return true;
	}

	static isSmallScreen (evt) {
		return this._isSizedScreen({evt, maxWidth: 768});
	}

	static isMinLargeScreen (evt) {
		return this._isSizedScreen({evt, minWidth: 1200});
	}

	/* -------------------------------------------- */

	/**
	 * @param page
	 * @param toRender
	 * @param [opts]
	 * @param [opts.isBookContent]
	 * @param [opts.isStatic] If this content is to be "static," i.e. display only, containing minimal interactive UI.
	 * @param [opts.fnRender]
	 * @param [renderFnOpts]
	 */
	static getHoverContent_stats (page, toRender, opts, renderFnOpts) {
		opts = opts || {};
		if (Renderer.hover.isBookContentStyledPage(page)) opts = {...MiscUtil.copyFast(opts), isBookContent: true};

		const name = toRender._displayName || toRender.name;
		const fnRender = opts.fnRender || Renderer.hover.getFnRenderCompact(page, {isStatic: opts.isStatic});
		const out = veT`<table class="ve-w-100 ve-stats ${opts.isBookContent ? `ve-stats--book` : ""}" ${name ? `data-roll-name-ancestor-roller="${Renderer.stripTags(name).qq()}"` : ""}>${fnRender(toRender, renderFnOpts)}</table>`;

		if (!opts.isStatic) {
			const fnBind = Renderer.hover.getFnBindListenersCompact(page);
			if (fnBind) fnBind(toRender, out);
		}

		return out;
	}

	/**
	 * @param page
	 * @param toRender
	 * @param [opts]
	 * @param [opts.isBookContent]
	 * @param [renderFnOpts]
	 */
	static getHoverContent_fluff (page, toRender, opts, renderFnOpts) {
		opts = opts || {};
		if (Renderer.hover.isBookContentStyledPage(page)) opts = {...MiscUtil.copyFast(opts), isBookContent: true};

		if (!toRender) {
			return veT`<table class="ve-w-100 ve-stats ${opts.isBookContent ? `ve-stats--book` : ""}"><tr><td colspan="6" class="ve-p-2 ve-text-center">${Renderer.utils.HTML_NO_INFO}</td></tr></table>`;
		}

		toRender = MiscUtil.copyFast(toRender);

		if (toRender.images && toRender.images.length) {
			const cachedImages = MiscUtil.copyFast(toRender.images);
			delete toRender.images;

			toRender.entries = toRender.entries || [];
			const hasText = toRender.entries.length > 0;
			// Add the first image at the top
			if (hasText) toRender.entries.unshift({type: "hr"});
			cachedImages[0].maxHeight = 33;
			cachedImages[0].maxHeightUnits = "vh";
			toRender.entries.unshift(cachedImages[0]);

			// Add any other images at the bottom
			if (cachedImages.length > 1) {
				if (hasText) toRender.entries.push({type: "hr"});
				toRender.entries.push(...cachedImages.slice(1));
			}
		}

		const name = toRender._displayName || toRender.name;
		return veT`<table class="ve-w-100 ve-stats ${opts.isBookContent ? `ve-stats--book` : ""}" ${name ? `data-roll-name-ancestor-roller="${Renderer.stripTags(name).qq()}"` : ""}>${Renderer.generic.getCompactRenderedString(toRender, renderFnOpts)}</table>`;
	}

	static getHoverContent_statsCode (toRender, {isSkipClean = false, title = null} = {}) {
		const cleanCopy = isSkipClean ? toRender : DataUtil.cleanJson(MiscUtil.copyFast(toRender));
		return Renderer.hover.getHoverContent_miscCode(
			title || [cleanCopy.name, "Source Data"].filter(Boolean).join(" \u2014 "),
			JSON.stringify(cleanCopy, null, "\t"),
		);
	}

	static getHoverContent_miscCode (name, code) {
		const toRenderCode = {
			type: "code",
			name,
			preformatted: code,
		};
		return veT`<table class="ve-w-100 ve-stats ve-stats--book"><tr><td>${Renderer.get().render(toRenderCode)}</td></tr></table>`;
	}

	/**
	 * @param toRender
	 * @param [opts]
	 * @param [opts.isBookContent]
	 * @param [opts.isLargeBookContent]
	 * @param [opts.depth]
	 */
	static getHoverContent_generic (toRender, opts) {
		opts = opts || {};

		const name = toRender._displayName || toRender.name;
		return veT`<table class="ve-w-100 ve-stats ${opts.isBookContent || opts.isLargeBookContent ? "ve-stats--book" : ""} ${opts.isLargeBookContent ? "ve-stats--book-large" : ""}" ${name ? `data-roll-name-ancestor-roller="${Renderer.stripTags(name).qq()}"` : ""}>${Renderer.hover.getGenericCompactRenderedString(toRender, {depth: opts.depth || 0})}</table>`;
	}

	/**
	 * @param evt
	 * @param entity
	 */
	static doPopoutCurPage (evt, entity) {
		const page = UrlUtil.getCurrentPage();
		Renderer.hover.getShowWindow(
			Renderer.hover.getHoverContent_stats(page, entity),
			Renderer.hover.getWindowPositionFromEvent(evt),
			{
				pageUrl: `#${UrlUtil.autoEncodeHash(entity)}`,
				title: entity._displayName || entity.name,
				isPermanent: true,
				isBookContent: Renderer.hover.isBookContentStyledPage(page),
				sourceData: entity,
			},
		);
	}

	/**
	 * @param evt
	 * @param entity
	 */
	static async pDoBrowserPopoutCurPage (evt, entity) {
		const page = UrlUtil.getCurrentPage();
		const content = Renderer.hover.getHoverContent_stats(page, entity);

		await Renderer.hover.pDoShowBrowserWindow(
			content,
			{
				title: entity._displayName || entity.name,
			},
		);
	}

	static isBookContentStyledPage (page) {
		return [UrlUtil.PG_RECIPES, UrlUtil.PG_HOMECRAFTS].includes(page);
	}
};

/**
 * Recursively find all the names of entries, useful for indexing
 * @param nameStack an array to append the names to
 * @param entry the base entry
 * @param [opts] Options object.
 * @param [opts.maxDepth] Maximum depth to search for
 * @param [opts.depth] Start depth (used internally when recursing)
 * @param [opts.typeBlocklist] A set of entry types to avoid.
 */
Renderer.getNames = function (nameStack, entry, opts) {
	opts = opts || {};
	if (opts.maxDepth == null) opts.maxDepth = false;
	if (opts.depth == null) opts.depth = 0;

	if (opts.typeBlocklist && entry.type && opts.typeBlocklist.has(entry.type)) return;

	if (opts.maxDepth !== false && opts.depth > opts.maxDepth) return;
	if (entry.name) nameStack.push(Renderer.stripTags(entry.name));
	if (entry.entries) {
		let nextDepth = entry.type === "section" ? -1 : entry.type === "entries" ? opts.depth + 1 : opts.depth;
		for (const eX of entry.entries) {
			const nxtOpts = {...opts};
			nxtOpts.depth = nextDepth;
			Renderer.getNames(nameStack, eX, nxtOpts);
		}
	} else if (entry.items) {
		for (const eX of entry.items) {
			Renderer.getNames(nameStack, eX, opts);
		}
	}
};

Renderer.getNumberedNames = function (entry) {
	const renderer = new Renderer().setTrackTitles(true);
	renderer.render(entry);
	const titles = renderer.getTrackedTitles();
	const out = {};
	Object.entries(titles).forEach(([k, v]) => {
		v = Renderer.stripTags(v);
		out[v] = Number(k);
	});
	return out;
};

// dig down until we find a name, as feature names can be nested
Renderer.findName = function (entry) { return CollectionUtil.dfs(entry, {prop: "name"}); };
Renderer.findSource = function (entry) { return CollectionUtil.dfs(entry, {prop: "source"}); };
Renderer.findEntry = function (entry) { return CollectionUtil.dfs(entry, {fnMatch: obj => obj.name && obj?.entries?.length}); };

/**
 * @param {string} str
 * @param {?Set<string>} allowlistTags
 * @param {?Set<string>} blocklistTags
 */
Renderer.stripTags = function (str, {allowlistTags = null, blocklistTags = null} = {}) {
	if (!str) return str;

	const ptrAccum = {_: ""};
	Renderer._stripTags_textRender({str, ptrAccum, allowlistTags, blocklistTags});
	return ptrAccum._;
};

Renderer._stripTags_textRender = function ({str, ptrAccum, allowlistTags = null, blocklistTags = null} = {}) {
	const tagSplit = Renderer.splitByTags(str);
	const len = tagSplit.length;
	for (let i = 0; i < len; ++i) {
		const s = tagSplit[i];
		if (!s) continue;

		if (!s.startsWith("{@")) {
			ptrAccum._ += s;
			continue;
		}

		const [tag, text] = Renderer.splitFirstSpace(s.slice(1, -1));

		if (
			(allowlistTags != null && allowlistTags.has(tag))
			|| (blocklistTags != null && !blocklistTags.has(tag))
		) {
			ptrAccum._ += s;
			continue;
		}

		const stripped = Renderer.tag.getTagInfo(tag, {isRequired: true}).getStripped(tag, text);

		Renderer._stripTags_textRender({str: stripped, ptrAccum, allowlistTags, blocklistTags});
	}
};

/**
 * This assumes validation has been done in advance.
 * @param row
 * @param [opts]
 * @param [opts.cbErr]
 * @param [opts.isForceInfiniteResults]
 * @param [opts.isFirstRow] Used it `isForceInfiniteResults` is specified.
 * @param [opts.isLastRow] Used it `isForceInfiniteResults` is specified.
 */
Renderer.getRollableRow = function (row, opts) {
	opts = opts || {};

	if (
		row[0]?.type === "cell"
		&& (
			row[0]?.roll?.exact != null
			|| (row[0]?.roll?.min != null && row[0]?.roll?.max != null)
		)
	) return row;

	row = MiscUtil.copyFast(row);
	try {
		const cleanRow = String(row[0]).trim();

		// format: "20 or lower"; "99 or higher"
		const mLowHigh = /^(\d+) or (lower|higher)$/i.exec(cleanRow);
		if (mLowHigh) {
			row[0] = {type: "cell", entry: cleanRow}; // Preserve the original text

			if (mLowHigh[2].toLowerCase() === "lower") {
				row[0].roll = {
					min: -Renderer.dice.POS_INFINITE,
					max: Number(mLowHigh[1]),
				};
			} else {
				row[0].roll = {
					min: Number(mLowHigh[1]),
					max: Renderer.dice.POS_INFINITE,
				};
			}

			return row;
		}

		// format: "95-00" or "12"
		// u2012 = figure dash; u2013 = en-dash; u2014 = em dash; u2212 = minus sign
		const m = /^(\d+)([-\u2013-\u2014\u2212](\d+))?$/.exec(cleanRow);
		if (m) {
			if (m[1] && !m[2]) {
				row[0] = {
					type: "cell",
					roll: {
						exact: Number(m[1]),
					},
				};
				if (m[1][0] === "0") row[0].roll.pad = true;
				Renderer.getRollableRow._handleInfiniteOpts(row, opts);
			} else {
				row[0] = {
					type: "cell",
					roll: {
						min: Number(m[1]),
						max: Number(m[3]),
					},
				};
				if (m[1][0] === "0" || m[3][0] === "0") row[0].roll.pad = true;
				Renderer.getRollableRow._handleInfiniteOpts(row, opts);
			}
		} else {
			// format: "12+"
			const m = /^(\d+)\+$/.exec(row[0]);
			row[0] = {
				type: "cell",
				roll: {
					min: Number(m[1]),
					max: Renderer.dice.POS_INFINITE,
				},
			};
		}
	} catch (e) {
		if (opts.cbErr) opts.cbErr(row[0], e);
	}
	return row;
};
Renderer.getRollableRow._handleInfiniteOpts = function (row, opts) {
	if (!opts.isForceInfiniteResults) return;

	const isExact = row[0].roll.exact != null;

	if (opts.isFirstRow) {
		if (!isExact) row[0].roll.displayMin = row[0].roll.min;
		row[0].roll.min = -Renderer.dice.POS_INFINITE;
	}

	if (opts.isLastRow) {
		if (!isExact) row[0].roll.displayMax = row[0].roll.max;
		row[0].roll.max = Renderer.dice.POS_INFINITE;
	}
};

Renderer.initLazyImageLoaders = function () {
	const images = document.querySelectorAll(`img[${Renderer.utils.lazy.ATTR_IMG_FINAL_SRC}], canvas[${Renderer.utils.lazy.ATTR_IMG_FINAL_SRC}]`);

	Renderer.utils.lazy.destroyObserver({observerId: "images"});

	const observer = Renderer.utils.lazy.getCreateObserver({
		observerId: "images",
		pFnOnObserve: async ({entry}) => {
			Renderer.utils.lazy.mutFinalizeEle(entry.target);
			return true;
		},
	});

	images.forEach(ele => observer.track(ele));
};

Renderer.HEAD_NEG_1 = "ve-rd__b--0";
Renderer.HEAD_0 = "ve-rd__b--1";
Renderer.HEAD_1 = "ve-rd__b--2";
Renderer.HEAD_2 = "ve-rd__b--3";
Renderer.HEAD_2_SUB_VARIANT = "ve-rd__b--4";
Renderer.DATA_NONE = "data-none";

"use strict";

Renderer.dice = class {
	static SYSTEM_USER = {
		name: "Avandra", // goddess of luck
	};
	static POS_INFINITE = 100000000000000000000; // larger than this, and we start to see "e" numbers appear
	static _SYMBOL_PARSE_FAILED = Symbol("parseFailed");

	static _wrpRoll = null;
	static _eleRollboxMinimized = null;
	static _iptRoll = null;
	static _eleOutRoll = null;
	static _eleHead = null;
	static _hist = [];
	static _histIndex = null;
	static _eleLastRolledBy = null;
	static _storage = null;

	static _isManualMode = false;

	/* -------------------------------------------- */

	// region Utilities
	static DICE = [4, 6, 8, 10, 12, 20, 100];

	static getNextDice (faces) {
		const idx = Renderer.dice.DICE.indexOf(faces);
		if (~idx) return Renderer.dice.DICE[idx + 1];
		else return null;
	}

	static getPreviousDice (faces) {
		const idx = Renderer.dice.DICE.indexOf(faces);
		if (~idx) return Renderer.dice.DICE[idx - 1];
		else return null;
	}
	// endregion

	/* -------------------------------------------- */

	// region DM Screen integration
	static _panel = null;

	static bindDmScreenPanel (panel, title) {
		if (Renderer.dice._panel) { // there can only be one roller box
			Renderer.dice.unbindDmScreenPanel();
		}
		Renderer.dice._showBox();
		Renderer.dice._panel = panel;
		panel.doPopulate_Rollbox(title);
	}

	static unbindDmScreenPanel () {
		if (Renderer.dice._panel) {
			document.body.appendChild(Renderer.dice._wrpRoll);
			Renderer.dice._panel.closeTabContent();
			Renderer.dice._panel = null;
			Renderer.dice._hideBox();
			Renderer.dice._wrpRoll.vee.removeClass("rollbox-panel");
		}
	}

	static getRoller () {
		return Renderer.dice._wrpRoll;
	}
	// endregion

	/* -------------------------------------------- */

	static bindOnclickListener (ele) {
		ele.addEventListener("click", (evt) => {
			const eleDice = evt.target.hasAttribute("data-packed-dice")
				? evt.target
				// Tolerate e.g. Bestiary wrapped proficiency dice rollers
				: evt.target.parentElement?.hasAttribute("data-packed-dice")
					? evt.target.parentElement
					: null;

			if (!eleDice) return;

			evt.preventDefault();
			evt.stopImmediatePropagation();
			Renderer.dice.pRollerClickUseData(evt, eleDice).then(null);
		});
	}

	/* -------------------------------------------- */

	/**
	 * Silently roll an expression and get the result.
	 * Note that this does not support dynamic variables (e.g. user proficiency bonus).
	 */
	static parseRandomise2 (str) {
		if (!str || !str.trim()) return null;
		const wrpTree = Renderer.dice.lang.getTree3(str);
		if (wrpTree) return wrpTree.tree.evl({});
		else return null;
	}

	/**
	 * Silently get the average of an expression.
	 * Note that this does not support dynamic variables (e.g. user proficiency bonus).
	 */
	static parseAverage (str) {
		if (!str || !str.trim()) return null;
		const wrpTree = Renderer.dice.lang.getTree3(str);
		if (wrpTree) return wrpTree.tree.avg({});
		else return null;
	}

	// region Roll box UI
	static _showBox () {
		Renderer.dice._eleRollboxMinimized.vee.hide();
		Renderer.dice._wrpRoll.vee.show();
		Renderer.dice._iptRoll.vee.prop("placeholder", `${Renderer.dice._getRandomPlaceholder()} or "/help"`);
	}

	static _hideBox () {
		Renderer.dice._eleRollboxMinimized.vee.show();
		Renderer.dice._wrpRoll.vee.hide();
	}

	static _getRandomPlaceholder () {
		const count = RollerUtil.randomise(10);
		const faces = Renderer.dice.DICE[RollerUtil.randomise(Renderer.dice.DICE.length - 1)];
		const mod = (RollerUtil.randomise(3) - 2) * RollerUtil.randomise(10);
		const drop = (count > 1) && RollerUtil.randomise(5) === 5;
		const dropDir = drop ? RollerUtil.randomise(2) === 2 ? "h" : "l" : "";
		const dropAmount = drop ? RollerUtil.randomise(count - 1) : null;
		return `${count}d${faces}${drop ? `d${dropDir}${dropAmount}` : ""}${mod < 0 ? mod : mod > 0 ? `+${mod}` : ""}`;
	}

	/** Initialise the roll box UI. */
	static async _pInit () {
		const minRoll = veT`<button class="rollbox-min"><span class="glyphicon glyphicon-chevron-up"></span></button>`
			.vee.onn("click", () => {
				Renderer.dice._showBox();
				Renderer.dice._iptRoll.vee.focus();
			});
		const eleHead = veT`<div class="head-roll"><span class="hdr-roll">Dice Roller</span><span class="ve-p-2 glyphicon glyphicon-remove"></span></div>`
			.vee.onn("click", () => {
				if (!Renderer.dice._panel) Renderer.dice._hideBox();
			});
		const outRoll = veT`<div class="out-roll"></div>`;
		const iptRoll = veT`<input class="ipt-roll ve-form-control">`
			.vee.disableSpellcheck()
			.vee.onn("keypress", async evt => {
				evt.stopPropagation();
				if (evt.key !== "Enter") return;

				const strDice = iptRoll.vee.val();
				const result = await Renderer.dice.pRoll2(
					strDice,
					{
						isUser: true,
						name: "Anon",
					},
				);
				iptRoll.vee.val("");

				if (result === Renderer.dice._SYMBOL_PARSE_FAILED) {
					Renderer.dice._showInvalid();
					iptRoll.vee.addClass("form-control--error");
				}
			})
			.vee.onn("keydown", (evt) => {
				iptRoll.vee.removeClass("form-control--error");

				// arrow keys only work on keydown
				if (evt.key === "ArrowUp") {
					evt.preventDefault();
					Renderer.dice._prevHistory();
					return;
				}

				if (evt.key === "ArrowDown") {
					evt.preventDefault();
					Renderer.dice._nextHistory();
				}
			});
		const wrpRoll = veT`<div class="rollbox ve-flex-col ve-min-h-0">
			${eleHead}
			${outRoll}
			${iptRoll}
		</div>`.vee.hide();

		Renderer.dice._wrpRoll = wrpRoll;
		Renderer.dice._eleRollboxMinimized = minRoll;
		Renderer.dice._eleHead = eleHead;
		Renderer.dice._eleOutRoll = outRoll;
		Renderer.dice._iptRoll = iptRoll;

		veE({ele: document.body}).vee.appends(minRoll).vee.appends(wrpRoll);

		wrpRoll
			.vee.onn("click", (evt) => {
				const tgt = veE({ele: evt.target});
				if (!tgt.vee.hasClass("out-roll-item-code")) return;
				Renderer.dice._iptRoll.vee.val(tgt.vee.txt()).vee.focus();
			});
		Renderer.dice.storage = await StorageUtil.pGet(VeCt.STORAGE_ROLLER_MACRO) || {};
	}

	static _prevHistory () { Renderer.dice._histIndex--; Renderer.dice._prevNextHistory_load(); }
	static _nextHistory () { Renderer.dice._histIndex++; Renderer.dice._prevNextHistory_load(); }

	static _prevNextHistory_load () {
		Renderer.dice._cleanHistoryIndex();
		const nxtVal = Renderer.dice._hist[Renderer.dice._histIndex];
		Renderer.dice._iptRoll.vee.val(nxtVal);
		if (nxtVal) Renderer.dice._iptRoll.selectionStart = Renderer.dice._iptRoll.selectionEnd = nxtVal.length;
	}

	static _cleanHistoryIndex () {
		if (!Renderer.dice._hist.length) {
			Renderer.dice._histIndex = null;
		} else {
			Renderer.dice._histIndex = Math.min(Renderer.dice._hist.length, Math.max(Renderer.dice._histIndex, 0));
		}
	}

	static _addHistory (str) {
		Renderer.dice._hist.push(str);
		// point index at the top of the stack
		Renderer.dice._histIndex = Renderer.dice._hist.length;
	}

	static _scrollBottom () {
		Renderer.dice._eleOutRoll.vee.scrollTop(1e10);
	}
	// endregion

	// region Event handling
	static RE_PROMPT = /#\$prompt_number:?([^$]*)\$#/g;

	static async pRollerClickUseData (evt, ele) {
		evt.stopPropagation();
		evt.preventDefault();

		ele = veE({ele});
		const rollData = JSON.parse(ele.vee.attr("data-packed-dice"));
		let name = ele.vee.attr("data-roll-name");
		let shiftKey = evt.shiftKey;
		let ctrlKey = EventUtil.isCtrlMetaKey(evt);

		const options = rollData.toRoll.split(";").map(it => it.trim()).filter(Boolean);

		let chosenRollData;
		if (options.length > 1) {
			const cpyRollData = MiscUtil.copyFast(rollData);
			const menu = ContextUtil.getMenu([
				new ContextUtil.Action(
					"Choose Roll",
					null,
					{isDisabled: true},
				),
				null,
				...options.map(rollOption => {
					return new ContextUtil.Action(
						`Roll ${rollOption.replace(/#\$prompt_number[^$]*\$#/g, "(𝑛)")}`,
						evt => {
							shiftKey = shiftKey || evt.shiftKey;
							ctrlKey = ctrlKey || (EventUtil.isCtrlMetaKey(evt));
							cpyRollData.toRoll = rollOption;
							return cpyRollData;
						},
					);
				}),
			]);

			chosenRollData = await ContextUtil.pOpenMenu(evt, menu);
		} else chosenRollData = rollData;

		if (!chosenRollData) return;

		const results = [];
		for (const m of chosenRollData.toRoll.matchAll(Renderer.dice.RE_PROMPT)) {
			const optionsRaw = m[1];
			const opts = {};
			if (optionsRaw) {
				const spl = optionsRaw.split(",");
				spl.map(it => it.trim()).forEach(part => {
					const [k, v] = part.split("=").map(it => it.trim());
					switch (k) {
						case "min":
						case "max":
							opts[k] = Number(v); break;
						default:
							opts[k] = v; break;
					}
				});
			}

			if (opts.min == null) opts.min = 0;
			if (opts.max == null) opts.max = Renderer.dice.POS_INFINITE;
			if (opts.default == null) opts.default = 0;

			const input = await InputUiUtil.pGetUserNumber(opts);
			if (input == null) return;
			results.push(input);
		}

		const rollDataCpy = MiscUtil.copyFast(chosenRollData);
		rollDataCpy.toRoll = rollDataCpy.toRoll.replace(Renderer.dice.RE_PROMPT, () => results.shift());

		// If there's a prompt, prompt the user to select the dice
		let rollDataCpyToRoll;
		if (rollData.prompt) {
			const sortedKeys = Object.keys(rollDataCpy.prompt.options).sort(SortUtil.ascSortLower);
			const menu = ContextUtil.getMenu([
				new ContextUtil.Action(rollDataCpy.prompt.entry, null, {isDisabled: true}),
				null,
				...sortedKeys
					.map(it => {
						const title = rollDataCpy.prompt.mode === "psi"
							? `${it} point${it === "1" ? "" : "s"}`
							: `${Parser.spLevelToFull(it)} level`;

						return new ContextUtil.Action(
							title,
							evt => {
								shiftKey = shiftKey || evt.shiftKey;
								ctrlKey = ctrlKey || (EventUtil.isCtrlMetaKey(evt));

								const fromScaling = rollDataCpy.prompt.options[it];
								if (!fromScaling) {
									name = "";
									return rollDataCpy;
								} else {
									name = rollDataCpy.prompt.mode === "psi" ? `${it} psi activation` : `${Parser.spLevelToFull(it)}-level cast`;
									rollDataCpy.toRoll += `+${fromScaling}`;
									return rollDataCpy;
								}
							},
						);
					}),
			]);

			rollDataCpyToRoll = await ContextUtil.pOpenMenu(evt, menu);
		} else rollDataCpyToRoll = rollDataCpy;

		if (!rollDataCpyToRoll) return;
		await Renderer.dice.pRollerClick({shiftKey, ctrlKey}, ele, JSON.stringify(rollDataCpyToRoll), name);
	}

	static __rerollNextInlineResult (ele) {
		ele = veE({ele});
		const result = ele.vee.next(`.result`);
		const r = Renderer.dice.__rollPackedData(ele);
		result.vee.txt(r);
	}

	static __rollPackedData (ele) {
		// Note that this does not support dynamic variables (e.g. user proficiency bonus)
		const wrpTree = Renderer.dice.lang.getTree3(ele.vee.attr("data-packed-dice").toRoll);
		return wrpTree.tree.evl({});
	}

	static getEleUnknownTableRoll (total) { return veE({outer: Renderer.dice._pRollerClick_getMsgBug(total)}); }

	static _pRollerClick_getMsgBug (total) { return `<span class="message">No result found matching roll ${total}?! <span class="ve-help-subtle" title="Bug!">🐛</span></span>`; }

	static async pRollerClick (evtMock, ele, packed, name) {
		ele = veE({ele});
		const entry = JSON.parse(packed);
		const additionalData = {...ele.dataset};

		const rolledBy = {
			name: Renderer.dice._pRollerClick_attemptToGetNameOfRoller({ele}),
			label: name != null ? name : Renderer.dice._pRollerClick_attemptToGetNameOfRoll({entry, ele}),
		};

		const modRollMeta = Renderer.dice.getEventModifiedRollMeta(evtMock, entry);
		const parent = ele.vee.closest("th, p, table");

		const rollResult = await this._pRollerClick_pGetResult({
			parent,
			ele,
			entry,
			modRollMeta,
			rolledBy,
			additionalData,
		});

		if (!entry.autoRoll) return;

		const tgt = ele.vee.next(`[data-rd-is-autodice-result="true"]`);
		const curTxt = tgt.vee.txt();
		tgt.vee.txt(rollResult);
		JqueryUtil.showCopiedEffect(tgt, {text: curTxt, isBubble: true});
	}

	static async _pRollerClick_pGetResult ({parent = null, ele, entry, modRollMeta, rolledBy, additionalData}) {
		const sharedRollOpts = {
			rollCount: modRollMeta.rollCount,
			additionalData,
			isHidden: !!entry.autoRoll,
		};

		if (parent?.vee.is("th") && parent.vee.attr("data-rd-isroller") === "true") {
			if (parent.vee.attr("data-rd-namegeneratorrolls")) {
				return Renderer.dice._pRollerClick_pRollGeneratorTable({
					parent,
					ele,
					rolledBy,
					modRollMeta,
					rollOpts: sharedRollOpts,
				});
			}

			return Renderer.dice.pRollEntry(
				modRollMeta.entry,
				rolledBy,
				{
					...sharedRollOpts,
					fnGetMessage: Renderer.dice._pRollerClick_fnGetMessageTable.bind(Renderer.dice, ele),
				},
			);
		}

		return Renderer.dice.pRollEntry(
			modRollMeta.entry,
			rolledBy,
			{
				...sharedRollOpts,
			},
		);
	}

	static _pRollerClick_fnGetMessageTable (ele, total) {
		const elesTd = Renderer.dice._pRollerClick_getTdsFromTotal(ele, total);
		if (elesTd) {
			const tableRow = elesTd.map(ele => ele.innerHTML.trim()).filter(Boolean).join(" | ");
			const row = veT`<span class="message">${tableRow}</span>`;
			Renderer.dice._pRollerClick_rollInlineRollers(ele);
			return row.vee.html();
		}
		return Renderer.dice._pRollerClick_getMsgBug(total);
	}

	// Aka "getTableName", probably
	static _pRollerClick_attemptToGetNameOfRoll ({entry, ele}) {
		// Try to use the entry's built-in name
		if (entry.name) return entry.name;

		const eleNameAncestor = ele.vee.closest(`[data-roll-name-ancestor]`);
		if (!eleNameAncestor) return "";

		const dataName = eleNameAncestor.vee.attr("data-roll-name-ancestor");
		if (dataName) return dataName;

		return eleNameAncestor.vee.txt().trim().replace(/[.,:]$/, "");
	}

	static _pRollerClick_attemptToGetNameOfRoller ({ele}) {
		const eleNameAncestor = ele.vee.closest(`[data-roll-name-ancestor-roller]`);
		if (eleNameAncestor) return eleNameAncestor.vee.attr("data-roll-name-ancestor-roller");

		const roll = ele.vee.closest(`[data-rollbox-last-rolled-by-name]`);
		if (roll) return roll.vee.attr("data-rollbox-last-rolled-by-name");

		const name = document.title.replace("- 5etools", "").trim();
		return name === "DM Screen" ? "Dungeon Master" : name;
	}

	static _pRollerClick_getTdsFromTotal (ele, total) {
		const table = ele.vee.closest(`table`);
		const tdRolls = table.vee.findAll("td")
			.filter(eleSub => {
				if (!eleSub.vee.closest(`table`).vee.is(table)) return false;
				return total >= Number(eleSub.vee.attr("data-roll-min")) && total <= Number(eleSub.vee.attr("data-roll-max"));
			});
		if (!tdRolls.length) return null;
		const [tdRoll] = tdRolls;
		const nxtAll = tdRoll.vee.nextAll();
		if (nxtAll.length) return nxtAll;
		return null;
	}

	static _pRollerClick_rollInlineRollers (ele) {
		ele.vee.findAll(`.render-roller`)
			.forEach(eleSub => {
				const r = Renderer.dice.__rollPackedData(eleSub);
				eleSub.vee.attr("onclick", `Renderer.dice.__rerollNextInlineResult(this)`);
				eleSub.vee.after(` (<span class="result">${r}</span>)`);
			});
	}

	static _pRollerClick_fnGetMessageGeneratorTable (ele, ix, total) {
		const elesTd = Renderer.dice._pRollerClick_getTdsFromTotal(ele, total);
		if (elesTd) {
			const row = veT`<span class="message">${elesTd[ix].innerHTML.trim()}</span>`;
			Renderer.dice._pRollerClick_rollInlineRollers(ele);
			return row.vee.html();
		}
		return Renderer.dice._pRollerClick_getMsgBug(total);
	}

	static async _pRollerClick_pRollGeneratorTable ({parent, ele, rolledBy, modRollMeta, rollOpts}) {
		Renderer.dice.addElement({rolledBy, html: `<i>${rolledBy.label}:</i>`, isMessage: true});

		// Track a total of all rolls--this is a bit meaningless, but this method is expected to return a result value
		let total = 0;

		const out = [];
		const numRolls = Number(parent.vee.attr("data-rd-namegeneratorrolls"));
		const ths = ele.vee.closest("table").vee.findAll("th");
		for (let i = 0; i < numRolls; ++i) {
			const cpyRolledBy = MiscUtil.copyFast(rolledBy);
			cpyRolledBy.label = ths[i + 1].vee.txt().trim();

			const result = await Renderer.dice.pRollEntry(
				modRollMeta.entry,
				cpyRolledBy,
				{
					...rollOpts,
					fnGetMessage: Renderer.dice._pRollerClick_fnGetMessageGeneratorTable.bind(Renderer.dice, ele, i),
				},
			);
			total += result;
			const elesTd = Renderer.dice._pRollerClick_getTdsFromTotal(ele, result);

			if (!elesTd) {
				out.push(`(no result)`);
				continue;
			}

			out.push(elesTd[i].innerHTML.trim());
		}

		Renderer.dice.addElement({rolledBy, html: `= ${out.join(" ")}`, isMessage: true});

		return total;
	}

	static getEventModifiedRollMeta (evt, entry) {
		// Change roll type/count depending on CTRL/SHIFT status
		const out = {rollCount: 1, entry};

		if (evt.shiftKey) {
			if (entry.subType === "damage") { // If SHIFT is held, roll crit
				const dice = [];
				// TODO(future) in order for this to correctly catch everything, would need to parse the toRoll as a tree and then pull all dice expressions from the first level of that tree
				entry.toRoll
					.replace(/\s+/g, "") // clean whitespace
					.replace(/\d*?d\d+/gi, m0 => dice.push(m0));
				entry.toRoll = `${entry.toRoll}${dice.length ? `+${dice.join("+")}` : ""}`;
			} else if (entry.subType === "d20") { // If SHIFT is held, roll advantage
				// If we have a cached d20mod value, use it
				if (entry.d20mod != null) entry.toRoll = `2d20dl1${entry.d20mod}`;
				else entry.toRoll = entry.toRoll.replace(/^\s*1?\s*d\s*20/, "2d20dl1");
			} else out.rollCount = 2; // otherwise, just roll twice
		}

		if (EventUtil.isCtrlMetaKey(evt)) {
			if (entry.subType === "damage") { // If CTRL is held, half the damage
				entry.toRoll = `floor((${entry.toRoll}) / 2)`;
			} else if (entry.subType === "d20") { // If CTRL is held, roll disadvantage (assuming SHIFT is not held)
				// If we have a cached d20mod value, use it
				if (entry.d20mod != null) entry.toRoll = `2d20dh1${entry.d20mod}`;
				else entry.toRoll = entry.toRoll.replace(/^\s*1?\s*d\s*20/, "2d20dh1");
			} else out.rollCount = 2; // otherwise, just roll twice
		}

		return out;
	}
	// endregion

	/**
	 * Parse and roll a string, and display the result in the roll box.
	 * Returns the total rolled, if available.
	 * @param str
	 * @param rolledBy
	 * @param rolledBy.isUser
	 * @param rolledBy.name The name of the roller.
	 * @param rolledBy.label The label for this roll.
	 * @param [opts] Options object.
	 * @param [opts.isResultUsed] If an input box should be provided for the user to enter the result (manual mode only).
	 */
	static async pRoll2 (str, rolledBy, opts) {
		opts = opts || {};
		str = str
			.trim()
			.replace(/\/r(?:oll)? /gi, "").trim() // Remove any leading "/r"s, for ease of use
		;
		if (!str) return;
		if (rolledBy.isUser) Renderer.dice._addHistory(str);

		if (str.startsWith("/")) return Renderer.dice._pHandleCommand(str, rolledBy);
		if (str.startsWith("#")) return Renderer.dice._pHandleSavedRoll(str, rolledBy, opts);

		const [head, ...tail] = str.split(":");
		if (tail.length) {
			str = tail.join(":");
			rolledBy.label = head;
		}
		const wrpTree = Renderer.dice.lang.getTree3(str);
		if (!wrpTree) return Renderer.dice._SYMBOL_PARSE_FAILED;
		return Renderer.dice._pHandleRoll2(wrpTree, rolledBy, opts);
	}

	/**
	 * Parse and roll an entry, and display the result in the roll box.
	 * Returns the total rolled, if available.
	 * @param entry
	 * @param rolledBy
	 * @param [opts] Options object.
	 * @param [opts.isResultUsed] If an input box should be provided for the user to enter the result (manual mode only).
	 * @param [opts.rollCount]
	 * @param [opts.additionalData]
	 * @param [opts.isHidden] If the result should not be posted to the rollbox.
	 */
	static async pRollEntry (entry, rolledBy, opts) {
		opts = opts || {};

		const rollCount = Math.round(opts.rollCount || 1);
		delete opts.rollCount;
		if (rollCount <= 0) throw new Error(`Invalid roll count: ${rollCount} (must be a positive integer)`);

		const wrpTree = Renderer.dice.lang.getTree3(entry.toRoll);
		wrpTree.tree.successThresh = entry.successThresh;
		wrpTree.tree.successMax = entry.successMax;
		wrpTree.tree.chanceSuccessText = entry.chanceSuccessText;
		wrpTree.tree.chanceFailureText = entry.chanceFailureText;
		wrpTree.tree.isColorSuccessFail = entry.isColorSuccessFail;

		// arbitrarily return the result of the highest roll if we roll multiple times
		const results = [];
		if (rollCount > 1 && !opts.isHidden) Renderer.dice._showMessage(`Rolling twice...`, rolledBy);
		for (let i = 0; i < rollCount; ++i) {
			const result = await Renderer.dice._pHandleRoll2(wrpTree, rolledBy, opts);
			if (result == null) return null;
			results.push(result);
		}
		return Math.max(...results);
	}

	/**
	 * @param wrpTree
	 * @param rolledBy
	 * @param [opts] Options object.
	 * @param [opts.fnGetMessage]
	 * @param [opts.isResultUsed]
	 * @param [opts.additionalData]
	 */
	static async _pHandleRoll2 (wrpTree, rolledBy, opts) {
		opts = {...opts};

		if (wrpTree.meta && wrpTree.meta.hasPb) {
			const userPb = await InputUiUtil.pGetUserNumber({
				min: 0,
				int: true,
				title: "Enter Proficiency Bonus",
				default: 2,
				storageKey_default: "dice.playerProficiencyBonus",
				isGlobal_default: true,
			});
			if (userPb == null) return null;
			opts.pb = userPb;
		}

		if (wrpTree.meta && wrpTree.meta.hasSummonSpellLevel) {
			const predefinedSpellLevel = opts.additionalData?.summonedBySpellLevel != null && !isNaN(opts.additionalData?.summonedBySpellLevel)
				? Number(opts.additionalData.summonedBySpellLevel)
				: null;

			const userSummonSpellLevel = await InputUiUtil.pGetUserNumber({
				min: predefinedSpellLevel ?? 0,
				int: true,
				title: "Enter Spell Level",
				default: predefinedSpellLevel ?? 1,
			});
			if (userSummonSpellLevel == null) return null;
			opts.summonSpellLevel = userSummonSpellLevel;
		}

		if (wrpTree.meta && wrpTree.meta.hasSummonClassLevel) {
			const predefinedClassLevel = opts.additionalData?.summonedByClassLevel != null && !isNaN(opts.additionalData?.summonedByClassLevel)
				? Number(opts.additionalData.summonedByClassLevel)
				: null;

			const userSummonClassLevel = await InputUiUtil.pGetUserNumber({
				min: predefinedClassLevel ?? 0,
				int: true,
				title: "Enter Class Level",
				default: predefinedClassLevel ?? 1,
			});
			if (userSummonClassLevel == null) return null;
			opts.summonClassLevel = userSummonClassLevel;
		}

		if (Renderer.dice._isManualMode) return Renderer.dice._pHandleRoll2_manual(wrpTree.tree, rolledBy, opts);
		else return Renderer.dice._pHandleRoll2_automatic(wrpTree.tree, rolledBy, opts);
	}

	/**
	 * @param tree
	 * @param rolledBy
	 * @param [opts] Options object.
	 * @param [opts.fnGetMessage]
	 * @param [opts.pb] User-entered proficiency bonus, to be propagated to the meta.
	 * @param [opts.summonSpellLevel] User-entered summon spell level, to be propagated to the meta.
	 * @param [opts.summonClassLevel] User-entered summon class level, to be propagated to the meta.
	 * @param [opts.target] Generic target number (e.g. save DC, AC) to meet/beat.
	 * @param [opts.isHidden] If the result should not be posted to the rollbox.
	 */
	static _pHandleRoll2_automatic (tree, rolledBy, opts) {
		opts = opts || {};

		if (!opts.isHidden) Renderer.dice._showBox();
		Renderer.dice._checkHandleName(rolledBy.name);
		const eleOut = Renderer.dice._eleLastRolledBy;

		if (tree) {
			const meta = {};
			if (opts.pb) meta.pb = opts.pb;
			if (opts.summonSpellLevel) meta.summonSpellLevel = opts.summonSpellLevel;
			if (opts.summonClassLevel) meta.summonClassLevel = opts.summonClassLevel;

			const result = tree.evl(meta);
			const fullHtml = (meta.html || []).join("");
			const formula = tree.toString();
			const fullText = (meta.text || []).join("")
				.replace(/\s+/g, " ")
				.trim();
			const allMax = meta.allMax && meta.allMax.length && !(meta.allMax.filter(it => !it).length);
			const allMin = meta.allMin && meta.allMin.length && !(meta.allMin.filter(it => !it).length);

			const lbl = rolledBy.label && (!rolledBy.name || rolledBy.label.trim().toLowerCase() !== rolledBy.name.trim().toLowerCase()) ? rolledBy.label : null;

			const ptTarget = opts.target != null
				? result >= opts.target ? ` <b>&geq;${opts.target}</b>` : ` <span class="ve-muted">&lt;${opts.target}</span>`
				: "";

			const isThreshSuccess = tree.successThresh != null && result > (tree.successMax || 100) - tree.successThresh;
			const isColorSuccess = tree.isColorSuccessFail || !tree.chanceSuccessText;
			const isColorFail = tree.isColorSuccessFail || !tree.chanceFailureText;
			const totalPart = tree.successThresh != null
				? `<span class="roll ${isThreshSuccess && isColorSuccess ? "roll-max" : !isThreshSuccess && isColorFail ? "roll-min" : ""}">${isThreshSuccess ? Renderer.get().render(tree.chanceSuccessText || "Success!") : Renderer.get().render(tree.chanceFailureText || "Failure")}</span>`
				: `<span class="roll ${allMax ? "roll-max" : allMin ? "roll-min" : ""}">${result}</span>`;

			const ptTitle = [
				rolledBy.name,
				lbl,
				formula,
				fullText,
			]
				.filter(Boolean)
				.join(" \u2014 ");

			const message = opts.fnGetMessage ? opts.fnGetMessage(result) : null;
			ExtensionUtil.doSendRoll({
				dice: formula,
				result,
				rolledBy: rolledBy.name,
				label: [lbl, message].filter(Boolean).join(" \u2013 "),
			});

			if (!opts.isHidden) {
				const btnCopyToInput = veT`<button title="Copy to Input" class="ve-btn ve-btn-default ve-btn-xs ve-btn-copy-roll"><span class="glyphicon glyphicon-pencil"></span></button>`
					.vee.onn("click", () => {
						Renderer.dice._iptRoll
							.vee.val(formula.replace(/\s+/g, ""))
							.vee.focus();
					});

				veT`<div class="out-roll-item" title="${ptTitle.qq()}">
					<div>
						${lbl ? `<span class="roll-label">${lbl}: </span>` : ""}
						${totalPart}
						${ptTarget}
						<span class="ve-muted ve-italic ve-small">${formula.qq()}</span>
						\u21d2
						<span class="ve-muted">${fullHtml}</span>
						${message ? `<span class="message">${message}</span>` : ""}
					</div>
					<div class="out-roll-item-button-wrp">${btnCopyToInput}</div>
				</div>`
					.vee.appendTo(eleOut);

				Renderer.dice._scrollBottom();
			}

			return result;
		} else {
			if (!opts.isHidden) {
				eleOut.vee.appends(`<div class="out-roll-item">Invalid input! Try &quot;/help&quot;</div>`);
				Renderer.dice._scrollBottom();
			}
			return null;
		}
	}

	static _pHandleRoll2_manual (tree, rolledBy, opts) {
		opts = opts || {};

		if (!tree) return JqueryUtil.doToast({type: "danger", content: `Invalid roll input!`});

		const title = (rolledBy.label || "").toTitleCase() || "Roll Dice";
		const dispDice = veT`<div class="ve-p-2 ve-bold ve-flex-vh-center rll__prompt-header">${tree.toString()}</div>`;
		if (opts.isResultUsed) {
			return InputUiUtil.pGetUserNumber({
				title,
				elePre: dispDice,
			});
		} else {
			const {eleModalInner} = UiUtil.getShowModal({
				title,
				isMinHeight0: true,
			});
			dispDice.vee.appendTo(eleModalInner);
			return null;
		}
	}

	static _showMessage (message, rolledBy) {
		Renderer.dice._showBox();
		Renderer.dice._checkHandleName(rolledBy.name);
		const eleOut = Renderer.dice._eleLastRolledBy;
		eleOut.vee.appends(`<div class="out-roll-item out-roll-item--message">${message}</div>`);
		Renderer.dice._scrollBottom();
	}

	static _showInvalid () {
		Renderer.dice._showMessage("Invalid input! Try &quot;/help&quot;", Renderer.dice.SYSTEM_USER);
	}

	static _validCommands = new Set(["/c", "/cls", "/clear", "/iterroll"]);

	static async _pHandleCommand (com, rolledBy) {
		Renderer.dice._showMessage(`<span class="out-roll-item-code">${com}</span>`, rolledBy); // parrot the user's command back to them

		const comParsed = Renderer.dice._getParsedCommand(com);
		const [comOp] = comParsed;

		if (comOp === "/help" || comOp === "/h") {
			Renderer.dice._showMessage(
				`<ul class="rll__list">
					<li>Keep highest; <span class="out-roll-item-code">4d6kh3</span></li>
					<li>Drop lowest; <span class="out-roll-item-code">4d6dl1</span></li>
					<li>Drop highest; <span class="out-roll-item-code">3d4dh1</span></li>
					<li>Keep lowest; <span class="out-roll-item-code">3d4kl1</span></li>

					<li>Reroll equal; <span class="out-roll-item-code">2d4r1</span></li>
					<li>Reroll less; <span class="out-roll-item-code">2d4r&lt;2</span></li>
					<li>Reroll less or equal; <span class="out-roll-item-code">2d4r&lt;=2</span></li>
					<li>Reroll greater; <span class="out-roll-item-code">2d4r&gt;2</span></li>
					<li>Reroll greater equal; <span class="out-roll-item-code">2d4r&gt;=3</span></li>

					<li>Explode equal; <span class="out-roll-item-code">2d4x4</span></li>
					<li>Explode less; <span class="out-roll-item-code">2d4x&lt;2</span></li>
					<li>Explode less or equal; <span class="out-roll-item-code">2d4x&lt;=2</span></li>
					<li>Explode greater; <span class="out-roll-item-code">2d4x&gt;2</span></li>
					<li>Explode greater equal; <span class="out-roll-item-code">2d4x&gt;=3</span></li>

					<li>Count Successes equal; <span class="out-roll-item-code">2d4cs=4</span></li>
					<li>Count Successes less; <span class="out-roll-item-code">2d4cs&lt;2</span></li>
					<li>Count Successes less or equal; <span class="out-roll-item-code">2d4cs&lt;=2</span></li>
					<li>Count Successes greater; <span class="out-roll-item-code">2d4cs&gt;2</span></li>
					<li>Count Successes greater equal; <span class="out-roll-item-code">2d4cs&gt;=3</span></li>

					<li>Margin of Success; <span class="out-roll-item-code">2d4ms=4</span></li>

					<li>Dice pools; <span class="out-roll-item-code">{2d8, 1d6}</span></li>
					<li>Dice pools with modifiers; <span class="out-roll-item-code">{1d20+7, 10}kh1</span></li>

					<li>Rounding; <span class="out-roll-item-code">floor(1.5)</span>, <span class="out-roll-item-code">ceil(1.5)</span>, <span class="out-roll-item-code">round(1.5)</span></li>

					<li>Average; <span class="out-roll-item-code">avg(8d6)</span></li>
					<li>Maximize dice; <span class="out-roll-item-code">dmax(8d6)</span></li>
					<li>Minimize dice; <span class="out-roll-item-code">dmin(8d6)</span></li>

					<li>Other functions; <span class="out-roll-item-code">sign(1d6-3)</span>, <span class="out-roll-item-code">abs(1d6-3)</span>, ...etc.</li>
				</ul>
				Up and down arrow keys cycle input history.<br>
				Anything before a colon is treated as a label (<span class="out-roll-item-code">Fireball: 8d6</span>)<br>
Use <span class="out-roll-item-code">/macro list</span> to list saved macros.<br>
				Use <span class="out-roll-item-code">/macro add myName 1d2+3</span> to add (or update) a macro. Macro names should not contain spaces or hashes.<br>
				Use <span class="out-roll-item-code">/macro remove myName</span> to remove a macro.<br>
				Use <span class="out-roll-item-code">#myName</span> to roll a macro.<br>
				Use <span class="out-roll-item-code">/iterroll roll count [target]</span> to roll multiple times, optionally against a target.
				Use <span class="out-roll-item-code">/clear</span> to clear the roller.`,
				Renderer.dice.SYSTEM_USER,
			);
			return;
		}

		if (comOp === "/macro") {
			const [, mode, ...others] = comParsed;

			if (!["list", "add", "remove", "clear"].includes(mode)) Renderer.dice._showInvalid();
			else {
				switch (mode) {
					case "list":
						if (!others.length) {
							Object.keys(Renderer.dice.storage).forEach(name => {
								Renderer.dice._showMessage(`<span class="out-roll-item-code">#${name}</span> \u2014 ${Renderer.dice.storage[name]}`, Renderer.dice.SYSTEM_USER);
							});
						} else {
							Renderer.dice._showInvalid();
						}
						break;
					case "add": {
						if (others.length === 2) {
							const [name, macro] = others;
							if (name.includes(" ") || name.includes("#")) Renderer.dice._showInvalid();
							else {
								Renderer.dice.storage[name] = macro;
								await Renderer.dice._pSaveMacros();
								Renderer.dice._showMessage(`Saved macro <span class="out-roll-item-code">#${name}</span>`, Renderer.dice.SYSTEM_USER);
							}
						} else {
							Renderer.dice._showInvalid();
						}
						break;
					}
					case "remove":
						if (others.length === 1) {
							if (Renderer.dice.storage[others[0]]) {
								delete Renderer.dice.storage[others[0]];
								await Renderer.dice._pSaveMacros();
								Renderer.dice._showMessage(`Removed macro <span class="out-roll-item-code">#${others[0]}</span>`, Renderer.dice.SYSTEM_USER);
							} else {
								Renderer.dice._showMessage(`Macro <span class="out-roll-item-code">#${others[0]}</span> not found`, Renderer.dice.SYSTEM_USER);
							}
						} else {
							Renderer.dice._showInvalid();
						}
						break;
				}
			}
			return;
		}

		if (Renderer.dice._validCommands.has(comOp)) {
			switch (comOp) {
				case "/c":
				case "/cls":
				case "/clear":
					Renderer.dice._eleOutRoll.vee.empty();
					Renderer.dice._eleLastRolledBy.vee.empty();
					Renderer.dice._eleLastRolledBy = null;
					return;

				case "/iterroll": {
					let [, exp, count, target] = comParsed;

					if (!exp) return Renderer.dice._showInvalid();
					const wrpTree = Renderer.dice.lang.getTree3(exp);
					if (!wrpTree) return Renderer.dice._showInvalid();

					count = count && !isNaN(count) ? Number(count) : 1;
					target = target && !isNaN(target) ? Number(target) : undefined;

					for (let i = 0; i < count; ++i) {
						await Renderer.dice.pRoll2(
							exp,
							{
								name: "Anon",
							},
							{
								target,
							},
						);
					}
				}
			}
			return;
		}

		Renderer.dice._showInvalid();
	}

	static async _pSaveMacros () {
		await StorageUtil.pSet(VeCt.STORAGE_ROLLER_MACRO, Renderer.dice.storage);
	}

	static _getParsedCommand (str) {
		// TODO(Future) this is probably too naive
		return str.split(/\s+/);
	}

	static _pHandleSavedRoll (id, rolledBy, opts) {
		id = id.replace(/^#/, "");
		const macro = Renderer.dice.storage[id];
		if (macro) {
			rolledBy.label = id;
			const wrpTree = Renderer.dice.lang.getTree3(macro);
			return Renderer.dice._pHandleRoll2(wrpTree, rolledBy, opts);
		} else Renderer.dice._showMessage(`Macro <span class="out-roll-item-code">#${id}</span> not found`, Renderer.dice.SYSTEM_USER);
	}

	static addRoll ({rolledBy, html, ele}) {
		if ([html, ele].filter(Boolean).length !== 1) throw new Error(`Must specify one of html or ele!`);

		if (html != null && !html.trim()) return;

		Renderer.dice._showBox();
		Renderer.dice._checkHandleName(rolledBy.name);

		if (html) {
			Renderer.dice._eleLastRolledBy.vee.appends(`<div class="out-roll-item" title="${(rolledBy.name || "").qq()}">${html}</div>`);
		} else {
			veT`<div class="out-roll-item" title="${(rolledBy.name || "").qq()}">${ele}</div>`
				.vee.appendTo(Renderer.dice._eleLastRolledBy);
		}

		Renderer.dice._scrollBottom();
	}

	static addElement ({rolledBy, html, ele}) {
		if (html && ele) throw new Error(`Must specify one of html or ele!`);

		if (html != null && !html.trim()) return;

		Renderer.dice._showBox();
		Renderer.dice._checkHandleName(rolledBy.name);

		if (html) {
			Renderer.dice._eleLastRolledBy.vee.appends(`<div class="out-roll-item out-roll-item--message" title="${(rolledBy.name || "").qq()}">${html}</div>`);
		} else {
			veT`<div class="out-roll-item out-roll-item--message" title="${(rolledBy.name || "").qq()}">${ele}</div>`
				.vee.appendTo(Renderer.dice._eleLastRolledBy);
		}

		Renderer.dice._scrollBottom();
	}

	static _checkHandleName (name) {
		if (!Renderer.dice._eleLastRolledBy || Renderer.dice._eleLastRolledBy.vee.attr("data-rollbox-last-rolled-by-name") !== name) {
			Renderer.dice._eleOutRoll.vee.prepends(`<div class="ve-muted out-roll-id">${name}</div>`);
			Renderer.dice._eleLastRolledBy = veT`<div class="out-roll-wrp" data-rollbox-last-rolled-by-name="${name.qq()}"></div>`;
			Renderer.dice._eleOutRoll.vee.prepends(Renderer.dice._eleLastRolledBy);
		}
	}
};

Renderer.dice.util = class {
	static getReducedMeta (meta) {
		return {
			pb: meta.pb,
			summonSpellLevel: meta.summonSpellLevel,
			summonClassLevel: meta.summonClassLevel,
		};
	}
};

Renderer.dice.lang = class {
	// region Public API
	static validate3 (str) {
		str = str.trim();

		// region Lexing
		let lexed;
		try {
			lexed = Renderer.dice.lang._lex3(str).lexed;
		} catch (e) {
			return e.message;
		}
		// endregion

		// region Parsing
		try {
			Renderer.dice.lang._parse3(lexed);
		} catch (e) {
			return e.message;
		}
		// endregion

		return null;
	}

	static getTree3 (str, isSilent = true) {
		str = str.trim();
		if (isSilent) {
			try {
				const {lexed, lexedMeta} = Renderer.dice.lang._lex3(str);
				return {tree: Renderer.dice.lang._parse3(lexed), meta: lexedMeta};
			} catch (e) {
				return null;
			}
		} else {
			const {lexed, lexedMeta} = Renderer.dice.lang._lex3(str);
			return {tree: Renderer.dice.lang._parse3(lexed), meta: lexedMeta};
		}
	}
	// endregion

	// region Lexer
	static _M_NUMBER_CHAR = /[0-9.]/;

	static _M_SYMBOL_CHAR = /[-+/*^=><florceidhkxunavgsmpbtqw,]/;

	static _M_NUMBER = /^[\d.,]+$/;

	static _lex3 (str) {
		const self = {
			tokenStack: [],
			parenCount: 0,
			braceCount: 0,
			mode: null,
			token: "",
			hasPb: false,
			hasSummonSpellLevel: false,
			hasSummonClassLevel: false,
		};

		str = str
			.trim()
			.replace(/\bPBd(?=\d)/g, "(PB)d") // Convert case-sensitive leading PB
			.toLowerCase()
			// region Convert some natural language
			.replace(/\s*?\bplus\b\s*?/g, " + ")
			.replace(/\s*?\bminus\b\s*?/g, " - ")
			.replace(/\s*?\btimes\b\s*?/g, " * ")
			.replace(/\s*?\bover\b\s*?/g, " / ")
			.replace(/\s*?\bdivided by\b\s*?/g, " / ")
			// endregion
			.replace(/\s+/g, "")
			.replace(/[\u2012-\u2014\u2212]/g, "-") // convert dashes
			.replace(/[×]/g, "*") // convert mult signs
			.replace(/\*\*/g, "^") // convert ** to ^
			.replace(/÷/g, "/") // convert div signs
			.replace(/--/g, "+") // convert double negatives
			.replace(/\+-|-\+/g, "-") // convert negatives
		;

		if (!str) return {lexed: [], lexedMeta: {}};

		this._lex3_lex(self, str);

		return {lexed: self.tokenStack, lexedMeta: {hasPb: self.hasPb, hasSummonSpellLevel: self.hasSummonSpellLevel, hasSummonClassLevel: self.hasSummonClassLevel}};
	}

	static _lex3_lex (self, l) {
		const len = l.length;

		for (let i = 0; i < len; ++i) {
			const c = l[i];

			switch (c) {
				case "(":
					self.parenCount++;
					this._lex3_outputToken(self);
					self.token = "(";
					this._lex3_outputToken(self);
					break;
				case ")":
					self.parenCount--;
					if (self.parenCount < 0) throw new Error(`Syntax error: closing <code>)</code> without opening <code>(</code>`);
					this._lex3_outputToken(self);
					self.token = ")";
					this._lex3_outputToken(self);
					break;
				case "{":
					self.braceCount++;
					this._lex3_outputToken(self);
					self.token = "{";
					this._lex3_outputToken(self);
					break;
				case "}":
					self.braceCount--;
					if (self.parenCount < 0) throw new Error(`Syntax error: closing <code>}</code> without opening <code>(</code>`);
					this._lex3_outputToken(self);
					self.token = "}";
					this._lex3_outputToken(self);
					break;
				// single-character operators
				case "+": case "-": case "*": case "/": case "^": case ",":
					this._lex3_outputToken(self);
					self.token += c;
					this._lex3_outputToken(self);
					break;
				default: {
					if (Renderer.dice.lang._M_NUMBER_CHAR.test(c)) {
						if (self.mode === "symbol") this._lex3_outputToken(self);
						self.token += c;
						self.mode = "text";
					} else if (Renderer.dice.lang._M_SYMBOL_CHAR.test(c)) {
						if (self.mode === "text") this._lex3_outputToken(self);
						self.token += c;
						self.mode = "symbol";
					} else throw new Error(`Syntax error: unexpected character <code>${c}</code>`);
					break;
				}
			}
		}

		// empty the stack of any remaining content
		this._lex3_outputToken(self);
	}

	static _lex3_outputToken (self) {
		if (!self.token) return;

		switch (self.token) {
			case "(": self.tokenStack.push(Renderer.dice.tk.PAREN_OPEN); break;
			case ")": self.tokenStack.push(Renderer.dice.tk.PAREN_CLOSE); break;
			case "{": self.tokenStack.push(Renderer.dice.tk.BRACE_OPEN); break;
			case "}": self.tokenStack.push(Renderer.dice.tk.BRACE_CLOSE); break;
			case ",": self.tokenStack.push(Renderer.dice.tk.COMMA); break;
			case "+": self.tokenStack.push(Renderer.dice.tk.ADD); break;
			case "-": self.tokenStack.push(Renderer.dice.tk.SUB); break;
			case "*": self.tokenStack.push(Renderer.dice.tk.MULT); break;
			case "/": self.tokenStack.push(Renderer.dice.tk.DIV); break;
			case "^": self.tokenStack.push(Renderer.dice.tk.POW); break;
			case "pb": self.tokenStack.push(Renderer.dice.tk.PB); self.hasPb = true; break;
			case "summonspelllevel": self.tokenStack.push(Renderer.dice.tk.SUMMON_SPELL_LEVEL); self.hasSummonSpellLevel = true; break;
			case "summonclasslevel": self.tokenStack.push(Renderer.dice.tk.SUMMON_CLASS_LEVEL); self.hasSummonClassLevel = true; break;
			case "floor": self.tokenStack.push(Renderer.dice.tk.FLOOR); break;
			case "ceil": self.tokenStack.push(Renderer.dice.tk.CEIL); break;
			case "round": self.tokenStack.push(Renderer.dice.tk.ROUND); break;
			case "avg": self.tokenStack.push(Renderer.dice.tk.AVERAGE); break;
			case "dmax": self.tokenStack.push(Renderer.dice.tk.DMAX); break;
			case "dmin": self.tokenStack.push(Renderer.dice.tk.DMIN); break;
			case "sign": self.tokenStack.push(Renderer.dice.tk.SIGN); break;
			case "abs": self.tokenStack.push(Renderer.dice.tk.ABS); break;
			case "cbrt": self.tokenStack.push(Renderer.dice.tk.CBRT); break;
			case "sqrt": self.tokenStack.push(Renderer.dice.tk.SQRT); break;
			case "exp": self.tokenStack.push(Renderer.dice.tk.EXP); break;
			case "log": self.tokenStack.push(Renderer.dice.tk.LOG); break;
			case "random": self.tokenStack.push(Renderer.dice.tk.RANDOM); break;
			case "trunc": self.tokenStack.push(Renderer.dice.tk.TRUNC); break;
			case "pow": self.tokenStack.push(Renderer.dice.tk.POW); break;
			case "max": self.tokenStack.push(Renderer.dice.tk.MAX); break;
			case "min": self.tokenStack.push(Renderer.dice.tk.MIN); break;
			case "d": self.tokenStack.push(Renderer.dice.tk.DICE); break;
			case "dh": self.tokenStack.push(Renderer.dice.tk.DROP_HIGHEST); break;
			case "kh": self.tokenStack.push(Renderer.dice.tk.KEEP_HIGHEST); break;
			case "dl": self.tokenStack.push(Renderer.dice.tk.DROP_LOWEST); break;
			case "kl": self.tokenStack.push(Renderer.dice.tk.KEEP_LOWEST); break;
			case "r": self.tokenStack.push(Renderer.dice.tk.REROLL_EXACT); break;
			case "r>": self.tokenStack.push(Renderer.dice.tk.REROLL_GT); break;
			case "r>=": self.tokenStack.push(Renderer.dice.tk.REROLL_GTEQ); break;
			case "r<": self.tokenStack.push(Renderer.dice.tk.REROLL_LT); break;
			case "r<=": self.tokenStack.push(Renderer.dice.tk.REROLL_LTEQ); break;
			case "x": self.tokenStack.push(Renderer.dice.tk.EXPLODE_EXACT); break;
			case "x>": self.tokenStack.push(Renderer.dice.tk.EXPLODE_GT); break;
			case "x>=": self.tokenStack.push(Renderer.dice.tk.EXPLODE_GTEQ); break;
			case "x<": self.tokenStack.push(Renderer.dice.tk.EXPLODE_LT); break;
			case "x<=": self.tokenStack.push(Renderer.dice.tk.EXPLODE_LTEQ); break;
			case "cs=": self.tokenStack.push(Renderer.dice.tk.COUNT_SUCCESS_EXACT); break;
			case "cs>": self.tokenStack.push(Renderer.dice.tk.COUNT_SUCCESS_GT); break;
			case "cs>=": self.tokenStack.push(Renderer.dice.tk.COUNT_SUCCESS_GTEQ); break;
			case "cs<": self.tokenStack.push(Renderer.dice.tk.COUNT_SUCCESS_LT); break;
			case "cs<=": self.tokenStack.push(Renderer.dice.tk.COUNT_SUCCESS_LTEQ); break;
			case "ms=": self.tokenStack.push(Renderer.dice.tk.MARGIN_SUCCESS_EXACT); break;
			case "ms>": self.tokenStack.push(Renderer.dice.tk.MARGIN_SUCCESS_GT); break;
			case "ms>=": self.tokenStack.push(Renderer.dice.tk.MARGIN_SUCCESS_GTEQ); break;
			case "ms<": self.tokenStack.push(Renderer.dice.tk.MARGIN_SUCCESS_LT); break;
			case "ms<=": self.tokenStack.push(Renderer.dice.tk.MARGIN_SUCCESS_LTEQ); break;
			default: {
				if (Renderer.dice.lang._M_NUMBER.test(self.token)) {
					if (self.token.split(Parser._decimalSeparator).length > 2) throw new Error(`Syntax error: too many decimal separators <code>${self.token}</code>`);
					self.tokenStack.push(Renderer.dice.tk.NUMBER(self.token));
				} else throw new Error(`Syntax error: unexpected token <code>${self.token}</code>`);
			}
		}

		self.token = "";
	}
	// endregion

	// region Parser
	static _parse3 (lexed) {
		const self = {
			ixSym: -1,
			syms: lexed,
			sym: null,
			lastAccepted: null,
			// Workaround for comma-separated numbers--if we're e.g. inside a dice pool, treat the commas as dice pool
			//   separators. Otherwise, merge together adjacent numbers, to convert e.g. "1,000,000" to "1000000".
			isIgnoreCommas: true,
		};

		this._parse3_nextSym(self);
		return this._parse3_expression(self);
	}

	static _parse3_nextSym (self) {
		const cur = self.syms[self.ixSym];
		self.ixSym++;
		self.sym = self.syms[self.ixSym];
		return cur;
	}

	static _parse3_match (self, symbol) {
		if (self.sym == null) return false;
		if (symbol.type) symbol = symbol.type; // If it's a typed token, convert it to its underlying type
		return self.sym.type === symbol;
	}

	static _parse3_accept (self, symbol) {
		if (this._parse3_match(self, symbol)) {
			const out = self.sym;
			this._parse3_nextSym(self);
			self.lastAccepted = out;
			return out;
		}
		return false;
	}

	static _parse3_expect (self, symbol) {
		const accepted = this._parse3_accept(self, symbol);
		if (accepted) return accepted;
		if (self.sym) throw new Error(`Unexpected input: Expected <code>${symbol}</code> but found <code>${self.sym}</code>`);
		else throw new Error(`Unexpected end of input: Expected <code>${symbol}</code>`);
	}

	static _parse3_factor (self, {isSilent = false} = {}) {
		if (this._parse3_accept(self, Renderer.dice.tk.TYP_NUMBER)) {
			// Workaround for comma-separated numbers
			if (self.isIgnoreCommas) {
				// Combine comma-separated parts
				const syms = [self.lastAccepted];
				while (this._parse3_accept(self, Renderer.dice.tk.COMMA)) {
					const sym = this._parse3_expect(self, Renderer.dice.tk.TYP_NUMBER);
					syms.push(sym);
				}
				const sym = Renderer.dice.tk.NUMBER(syms.map(it => it.value).join(""));
				return new Renderer.dice.parsed.Factor(sym);
			}

			return new Renderer.dice.parsed.Factor(self.lastAccepted);
		} else if (this._parse3_accept(self, Renderer.dice.tk.PB)) {
			return new Renderer.dice.parsed.Factor(Renderer.dice.tk.PB);
		} else if (this._parse3_accept(self, Renderer.dice.tk.SUMMON_SPELL_LEVEL)) {
			return new Renderer.dice.parsed.Factor(Renderer.dice.tk.SUMMON_SPELL_LEVEL);
		} else if (this._parse3_accept(self, Renderer.dice.tk.SUMMON_CLASS_LEVEL)) {
			return new Renderer.dice.parsed.Factor(Renderer.dice.tk.SUMMON_CLASS_LEVEL);
		} else if (
			// Single-arg functions
			this._parse3_match(self, Renderer.dice.tk.FLOOR)
			|| this._parse3_match(self, Renderer.dice.tk.CEIL)
			|| this._parse3_match(self, Renderer.dice.tk.ROUND)
			|| this._parse3_match(self, Renderer.dice.tk.AVERAGE)
			|| this._parse3_match(self, Renderer.dice.tk.DMAX)
			|| this._parse3_match(self, Renderer.dice.tk.DMIN)
			|| this._parse3_match(self, Renderer.dice.tk.SIGN)
			|| this._parse3_match(self, Renderer.dice.tk.ABS)
			|| this._parse3_match(self, Renderer.dice.tk.CBRT)
			|| this._parse3_match(self, Renderer.dice.tk.SQRT)
			|| this._parse3_match(self, Renderer.dice.tk.EXP)
			|| this._parse3_match(self, Renderer.dice.tk.LOG)
			|| this._parse3_match(self, Renderer.dice.tk.RANDOM)
			|| this._parse3_match(self, Renderer.dice.tk.TRUNC)
		) {
			const children = [];

			children.push(this._parse3_nextSym(self));
			this._parse3_expect(self, Renderer.dice.tk.PAREN_OPEN);
			children.push(this._parse3_expression(self));
			this._parse3_expect(self, Renderer.dice.tk.PAREN_CLOSE);

			return new Renderer.dice.parsed.Function(children);
		} else if (
			// 2-arg functions
			this._parse3_match(self, Renderer.dice.tk.POW)
		) {
			self.isIgnoreCommas = false;

			const children = [];

			children.push(this._parse3_nextSym(self));
			this._parse3_expect(self, Renderer.dice.tk.PAREN_OPEN);
			children.push(this._parse3_expression(self));
			this._parse3_expect(self, Renderer.dice.tk.COMMA);
			children.push(this._parse3_expression(self));
			this._parse3_expect(self, Renderer.dice.tk.PAREN_CLOSE);

			self.isIgnoreCommas = true;

			return new Renderer.dice.parsed.Function(children);
		} else if (
			// N-arg functions
			this._parse3_match(self, Renderer.dice.tk.MAX)
			|| this._parse3_match(self, Renderer.dice.tk.MIN)
		) {
			self.isIgnoreCommas = false;

			const children = [];

			children.push(this._parse3_nextSym(self));
			this._parse3_expect(self, Renderer.dice.tk.PAREN_OPEN);
			children.push(this._parse3_expression(self));
			while (this._parse3_accept(self, Renderer.dice.tk.COMMA)) children.push(this._parse3_expression(self));
			this._parse3_expect(self, Renderer.dice.tk.PAREN_CLOSE);

			self.isIgnoreCommas = true;

			return new Renderer.dice.parsed.Function(children);
		} else if (this._parse3_accept(self, Renderer.dice.tk.PAREN_OPEN)) {
			const exp = this._parse3_expression(self);
			this._parse3_expect(self, Renderer.dice.tk.PAREN_CLOSE);
			return new Renderer.dice.parsed.Factor(exp, {hasParens: true});
		} else if (this._parse3_accept(self, Renderer.dice.tk.BRACE_OPEN)) {
			self.isIgnoreCommas = false;

			const children = [];

			children.push(this._parse3_expression(self));
			while (this._parse3_accept(self, Renderer.dice.tk.COMMA)) children.push(this._parse3_expression(self));

			this._parse3_expect(self, Renderer.dice.tk.BRACE_CLOSE);

			self.isIgnoreCommas = true;

			const modPart = [];
			this._parse3__dice_modifiers(self, modPart);

			return new Renderer.dice.parsed.Pool(children, modPart[0]);
		} else {
			if (isSilent) return null;

			if (self.sym) throw new Error(`Unexpected input: <code>${self.sym}</code>`);
			else throw new Error(`Unexpected end of input`);
		}
	}

	static _parse3_dice (self) {
		const children = [];

		// if we've omitted the X in XdY, add it here
		if (this._parse3_match(self, Renderer.dice.tk.DICE)) children.push(new Renderer.dice.parsed.Factor(Renderer.dice.tk.NUMBER(1)));
		else children.push(this._parse3_factor(self));

		while (this._parse3_match(self, Renderer.dice.tk.DICE)) {
			this._parse3_nextSym(self);
			children.push(this._parse3_factor(self));
			this._parse3__dice_modifiers(self, children);
		}
		return new Renderer.dice.parsed.Dice(children);
	}

	static _parse3__dice_modifiers (self, children) { // used in both dice and dice pools
		// Collect together all dice mods
		const modsMeta = new Renderer.dice.lang.DiceModMeta();

		while (
			this._parse3_match(self, Renderer.dice.tk.DROP_HIGHEST)
			|| this._parse3_match(self, Renderer.dice.tk.KEEP_HIGHEST)
			|| this._parse3_match(self, Renderer.dice.tk.DROP_LOWEST)
			|| this._parse3_match(self, Renderer.dice.tk.KEEP_LOWEST)
			|| this._parse3_match(self, Renderer.dice.tk.REROLL_EXACT)
			|| this._parse3_match(self, Renderer.dice.tk.REROLL_GT)
			|| this._parse3_match(self, Renderer.dice.tk.REROLL_GTEQ)
			|| this._parse3_match(self, Renderer.dice.tk.REROLL_LT)
			|| this._parse3_match(self, Renderer.dice.tk.REROLL_LTEQ)
			|| this._parse3_match(self, Renderer.dice.tk.EXPLODE_EXACT)
			|| this._parse3_match(self, Renderer.dice.tk.EXPLODE_GT)
			|| this._parse3_match(self, Renderer.dice.tk.EXPLODE_GTEQ)
			|| this._parse3_match(self, Renderer.dice.tk.EXPLODE_LT)
			|| this._parse3_match(self, Renderer.dice.tk.EXPLODE_LTEQ)
			|| this._parse3_match(self, Renderer.dice.tk.COUNT_SUCCESS_EXACT)
			|| this._parse3_match(self, Renderer.dice.tk.COUNT_SUCCESS_GT)
			|| this._parse3_match(self, Renderer.dice.tk.COUNT_SUCCESS_GTEQ)
			|| this._parse3_match(self, Renderer.dice.tk.COUNT_SUCCESS_LT)
			|| this._parse3_match(self, Renderer.dice.tk.COUNT_SUCCESS_LTEQ)
			|| this._parse3_match(self, Renderer.dice.tk.MARGIN_SUCCESS_EXACT)
			|| this._parse3_match(self, Renderer.dice.tk.MARGIN_SUCCESS_GT)
			|| this._parse3_match(self, Renderer.dice.tk.MARGIN_SUCCESS_GTEQ)
			|| this._parse3_match(self, Renderer.dice.tk.MARGIN_SUCCESS_LT)
			|| this._parse3_match(self, Renderer.dice.tk.MARGIN_SUCCESS_LTEQ)
		) {
			const nxtSym = this._parse3_nextSym(self);
			const nxtFactor = this._parse3__dice_modifiers_nxtFactor(self, nxtSym);

			if (nxtSym.isSuccessMode) modsMeta.isSuccessMode = true;
			modsMeta.mods.push({modSym: nxtSym, numSym: nxtFactor});
		}

		if (modsMeta.mods.length) children.push(modsMeta);
	}

	static _parse3__dice_modifiers_nxtFactor (self, nxtSym) {
		if (nxtSym.diceModifierImplicit == null) return this._parse3_factor(self, {isSilent: true});

		const fallback = new Renderer.dice.parsed.Factor(Renderer.dice.tk.NUMBER(nxtSym.diceModifierImplicit));
		if (self.sym == null) return fallback;

		const out = this._parse3_factor(self, {isSilent: true});
		if (out) return out;

		return fallback;
	}

	static _parse3_exponent (self) {
		const children = [];
		children.push(this._parse3_dice(self));
		while (this._parse3_match(self, Renderer.dice.tk.POW)) {
			this._parse3_nextSym(self);
			children.push(this._parse3_dice(self));
		}
		return new Renderer.dice.parsed.Exponent(children);
	}

	static _parse3_term (self) {
		const children = [];
		children.push(this._parse3_exponent(self));
		while (this._parse3_match(self, Renderer.dice.tk.MULT) || this._parse3_match(self, Renderer.dice.tk.DIV)) {
			children.push(this._parse3_nextSym(self));
			children.push(this._parse3_exponent(self));
		}
		return new Renderer.dice.parsed.Term(children);
	}

	static _parse3_expression (self) {
		const children = [];
		if (this._parse3_match(self, Renderer.dice.tk.ADD) || this._parse3_match(self, Renderer.dice.tk.SUB)) children.push(this._parse3_nextSym(self));
		children.push(this._parse3_term(self));
		while (this._parse3_match(self, Renderer.dice.tk.ADD) || this._parse3_match(self, Renderer.dice.tk.SUB)) {
			children.push(this._parse3_nextSym(self));
			children.push(this._parse3_term(self));
		}
		return new Renderer.dice.parsed.Expression(children);
	}
	// endregion

	// region Utilities
	static DiceModMeta = class {
		constructor () {
			this.isDiceModifierGroup = true;
			this.isSuccessMode = false;
			this.mods = [];
		}
	};
	// endregion
};

Renderer.dice.tk = class {
	static Token = class {
		/**
		 * @param type
		 * @param value
		 * @param asString
		 * @param [opts] Options object.
		 * @param [opts.isDiceModifier] If the token is a dice modifier, e.g. "dl"
		 * @param [opts.diceModifierImplicit] If the dice modifier has an implicit value (e.g. "kh" is shorthand for "kh1")
		 * @param [opts.isSuccessMode] If the token is a "success"-based dice modifier, e.g. "cs="
		 */
		constructor (type, value, asString, opts) {
			opts = opts || {};
			this.type = type;
			this.value = value;
			this._asString = asString;
			if (opts.isDiceModifier) this.isDiceModifier = true;
			if (opts.diceModifierImplicit) this.diceModifierImplicit = true;
			if (opts.isSuccessMode) this.isSuccessMode = true;
		}

		eq (other) { return other && other.type === this.type; }

		toString () {
			if (this._asString) return this._asString;
			return this.toDebugString();
		}

		toDebugString () { return `${this.type}${this.value ? ` :: ${this.value}` : ""}`; }
	};

	static _new (type, asString, opts) { return new Renderer.dice.tk.Token(type, null, asString, opts); }

	static TYP_NUMBER = "NUMBER";

	static TYP_DICE = "DICE";

	static TYP_SYMBOL = "SYMBOL";

	static NUMBER (val) { return new Renderer.dice.tk.Token(Renderer.dice.tk.TYP_NUMBER, val); }
};
Renderer.dice.tk.PAREN_OPEN = Renderer.dice.tk._new("PAREN_OPEN", "(");
Renderer.dice.tk.PAREN_CLOSE = Renderer.dice.tk._new("PAREN_CLOSE", ")");
Renderer.dice.tk.BRACE_OPEN = Renderer.dice.tk._new("BRACE_OPEN", "{");
Renderer.dice.tk.BRACE_CLOSE = Renderer.dice.tk._new("BRACE_CLOSE", "}");
Renderer.dice.tk.COMMA = Renderer.dice.tk._new("COMMA", ",");
Renderer.dice.tk.ADD = Renderer.dice.tk._new("ADD", "+");
Renderer.dice.tk.SUB = Renderer.dice.tk._new("SUB", "-");
Renderer.dice.tk.MULT = Renderer.dice.tk._new("MULT", "*");
Renderer.dice.tk.DIV = Renderer.dice.tk._new("DIV", "/");
Renderer.dice.tk.POW = Renderer.dice.tk._new("POW", "^");
Renderer.dice.tk.PB = Renderer.dice.tk._new("PB", "pb");
