class UtilDocument {
	static getDocumentSourceReadOnly (document) {
		return document._source;
	}

	static getDocumentSourceMutableCopy (document) {
		return document.toJSON();
	}
}

class UtilDocumentSheet {
	static hasSheet (doc) {
		if (!doc._sheet?.element) return false;
		// eslint-disable-next-line vet-jquery/jquery
		if (doc._sheet.element instanceof $) return !!doc._sheet.element.length;
		return !!doc._sheet.element;
	}
}

class UtilDocumentEffects {
	static getDocumentEffectsList ({doc}) {
		if (!doc) return null;
		if (doc.allApplicableEffects) return [...doc.allApplicableEffects()];
		if (!doc.effects) return null;
		return [...doc.effects];
	}
}

class UtilDocumentFlags {
	/**
	 * @param doc
	 * @param {?Array<string>} [propsRequired] An optional list of required props; if any are not present, `null` will be returned.
	 */
	static getPlutoniumFlags (doc, {propsRequired = null} = {}) {
		const flags = doc?.flags?.[SharedConsts.MODULE_ID];
		if (!flags || !propsRequired) return flags;

		if (!propsRequired.every(prop => flags[prop] != null)) return null;
		return flags;
	}
}

