	static _template_getMinimumRole ({name, help, isGmOnly = false, dfault, isReloadRequired = false}) {
		const out = MiscUtil.copyFast(ConfigConsts._TEMPALTE_MINIMUM_ROLE);
		out.values = Util.Fvtt.getMinimumRolesEnum({isGmOnly});
		out.name = name;
		out.help = help;
		if (dfault) out.default = dfault;
		else out.default = out.values[0].value;
		if (isReloadRequired) out.isReloadRequired = isReloadRequired;
		return out;
	}

