	static _template_class_getHpIncreaseModeCustomRollFormula ({name, nameHpIncreaseMode}) {
		return {
			name,
			help: `A custom roll formula to be used when gaining HP on level up. Used if either the "${nameHpIncreaseMode}" option is set to "${ConfigConsts.C_IMPORT_CLASS_HP_INCREASE_MODE___NAMES[ConfigConsts.C_IMPORT_CLASS_HP_INCREASE_MODE__ROLL_CUSTOM]}", or if a player chooses "${ConfigConsts.C_IMPORT_CLASS_HP_INCREASE_MODE___NAMES[ConfigConsts.C_IMPORT_CLASS_HP_INCREASE_MODE__ROLL_CUSTOM]}" when prompted to select their Hit Points Increase Mode. Use "@hd.faces" for the type of dice (i.e., the "8" in "1d8"), and "@hd.number" for "number of dice" (i.e., the "1" in "1d8"). Note that backticks (\`) around an expression will also be replaced so "\`@hd.number\`d\`@hd.faces\`" will produce e.g. "1d8", should you need to avoid using brackets.`,
			placeholder: "(@hd.number)d(@hd.faces)",
			type: "string",
			additionalStyleClasses: ["code"],
			default: null,
			isNullable: true,
		};
	}

