	render (
		{
			configDraft,
			groupKey,
			k,
			backend,
			isDisabled,
			titleDisabled,
			current,
		},
	) {
		const cur = current instanceof Array ? MiscUtil.copyFast(current) : [];

		const comp = BaseComponent.fromObject({values: cur}, "values");

		const {wrp, fnToggleDisabled} = ComponentUiUtil.getPickString2(
			comp,
			"values",
			{
				fnGetElePill: val => {
					const pack = game.packs.get(val);

					const ele = pack
						? veT`<span class="ve-clickable ve-flex-v-center"><i class="ve-muted fas fa-fw fa-passport"></i><i class="ve-muted fa-fw ${CONFIG[this.documentType]?.sidebarIcon} ve-mr-1"></i> ${pack.metadata.label}</span>`
						: veT`<span class="ve-clickable ve-code">${val}</span>`;

					return ele
						.vee.onn("click", () => {
							const pack = game.packs.get(val);
							if (!pack) return ui.notifications.warn(`Could not find compendium with ID "${val}"!`);

							pack.render(true);
						});
				},
				fnGetTitlePill: val => {
					const pack = game.packs.get(val);
					if (!pack) return val;
					return `${pack.metadata.label} ("${val}")`;
				},
				fnOnDrop: (
					{
						evt,
						addValue,
					},
				) => {
					const data = EventUtil.getDropJson(evt);

					if (data?.type !== "Compendium") return;

					evt.stopPropagation();

					const pack = game.packs.get(data.collection);
					if (pack.metadata.type !== this.documentType) {
						return ui.notifications.warn(`Compendium "${pack.metadata.label}" did not have expected type "${this.documentType}"!`);
					}

					addValue(data.collection);
				},
				asMeta: true,
				placeholderInput: "Compendium ID",
				additionalStyleClassesInput: "code",
			},
		);
		let isIgnoreHook = false;
		comp._addHookBase("values", () => {
			if (isIgnoreHook) return;
			configDraft.set(groupKey, k, comp._state.values);
			fnUpdateIsDefault();
		});

		const fnDisable = () => {
			fnToggleDisabled(true);
		};

		const fnReset = () => {
			comp._state.values = [...this._getValDefault({backend, groupKey, k})];

			if (game.user.isGM) return;

			configDraft.delete(groupKey, k);
			fnUpdateIsDefault();
		};

		const {btnResetRow, fnUpdateIsDefault} = this._getBtnResetRow({configDraft, groupKey, k, isDisabled, fnReset});
		fnUpdateIsDefault();

		const fnHandleUpdate = () => {
			try {
				isIgnoreHook = true;
				comp._state.values = [...configDraft.get(groupKey, k) || []];
				fnUpdateIsDefault();
			} finally {
				isIgnoreHook = false;
			}
		};

		return new this.constructor._RenderMeta({
			ele: wrp,
			btnResetRow,
			fnDisable,
			fnReset,
			fnHandleUpdate,
			isLabel: false,
		});
	}

	_isValidValue (value) {
		return value instanceof Array
			&& value.every(it => typeof it === "string");
	}
