const BASE_TITLE = "Art Browser";

class ArtBrowserBackendClient {
	static async pDownloadPack (json) {
		await fetch(
			Config.backendEndpoint,
			{
				method: "post",
				headers: {
					"Content-Type": "application/json",
				},
				body: JSON.stringify({
					type: "artBrowserDownloadPack",
					json,
					directoryPath: Config.get("artBrowser", "artDirectoryPath"),
				}),
			},
		);
	}

	static async doCancelPackDownload () {
		await fetch(
			Config.backendEndpoint,
			{
				method: "post",
				headers: {
					"Content-Type": "application/json",
				},
				body: JSON.stringify({
					type: "artBrowserCancelDownloadPack",
				}),
			},
		);
	}

	static async pCopyImageToLocalViaBackend (url) {
		const fetched = await fetch(
			Config.backendEndpoint,
			{
				method: "post",
				headers: {
					"Content-Type": "application/json",
				},
				body: JSON.stringify({
					type: "artBrowserCopyToLocal",
					url: url,
					directoryPath: Config.get("artBrowser", "artDirectoryPath"),
				}),
			},
		);
		const json = await fetched.json();
		return json.path;
	}
}

