		out.source = ele.getAttribute("data-plut-hover-source");
		out.hash = ele.getAttribute("data-plut-hover-hash");
		out.preloadId = ele.getAttribute("data-plut-hover-preload-id");
		out.hashPreEncoded = !!ele.getAttribute("data-plut-hover-hash-pre-encoded");
		out.pageHover = ele.getAttribute("data-plut-hover-page-hover") || out.page;
		out.sourceHover = ele.getAttribute("data-plut-hover-source-hover") || out.source;
		out.hashHover = ele.getAttribute("data-plut-hover-hash-hover");
		out.hashPreEncodedHover = !!ele.getAttribute("data-plut-hover-hash-pre-encoded-hover");
		out.subhashesHover = ele.getAttribute("data-plut-hover-subhashes-hover");
		out.isFauxPage = ele.getAttribute("data-plut-hover-is-faux-page");
		out.isAllowRedirect = ele.getAttribute("data-plut-hover-is-allow-redirect") === "true";

