class UtilDocumentActor {
	static getSheetPb (pb) {
		// As of 4.x, `null` CR is allowed, so PB can be any value
		return pb;
	}

	/* -------------------------------------------- */

	static getConsumedSheetItem ({name, actor}) {
		const lookupNames = [
			name.toLowerCase().trim(),
			name.toLowerCase().trim().toPlural(),
		];

		return (actor?.items?.contents || [])
			.find(actorItem => {
				if (actorItem.type !== "feat") return false;
				const nameClean = actorItem.name.toLowerCase().trim();
				if (lookupNames.includes(nameClean)) return true;

				// TODO(Future) hack; remove/clean up
				if (!Config.get("importClassSubclassFeature", "isLevelPrefixNames")) return false;
				const nameCleanAlt = nameClean.replace(/^Level \d+:\s*/i, "");
				if (nameCleanAlt === nameClean) return false;

				return lookupNames.includes(nameCleanAlt);
			});
	}

	/* -------------------------------------------- */

	// Support either JSON, or real `actor` documents
	// See: https://github.com/foundryvtt/dnd5e/issues/6685
	static getActorType ({actor}) {
		if (!actor) return null;

		if (actor?.system?.isCharacter) return "character";
		if (actor?.system?.isNPC) return "npc";
		if (actor?.system?.isVehicle) return "vehicle";

		// Fall back on underlying type
		return actor.type;
	}
}

class _ConsumptionInfo {
	isConsumes = false;
	isFound = false;
	consumptionTarget = null;

	/**
	 * @param isConsumes
	 * @param isFound
	 * @param {?object} consumptionTarget
	 */
	constructor (
		{
			isConsumes = false,
			isFound = false,
			consumptionTarget = null,
		} = {},
	) {
		this.isConsumes = isConsumes;
		this.isFound = isFound;
		this.consumptionTarget = consumptionTarget;
	}

	/* -------------------------------------------- */

	/**
	 * @param {object} itemDataExpanded
	 */
	mutRepairItemActivityData (itemDataExpanded) {
		if (!this.isConsumes || !Object.keys(this.consumptionTarget || {}).length) return;

		Object.values(itemDataExpanded.system.activities || {})
			.forEach(activity => {
				MiscUtil.set(
					activity,
					"consumption",
					"targets",
					[
						{
							...this.consumptionTarget,
						},
					],
				);
			});
	}

	/* -------------------------------------------- */

	_getActivityConsumptionTargets () {
		if (!this.isConsumes) return null;

		if (this.isFound) {
			return [MiscUtil.copyFast(this.consumptionTarget)];
		}

		// Return a stub consumption target, and expect that it will be repaired later
		return [{}];
	}

	/**
	 * Get activity data for an item which consumes another item.
	 * This serves two purposes:
	 *   - if we have the item ready, we can return a valid consumption target
	 *   - if we do not yet have the item ready, we instead return a stub consumption target,
	 *     to be repaired later.
	 */
	getActivityData () {
		if (!this.isConsumes) return null;

		return {
			allActivities: {
				consumptionTargets: this._getActivityConsumptionTargets(),
			},
		};
	}

	/* ----- */

	getMutMergeActivitiesData (activities) {
		if (!this.isConsumes) return activities;

		// If there are no activities in the incoming data, make a "utility" activity to hang
		//   our consumption targets on
		if (!Object.keys(activities).length) {
			const id = UtilDocumentItem.getActivityId(0);

			const state = new EntryParseStateActivityModelUtility({
				stateInitial: {
					id,
					consumptionTargets: this._getActivityConsumptionTargets(),
				},
			});

			activities[id] = state.toActivityJSON();

			return activities;
		}

		Object.values(activities)
			.forEach(activity => {
				MiscUtil.set(
					activity,
					"consumption",
					"targets",
					this._getActivityConsumptionTargets(),
				);
			});

		return activities;
	}
}

class ImportItemConsumptionManager {
	static _getConsumedSheetItem ({consumes, actor}) {
		const lookupNames = [
			consumes.name.toLowerCase().trim(),
			consumes.name.toLowerCase().trim().toPlural(),
		];

		return (actor?.items?.contents || [])
			.find(it => {
				if (it.type !== "feat") return false;
				const nameClean = it.name.toLowerCase().trim();
				if (lookupNames.includes(nameClean)) return true;

				// TODO(Future) hack; remove/clean up
				if (!Config.get("importClassSubclassFeature", "isLevelPrefixNames")) return false;
				const nameCleanAlt = nameClean.replace(/^Level \d+:\s*/i, "");
				if (nameCleanAlt === nameClean) return false;

				return lookupNames.includes(nameCleanAlt);
			});
	}

	static getConsumptionInfo ({ent, actor}) {
		if (!ent?.consumes?.name) return new _ConsumptionInfo();

		const sheetItem = UtilDocumentActor.getConsumedSheetItem({name: ent.consumes.name, actor});
		if (!sheetItem) {
			return new _ConsumptionInfo({
				isConsumes: true,
				isFound: false,
			});
		}

		return new _ConsumptionInfo({
			isConsumes: true,
			isFound: true,
			consumptionTarget: {
				type: "itemUses",
				value: `${ent.consumes.amount ?? 1}`,
				target: sheetItem.id,
			},
		});
	}

	static getConsumesMetaEmpty () { return new _ConsumptionInfo(); }

	static getConsumesMetaFrom (
		{
			type,
			value,
			target,
			scaling,
		},
	) {
		return new _ConsumptionInfo({
			isConsumes: true,
			isFound: true,
			consumptionTarget: {
				type,
				value,
				target,
				scaling,
			},
		});
	}
}

