class SideDataMatcherSystem extends SideDataMatcherBase {
	_propPropFromEntity = "system";
	_propFromEntity = "foundrySystem";
	_propFromSideLoaded = "system";

	static _pGetStarSideLoaded_mutInitial ({outExpanded}) {
		if (!outExpanded.activities?.length) return;

		// Expand activities from our "array" version into an "object of id -> activity"
		outExpanded.activities = Object.fromEntries(
			outExpanded.activities
				.map((activity, i) => {
					const id = activity._id || activity.id || UtilDocumentItem.getActivityId(i);
					activity.id = activity._id = id;
					return [
						id,
						activity,
					];
				}),
		);
	}
}

class SideDataMatcherActivities extends SideDataMatcherBase {
	_propPropFromEntity = "activities";
	_propFromEntity = "foundryActivities";
	_propFromSideLoaded = "activities";

	_getHydratedActivity ({activity, ix}) {
		const idObj = this._getHydrated_getIdObj({dehydrated: activity, fallbackId: UtilDocumentItem.getActivityId(ix)});
		const cpyActivity = SideDataActivitiesInlineRefMutator.getHydrated({
			activity: MiscUtil.copyFast(activity),
		});

		this._getHydratedActivity_mutDescription_pre({activity: cpyActivity});

		const cpyOut = foundry.utils.expandObject({
			...cpyActivity,
			...idObj,
		});

		this._getHydratedActivity_mutCastSpell({activity: cpyOut});
		this._getHydratedActivity_mutProfiles({activity: cpyOut});
		this._getHydratedActivity_mutForwardActivity({activity: cpyOut});

		if (cpyOut.effects?.length) {
			cpyOut.effects
				.forEach(effectLink => this._getHydratedActivity_mutEffectLink({effectLink}));
		}

		this._getHydratedActivity_mutDescription({activity: cpyOut});

		return cpyOut;
	}

	/* ----- */

	_getHydratedActivity_mutCastSpell ({activity}) {
		if (activity.type !== "cast") return;

		this._getHydrated_mutGenericUuid(activity.spell);

		// As of 2025-04-13, the custom `img` handling in `CastActivityData.prepareFinalData`
		//   breaks the use of a default "cast"-type activity image. Specify it explicitly
		//   instead.
		activity.img ||= CONFIG.DND5E.activityTypes.cast.documentClass.metadata.img;
	}

	_getHydratedActivity_mutProfiles ({activity}) {
		if (!["summon", "transform"].includes(activity.type)) return;

		if (!activity.profiles?.length) return;

		activity.profiles
			.forEach(profile => this._getHydrated_mutGenericUuid(profile));
	}

	_getHydratedActivity_mutForwardActivity ({activity}) {
		if (activity.type !== "forward") return;

		this._getHydrated_mutIdObjNoFallback({dehydrated: activity.activity});
	}

	/* ----- */

	_getHydratedActivity_mutEffectLink ({effectLink}) {
		this._getHydratedActivity_mutEffectLink_id({effectLink});
		this._getHydratedActivity_mutEffectLink_riders({effectLink});
	}

	_getHydratedActivity_mutEffectLink_id ({effectLink}) {
		this._getHydrated_mutIdObjNoFallback({dehydrated: effectLink});
	}

	_getHydratedActivity_mutEffectLink_riders ({effectLink}) {
		["activity", "effect"]
			.forEach(prop => {
				if (!effectLink?.riders?.[prop]?.length) return;

				effectLink.riders[prop] = effectLink.riders[prop]
					.map(refLink => this._getHydrated_getIdFromRef({refLink, prop}));
			});

		["item"]
			.forEach(prop => {
				if (!effectLink.riders?.[prop]?.length) return;

				effectLink.riders[prop] = effectLink.riders[prop]
					.map(uuid => {
						const link = {uuid};
						this._getHydrated_mutGenericUuid(link);
						return link.uuid;
					});
			});
	}

	/* ----- */

	_getHydratedActivity_mutDescription_pre_generic ({activity, prop, propEntries}) {
		if (activity[prop] == null) return;
		if (typeof activity[prop] !== "string") throw new Error(`Activity "${prop}" must be a string!`);

		if (activity[propEntries]?.length) throw new Error(`Activity "${prop}" and "${propEntries}" are mutually exclusive!`);

		activity[propEntries] = [activity[prop]];
		delete activity[prop];
	}

	_getHydratedActivity_mutDescription_pre ({activity}) {
		// E.g. already-Foundry-structured activity via "Unarmed Strike" generation
		if (activity.description && typeof activity.description === "object") return;

		this._getHydratedActivity_mutDescription_pre_generic({activity, prop: "description", propEntries: "descriptionEntries"});
		this._getHydratedActivity_mutDescription_pre_generic({activity, prop: "descriptionChat", propEntries: "descriptionEntriesChat"});
	}

	/* ----- */

	_getHydratedActivity_mutDescription_generic ({activity, prop, propEntries}) {
		if (!activity[propEntries]?.length) return;

		if (activity.description?.[prop]?.length) throw new Error(`Activity "description.${prop}" and "${propEntries}" are mutually exclusive!`);

		(activity.description ||= {})[prop] = Renderer.get().render({type: "entries", entries: activity[propEntries]}, 2);
		delete activity[propEntries];
	}

	_getHydratedActivity_mutDescription ({activity}) {
		this._getHydratedActivity_mutDescription_generic({activity, prop: "value", propEntries: "descriptionEntries"});
		this._getHydratedActivity_mutDescription_generic({activity, prop: "chatFlavor", propEntries: "descriptionEntriesChat"});
	}

	/* ----- */

	async pGet (opts) {
		const activitiesArray = await super.pGet(opts);

		// Nothing specified -> ignore, and e.g. auto-generate
		if (!activitiesArray) return null;

		// Empty array specified -> empty object, to signal that we don't want e.g. auto-generated
		if (!activitiesArray.length) return {};

		const out = Object.fromEntries(
			activitiesArray
				.map((activity, ix) => {
					const activityHydrated = this._getHydratedActivity({activity, ix});
					return [
						activityHydrated.id,
						activityHydrated,
					];
				}),
		);

		new ActivitiesConsumptionTargetMutatorResourceConsumption()
			.mutActivitiesTarget({
				id: this._idObj.id,
				activities: out,
				actorMultiImportHelper: this._actorMultiImportHelper,
			});

		new ActivitiesConsumptionTargetMutatorEntityReference()
			.mutActivitiesTarget({
				id: this._idObj.id,
				activities: out,
				actorMultiImportHelper: this._actorMultiImportHelper,
			});

		return out;
	}
}

