class SideDataMatcherEffects extends SideDataMatcherBase {
	_propPropFromEntity = "effects";
	_propFromEntity = "foundryEffects";
	_propFromSideLoaded = "effects";

	_getHydratedEffect ({effect}) {
		let out = null;

		// Retain the `foundryId` key, as we expand it later in `getExpandedEffects`.
		if (effect.foundryId) {
			out ??= MiscUtil.copyFast(effect);
			out.foundryId = Dnd5eUtil.getPaddedIdCustom(out.foundryId);
		}

		if (effect.system?.rider?.activities?.length) {
			out ??= MiscUtil.copyFast(effect);
			out.system.rider.activities = out.system.rider.activities
				.map(refLink => this._getHydrated_getIdFromRef({refLink, prop: "activities"}));
		}

		if (effect.system?.rider?.effects?.length) {
			out ??= MiscUtil.copyFast(effect);
			out.system.rider.effects = out.system.rider.effects
				.map(refLink => typeof refLink === "string" ? refLink : `.ActiveEffect.${this._getHydrated_getIdFromRef({refLink, prop: "effects"})}`);
		}

		if (effect.system?.rider?.items?.length) {
			out ??= MiscUtil.copyFast(effect);
			out.system.rider.items = out.system.rider.items
				.map(uuid => {
					const link = {uuid};
					this._getHydrated_mutGenericUuid(link);
					return link.uuid;
				});
		}

		return out ?? effect;
	}

	async pGet (opts) {
		const out = await super.pGet(opts);

		if (!out?.length) return out;

		return out
			.filter(effect => {
				if (!effect) return false;
				if (!effect.requires) return true;

				return Object.keys(effect.requires)
					.every(k => UtilCompat.isModuleActive(k));
			})
			.map(effect => this._getHydratedEffect({effect}))
		;
	}
}

