class DdbImporterIconFileAdapterBase {
	static _getCleanLookupString (str) {
		return str
			.trim()
			.toLowerCase();
	}

	static _getValidString (strOr) {
		if (!strOr) return null;
		if (typeof strOr === "string") return strOr;
		return null;
	}

	_CACHE = {};
	_pAddingToCache = null;

	constructor ({filename}) {
		this._filename = filename;
	}

	async pInit () {
		return (this._pAddingToCache ||= this._pLoadCache());
	}

	async _pLoadCache () {
		const json = await DataUtil.loadRawJSON(VetoolsLinks.getModuleDataUrl(`ddb-importer/${this._filename}`));
		json.forEach(row => this._addRowToCache({row}));
	}

	getPathFromCache ({ent, fnGetAliasedEntities}) {
		const out = this._getPathFromCache({ent});
		if (out) return out;

		const entsAlias = fnGetAliasedEntities(ent);
		for (const entAlias of entsAlias) {
			const out = this._getPathFromCache({ent: entAlias});
			if (out) return out;
		}

		return null;
	}

	/**
	 * @abstract
	 * @return void
	 */
	_addRowToCache ({row}) { throw new Error("Unimplemented!"); }

	/**
	 * @abstract
	 * @return {string}
	 */
	_getPathFromCache ({ent}) { throw new Error("Unimplemented!"); }
}

class DdbImporterIconFileAdapter extends DdbImporterIconFileAdapterBase {
	_addRowToCache ({row}) {
		this._CACHE[row.name] = row.path;
	}

	_getPathFromCache ({ent}) {
		if (!ent.name) return null;

		return this._CACHE[this.constructor._getCleanLookupString(ent.name)];
	}
}

