class CompendiumCacheKeyProviderCreatureFeature extends CompendiumCacheKeyProviderGeneric {
	getLookupMetas (ent) {
		return [
			...super.getLookupMetas(ent),
			...UtilEntityCreatureFeature.getEntityAliases(ent, {isStrict: this._isStrict}).map(({name}) => ({name})),
		];
	}
}

class UtilEntityCreatureFeature extends UtilEntityBase {
	static _PropNamespacer = UtilEntityPropNamespacerCreatureFeature;

	/* -------------------------------------------- */

	static getCompendiumCacheKeyProvider ({isStrict = false} = {}) {
		return new CompendiumCacheKeyProviderCreatureFeature({isStrict});
	}

	/* -------------------------------------------- */

	static getEntityAliases (ent, {isStrict = false} = {}) {
		if (!ent.name) return [];

		const out = [];

		const noBrackets = ent.name
			.replace(/\([^)]+\)/g, "")
			.replace(/\s+/g, " ")
			.trim();
		if (noBrackets !== ent.name) out.push({...ent, name: noBrackets});

		const noTags = ent.name
			.replace(/{@[^}]+}/g, "")
			.replace(/\s+/g, " ")
			.trim();
		if (noTags !== ent.name) out.push({...ent, name: noTags});

		// SRD legendary actions are suffixed
		if (
			[
				"legendary",
				"mythic",
			]
				.map(prop => UtilEntityCreatureFeature.getNamespacedProp(prop))
				.includes(ent.__prop)
		) out.push({...ent, name: `${ent.name} (Legendary)`});
		if (ent._featureExtras?.isAttack) out.push({...ent, name: `${ent.name} Attack`});

		const noAttack = ent.name.replace(/ Attack$/, "");
		if (noAttack !== ent.name) out.push({...ent, name: noAttack});

		return out;
	}

	/* -------------------------------------------- */

	static isActionEyeRay (action) {
		return /^eye (?:ray|psionic)s?/gi.test(action.name)
			&& action.entries.find(it => it.type === "list" && (it.items || []).every(li => li.type === "item"));
	}

	/* -------------------------------------------- */

	// Additional properties generated by faux monster features
	static CHILD_PROPS_FAUX = [
		"legendaryHeader",
		"mythicHeader",

		"resource",

		"traitNote",
		"actionNote",
		"bonusNote",
		"reactionNote",

		"traitHeader",
		"actionHeader",
		"bonusHeader",
		"reactionHeader",
	];
}

class DdbImporterIconFileAdapterClassFeatures extends DdbImporterIconFileAdapterBase {
	_subclassLookup = null;

	constructor () {
		super({filename: "class-features.json"});
	}

	async _pLoadCache () {
		this._subclassLookup = await DataUtil.class.pGetSubclassLookup();
		return super._pLoadCache();
	}

	_addRowToCache ({row}) {
		if (row.subclass) return MiscUtil.set(this._CACHE, row.class, row.subclass, row.name, row.path);
		if (row.class) return MiscUtil.set(this._CACHE, row.class, row.name, row.path);
		return MiscUtil.set(this._CACHE, row.name, row.path);
	}

	_getPathFromCache ({ent}) {
		if (!ent.name) return null;

		if (ent.classSource && ent.className && ent.subclassSource && ent.subclassShortName) {
			const subclassName = MiscUtil.get(this._subclassLookup, ent.classSource, ent.className, ent.subclassSource, ent.subclassShortName, "name");

			if (subclassName) {
				const out = this.constructor._getValidString(
					MiscUtil.get(
						this._CACHE,
						this.constructor._getCleanLookupString(ent.className),
						this.constructor._getCleanLookupString(subclassName),
						this.constructor._getCleanLookupString(ent.name),
					),
				);
				if (out) return out;
			}
		}

		if (ent.className) {
			const out = this.constructor._getValidString(
				MiscUtil.get(
					this._CACHE,
					this.constructor._getCleanLookupString(ent.className),
					this.constructor._getCleanLookupString(ent.name),
				),
			);
			if (out) return out;
		}

		return this.constructor._getValidString(
			MiscUtil.get(
				this._CACHE,
				this.constructor._getCleanLookupString(ent.name),
			),
		);
	}
}

