/** @abstract */
class ThreeDiTokenAdapterBase {
	/**
	 * @abstract
	 * @return {string}
	 */
	static _getFilePath () { throw new Error("Unimplemented!"); }

	static _P_LOAD_THREE_DI_TOKEN_LOOKUP = null;
	static _THREE_DI_TOKEN_LOOKUP = {}; // Keep a sync version to access, as we expect to preload this
	static async _pInitThreeDiTokenLookup () {
		if (!UtilCompat.isThreeDiTokensActive() || !Config.get("integrationThreeDiCanvas", "isSetThreeDiModels")) return;

		await (this._P_LOAD_THREE_DI_TOKEN_LOOKUP ||= (async () => {
			this._THREE_DI_TOKEN_LOOKUP = await DataUtil.loadJSON(this._getFilePath());
		})());
	}

	static async pInit () {
		await this._pInitThreeDiTokenLookup();
	}

	/** @abstract */
	static _getHash (ent) { throw new Error(`Unimplemented!`); }

	static _getPathMeta (path) {
		// region Based on `TokenBrowser.getData`
		const name = path
			.split("/")
			.pop()
			.replaceAll("%20", "_")
			.replaceAll("_", " ")
			.replace(".glb", "")
			.replace(/MZ4250\s*-\s*/, "")
			.replace(/MS4250\s*-\s*/g, "")
		;

		const previewPath = path.replace(/\..*?$/, ".webp");
		// endregion

		return {
			name,
			path,
			previewPath,
		};
	}

	static getPrimaryMeta (ent) {
		const hash = this._getHash(ent);
		const fromData = this._THREE_DI_TOKEN_LOOKUP[hash];
		if (!fromData?.primary) return null;
		return this._getPathMeta(fromData.primary);
	}

	static getSecondaryMetas (ent) {
		const hash = this._getHash(ent);
		const fromData = this._THREE_DI_TOKEN_LOOKUP[hash];
		if (!fromData?.secondary?.length) return [];
		return fromData.secondary.map(path => this._getPathMeta(path));
	}

	static getAllMetas (ent) {
		return [
			this.getPrimaryMeta(ent),
			...this.getSecondaryMetas(ent),
		]
			.filter(Boolean);
	}
}

class ThreeDiTokenAdapterCreature extends ThreeDiTokenAdapterBase {
	static _getFilePath () { return VetoolsLinks.getModuleDataUrl(`bestiary/foundry-integration-3d-tokens.json`); }
	static _getHash (ent) { return UrlUtil.URL_TO_HASH_BUILDER[UrlUtil.PG_BESTIARY](ent); }
}

class DataPrimerActor extends DataPrimerBase {
	static _PROPS;
	static _ThreeDiTokenAdapter;

	static async pGetPrimed ({json, propsCopied}) {
		if (!this._ThreeDiTokenAdapter) return json;
		if (!this._PROPS.some(prop => json[prop]?.length)) return json;

		await this._ThreeDiTokenAdapter.pInit();

		this._PROPS
			.forEach(prop => {
				(json[prop] || [])
					.forEach(ent => ent.hasToken3d = !!this._ThreeDiTokenAdapter.getPrimaryMeta(ent));
			});

		return json;
	}
}

class DataPrimerCreature extends DataPrimerActor {
	static _PROPS = ["monster"];
	static _ThreeDiTokenAdapter = ThreeDiTokenAdapterCreature;
}

