class UtilCompendium {
	static getAvailablePacks ({folderType}) {
		return game.packs.filter(it => !it.locked && it.metadata.type === folderType);
	}

	static async pGetUserCreatePack ({folderType}) {
		const dispPackName = veT`<div class="ve-w-100 ve-italic"></div>`;
		const packLabel = await InputUiUtil.pGetUserString({
			title: `Enter New "${folderType}" Compendium Name`,
			fnIsValid: str => Parser.stringToSlug(str).length,
			elePost: veT`<label class="ve-mb-2 ve-split-v-center ve-muted">
					<div class="ve-mr-2 ve-bold ve-no-wrap">Compendium ID:</div>
					${dispPackName}
				</label>`,
			cbPostRender: ({comp, propValue}) => {
				const hkId = () => dispPackName.vee.txt(comp._state[propValue] ? (Parser.stringToSlug(comp._state[propValue]) || "(Invalid)") : "\u2014");
				comp._addHookBase(propValue, hkId);
				hkId();
			},
		});
		if (!packLabel || !packLabel.trim()) return null;

		return foundry.documents.collections.CompendiumCollection.createCompendium({
			type: "Item",
			label: packLabel,
			name: Parser.stringToSlug(packLabel),
			package: "world",
		});
	}

	static getSelCompendium ({availablePacks = null, folderType = null}) {
		availablePacks = availablePacks || this.getAvailablePacks({folderType});
		return veT`<select class="ve-form-control ve-m-0">
			${availablePacks.map((pack) => `<option value="${pack.collection}">${pack.metadata.label}</option>`).join("")}
		</select>`;
	}

	static getPackByCollection ({collection}) {
		if (collection == null) return null;
		return game.packs.find(it => it.collection === collection);
	}

	/* -------------------------------------------- */

	/**
	 * @param type
	 * @param label
	 * @param name
	 * @param isOptional
	 * @param {?string} optionalPromptHtmlDescription
	 * @param isRender
	 */
	static async pGetCreateBackingCompendium (
		{
			type,
			label,
			name,
			isOptional = false,
			optionalPromptHtmlDescription = null,
			isRender = true,
		},
	) {
		const packKey = `world.${name}`;

		const existingCompendium = game.packs.get(packKey);
		if (existingCompendium) {
			// For player-facing hits, we assume the GM has already configured the compendium
			if (game.user.isGM) {
				await existingCompendium.configure({
					ownership: this._pGetCreateBackingCompendium_getOwnership(),
				});
			}

			return existingCompendium;
		}

		if (
			isOptional
		) {
			const isContinue = await InputUiUtil.pGetUserBoolean({
				title: "Create Backing Compendium?",
				htmlDescription: optionalPromptHtmlDescription,
			});
			if (!isContinue) return null;
		}

		const folderId = await this._pGetCreateBackingCompendium_pGetCreateFolderId({isRender});

		const pack = await foundry.documents.collections.CompendiumCollection.createCompendium({
			type,
			label,
			name,
			package: "world",
		});

		await pack.setFolder(folderId);

		await pack.configure({
			ownership: this._pGetCreateBackingCompendium_getOwnership(),
		});

		return pack;
	}

	static _pGetCreateBackingCompendium_getOwnership () {
		return Object.fromEntries(
			Object.keys(CONST.USER_ROLES)
				.filter(k => k !== "NONE")
				.map(k => [k, "OWNER"]),
		);
	}

	static async _pGetCreateBackingCompendium_pGetCreateFolderId ({isRender}) {
		try {
			return (await this._pGetCreateBackingCompendium_pGetCreateFolderId_({isRender}));
		} catch (e) {
			console.warn(...LGT, `Failed to create backing compendium folder: ${e.message}.`);
			return null;
		}
	}

	static async _pGetCreateBackingCompendium_pGetCreateFolderId_ ({isRender}) {
		return UtilFolders.pCreateFoldersGetId({
			folderType: "Compendium",
			folderNames: [`${SharedConsts.MODULE_TITLE_FAKE}`],
			sorting: "m",
			color: "#9e1612",
			isRender,
		});
	}
}

class UtilAdvancementsBackingCompendium {
	static init () {
		UtilHooks.on(UtilHooks.HK_CONFIG_UPDATE, (diff) => this._pHandleConfigUpdate(diff));
		this._pHandleConfigUpdate({isInit: true}).then(null);
	}

	static async _pHandleConfigUpdate ({isInit = false, current, previous} = {}) {
		if (!game.users.activeGM?.isSelf) return;

		if (!Config.get("import", "isUseAdvancementBackingCompendium")) return;

		if (isInit) return this._pGetCreateBackingCompendium({isInit});

		if (
			MiscUtil.get(current, "import", "isUseAdvancementBackingCompendium") ===
			MiscUtil.get(previous, "import", "isUseAdvancementBackingCompendium")
		) return;

		return this._pGetCreateBackingCompendium({isInit});
	}

	/* -------------------------------------------- */

	static PACK_NAME = `${SharedConsts.MODULE_ID_FAKE}-advancement-backing-item`;

	static async _pGetCreateBackingCompendium ({isInit = false} = {}) {
		return UtilCompendium.pGetCreateBackingCompendium({
			type: "Item",
			label: "Advancement-Backing Items",
			name: this.PACK_NAME,
			isRender: !isInit,
		});
	}

	/* -------------------------------------------- */

	static async pCreateAdvancementBackingItem (
		{
			item,
		},
	) {
		// eslint-disable-next-line new-cap
		const itemJson = new Item.implementation(item.toJSON());

		// Prevent any antics
		MiscUtil.set(itemJson, "flags", SharedConsts.MODULE_ID, "isDirectImport", true);

		const pack = await this._pGetCreateBackingCompendium();

		return pack.importDocument(itemJson);
	}
}

class UtilAdvancementsData {
	static getAdvancementsAsArray (advancements) {
		if (!advancements) return [];

		// Handle legacy case/Plutonium-internal arrays
		if (Array.isArray(advancements)) return advancements;

		// Handle Foundry document case
		if (typeof advancements.values === "function") return [...advancements.values()];

		// Handle plain object case
		return Object.values(advancements);
	}

	static getDocumentAdvancementsAsArray (document) {
		const advancements = UtilDocument.getDocumentSourceReadOnly(document).system?.advancement;
		if (!advancements) return [];
		return this.getAdvancementsAsArray(MiscUtil.copyFast(advancements));
	}
}

class SystemDnd5eAdvancementUtil {
	static getVersionCompatibleAdvancement (advancement) {
		if (UtilVersions.getSystemVersion().isVersionSixPlus) return advancement;

		const out = MiscUtil.copyFast(advancement);
		const name = out.name ?? out.title;
		const img = out.img ?? out.icon;

		if (out.type === "ScaleValue" && out.configuration?.type === "usage") {
			out.configuration.type = "number";
			Object.values(out.configuration.scale || {})
				.forEach(scaleValue => delete scaleValue.period);
		}

		if (name != null) out.title = name;
		if (img != null) out.icon = img;
		delete out.name;
		delete out.img;

		return out;
	}
}

