	static getWalkDamageOnSaveMode (toWalk) {
		let onSave;
		UtilWalker.WALKER_READONLY_GENERIC_BOR
			.walk(
				toWalk,
				{
					string: (str) => {
						const {onSave: _onSave, isFound} = UtilActivityBuilder.getDamageOnSaveMode(str);
						onSave = _onSave;
						if (isFound) return true;
					},
				},
			);
		return onSave;
	}

