class DataSourceAdventureBookOfficial extends DataSourceSpecial {
	constructor ({contents, propContents, propTuple}) {
		super();
		this._propContents = propContents;
		this._propTuple = propTuple;
		this._contents = contents;
	}

	get _cacheKey () { return `5etools-${this._propContents}-${this._contents.id}`; }

	async _pGet () {
		const propData = `${this._propContents}Data`;
		const json = await DataUtil.loadJSON(this._contents._url);
		return {
			[this._propTuple]: [
				{
					source: this._contents.source,
					_contentMetadata: this._contents,
					...json[propData].find(corpusData => corpusData.id === this._contents.id),
					__prop: this._propTuple,
				},
			],
		};
	}
}

