class DataPostLoaderAdventureBook extends DataPostLoaderBase {
	static _propContents;
	static _propData;
	static _propTuple;

	static async pMutPostLoad (json) {
		if ([this._propContents, this._propData].some(prop => !json[prop]?.length)) return;

		json[this._propTuple] = json[this._propContents]
			.map(contents => {
				const data = json[this._propData].find(data => data.id === contents.id);
				if (!data) return null;
				return {
					_contentMetadata: contents,
					...data,
					__prop: this._propTuple,
				};
			})
			.filter(Boolean);
	}
}

