class UtilEntitySpell extends UtilEntityBase {
	static getListDisplayLevel (it) {
		return `${Parser.spLevelToFull(it.level)}${it.meta && it.meta.ritual ? " (rit.)" : ""}${it.meta && it.meta.technomagic ? " (tec.)" : ""}`;
	}

	static getInnateScalingLevelDelta ({entry, castAtLevel, method}) {
		const fromConfig = Config.get("importSpell", "debugInnateScalingLevelDelta");
		if (fromConfig) return fromConfig;

		if (
			castAtLevel != null
			&& castAtLevel > entry.level
			&& method === "innate"
		) return castAtLevel - entry.level;
	}

	static getSpellUidParts (text) {
		const [uidPart, castAtLevelPart] = (text || "").split("#").map(it => it.trim()).filter(Boolean);
		return {
			uid: uidPart,
			castAtLevel: castAtLevelPart && !isNaN(castAtLevelPart) ? Number(castAtLevelPart) : null,
		};
	}
}

