	static _getItemCapacity (item, opts) {
		if (!item.containerCapacity) return {};

		const out = {};

		if (item.containerCapacity.item?.length) {
			out.count = item.containerCapacity.item
				.map(itemToCount => Object.values(itemToCount).sum())
				.sum();
		}

		if (item.containerCapacity.weight) {
			out.weight = {
				value: Config.getMetricNumberWeight({
					configGroup: this._configGroup,
					originalUnit: Parser.UNT_LBS,
					originalValue: item.containerCapacity.weight.sum(),
				}),
				units: Config.getMetricUnitWeight({
					configGroup: this._configGroup,
					originalUnit: Parser.UNT_LBS,
				}),
			};
		}

		if (item.containerCapacity.volume) {
			out.volume = {
				value: Config.getMetricNumberVolume({
					configGroup: this._configGroup,
					originalUnit: Parser.UNT_CUBIC_FEET,
					originalValue: item.containerCapacity.volume.sum(),
				}),
				units: Config.getMetricUnitVolume({
					configGroup: this._configGroup,
					originalUnit: Parser.UNT_CUBIC_FEET,
				}),
			};
		}

		return out;
	}

