class DataPostLoaderCreatureFeature extends DataPostLoaderBase {
	static async pMutPostLoad (json) {
		if (!json.monster?.length) return;

		for (const mon of json.monster) {
			Renderer.monster.initParsed(mon);

			const legendaryMeta = DataUtil.monster.getLegendaryGroup(mon);

			Renderer.monster.CHILD_PROPS_EXTENDED
				.forEach(prop => {
					// TODO(Future) support spellcasting?
					if (prop === "spellcasting") return;

					const outProp = UtilEntityCreatureFeature.getNamespacedProp(prop);

					(mon[prop] || legendaryMeta?.[prop] || [])
						.filter(ent => ent.name && ent.entries)
						.forEach(ent => {
							(json[outProp] ||= []).push(
								DataConverterCreatureFeature.getFauxFeature(
									mon,
									ent,
									prop,
								),
							);
						});
				});
		}
	}
}

