const PROPS = ["recipe"];

class DataPostLoaderRecipeOfficial {
	static async pMutPostLoad (json) {
		if (!PROPS.some(prop => json[prop]?.length)) return;

		Object.assign(json, await DataUtil.recipe.loadJSON());
	}
}

/** Hack around recipes having a 5etools post-load step to bake in fluff */
const getFromStored = ({json, dataStored}) => {
	const sources = new Set();

	PROPS.forEach(prop => (json[prop] || []).filter(it => it.source).forEach(it => sources.add(it.source)));

	return PROPS.mergeMap(prop => ({[prop]: (dataStored[prop] || []).filter(it => !it.source || sources.has(it.source))}));
};

const pGetFromStorage = async ({json}) => {
	const {isPrerelease, isBrew} = UtilDataSource.getSourceType(json, {isErrorOnMultiple: true});
	if (isPrerelease) getFromStored({json, dataStored: await DataUtil.recipe.loadPrerelease()});
	if (isBrew) getFromStored({json, dataStored: await DataUtil.recipe.loadBrew()});
	throw new Error("Unimplemented!");
};

class DataPostLoaderRecipePrereleaseBrew extends DataPostLoaderBase {
	static async pMutPostLoad (json) {
		if (!PROPS.some(prop => json[prop]?.length)) return;

		Object.assign(json, await pGetFromStorage({json}));
	}
}

class DataPostLoaderRecipePrerelease extends DataPostLoaderBase {
	static async pMutPostLoad (json) {
		if (!PROPS.some(prop => json[prop]?.length)) return;

		const dataStored = await DataUtil.recipe.loadPrerelease();
		Object.assign(json, getFromStored({json, dataStored}));
	}
}

