class DataSourceComposite extends DataSourceBase {
	constructor (
		{
			cacheKey,
			ClssesDataSource,
			...rest
		},
	) {
		super({...rest});

		this._ClssesDataSource = ClssesDataSource;

		if (!cacheKey) throw new Error(`No cache key specified!`);
		this._cacheKey = cacheKey;
	}

	get identifier () { return this._cacheKey; }

	async pGetOutputs ({uploadedFileMetas, customUrls}) {
		const metasSub = await Promise.all(
			this._ClssesDataSource
				.map(Cls => new Cls())
				.map(dataSource => dataSource.pGetOutputs({uploadedFileMetas, customUrls})),
		);
		return new DataSourceOutputs({
			cacheKeys: metasSub
				.flatMap(meta => meta.cacheKeys),
			contents: metasSub
				.flatMap(meta => meta.contents),
		});
	}

	async _pGetBrewUtilAutodetected () { throw new Error("Unimplemented!"); }
}

class DataPostLoaderComposite extends DataPostLoaderBase {
	static _DataPostLoaders;

	static async pMutPostLoad (json) {
		for (const postLoader of this._DataPostLoaders) {
			await postLoader.pMutPostLoad(json);
		}
	}
}

