				if (otherStates) otherStates.forEach(otherState => maxExisting = Math.max(maxExisting, otherState[v] || 0, (parentGroup ? otherState[parentGroup] : 0) || 0));

				const helpText = maxExisting === 0 ? "" : `${prop === "itemMasteries" ? "Mastery" : PROF_TO_TEXT[maxExisting]} from Another Source`;

				ptsExisting[prop][v]
					.vee.tooltip(helpText)
					.vee.toggleClass("ve-ml-1", !!maxExisting)
					.vee.html(maxExisting ? `(<i class="fas fa-fw ${PROF_TO_ICON_CLASS[maxExisting]}"></i>)` : "");
