class Charactermancer_ItemMasteries_Util {
	static _WEAPON_PROF_GROUP_TO_FILTER_EXPRESSION = {
		"simple": "type=simple weapon",
		"martial": "type=martial weapon",
		"firearms": "type=firearm",
		"improvised": null,
	};

	/* -------------------------------------------- */

	static _P_INIT = null;
	static _MODAL_FILTER_ITEMS = null;

	static async pInit () {
		return this._P_INIT ||= (async () => {
			const {Charactermancer_OtherProficiencySelect} = await Promise.resolve().then(function () { return CharactermancerSelectProficiencyOther; });
			this._MODAL_FILTER_ITEMS = await Charactermancer_OtherProficiencySelect.pGetModalFilterItems();
		})();
	}

	/* -------------------------------------------- */

	static _getProficiencies_getCountAtLevel ({progression, level}) {
		if (level <= 0) return 0;
		return Object.entries(progression)
			.filter(([lvl]) => Number(lvl) <= level)
			.sort(([a], [b]) => Number(b) - Number(a))[0]?.[1] ?? progression["*"] ?? 0;
	}

	static _getProficiencies_getMatchingUids (
		{
			availableProficiencyManager,
			fromFilter,
		},
	) {
		return this._MODAL_FILTER_ITEMS.getEntitiesMatchingFilterExpression({filterExpression: fromFilter})
			.filter(ent => ent.mastery?.length)
			.map(ent => DataUtil.proxy.getUid("item", ent))
			.filter(uid => availableProficiencyManager.availableProficiencyInfoWeapons.validProficiencies.has(uid));
	}

	static getProficiencies (
		{
			entity,
			weaponProficiencies,
			level = 1,
			previousLevel = 0,
			availableProficiencyManager,
		},
	) {
		const itemMasteriesProgression = entity?.itemMasteriesProgression || entity?.entryData?.itemMasteriesProgression;

		if (!itemMasteriesProgression) return null;

		const itemMasteries = entity?.itemMasteries || entity?.entryData?.itemMasteries;
		weaponProficiencies ||= entity?.weaponProficiencies || entity?.entryData?.weaponProficiencies;

		const proficiencies = itemMasteries === true ? weaponProficiencies : itemMasteries;
		if (!proficiencies?.length) return null;

		const count = this._getProficiencies_getCountAtLevel({progression: itemMasteriesProgression, level})
			- this._getProficiencies_getCountAtLevel({progression: itemMasteriesProgression, level: previousLevel});
		if (count <= 0) return null;

		if (!this._MODAL_FILTER_ITEMS) throw new Error(`Item filter not initialized! This is a bug!`);

		return proficiencies
			.map(proficiencySet => {
				const mappedFroms = new Set();

				Object.entries(proficiencySet)
					.forEach(([key, value]) => {
						if (!value) return;

						if (key === "all" || key === "choose") {
							this._getProficiencies_getMatchingUids({availableProficiencyManager, fromFilter: value.fromFilter})
								.forEach(uid => mappedFroms.add(uid));
							return;
						}

						if (key.includes("|")) return mappedFroms.add(key);

						if (!(key in this._WEAPON_PROF_GROUP_TO_FILTER_EXPRESSION)) {
							console.warn(...LGTD, `Unhandled itemMasteries key "${key}"!`);
							return;
						}

						if (!this._WEAPON_PROF_GROUP_TO_FILTER_EXPRESSION[key]) return;

						this._getProficiencies_getMatchingUids({availableProficiencyManager, fromFilter: this._WEAPON_PROF_GROUP_TO_FILTER_EXPRESSION[key]})
							.forEach(uid => mappedFroms.add(uid));
					});

				return {
					choose: {
						from: [...mappedFroms],
						count,
					},
				};
			});
	}
}

