/** @abstract */
class ActorUpdateFillerBase {
	_actorData;
	_availableProficiencyManager = null;
	_dataBuilderOpts = null;

	_titlePrefix = null;

	constructor (
		{
			actorData,
			availableProficiencyManager,
			dataBuilderOpts,
			// Other options
			titlePrefix = null,
		},
	) {
		this._actorData = actorData;
		this._availableProficiencyManager = availableProficiencyManager;
		this._dataBuilderOpts = dataBuilderOpts;
		this._titlePrefix = titlePrefix;
	}

	/**
	 * @abstract
	 * @return {ActorUpdateFillerChosen}
	 */
	doFill (opts) {
		throw new Error("Unimplemented!");
	}

	/**
	 * @abstract
	 * @return {Promise<ActorUpdateFillerChosen>}
	 */
	async pPromptAndFill (opts) {
		throw new Error("Unimplemented!");
	}
}

class ActorUpdateFillerItemMasteries extends ActorUpdateFillerBase {
	doFill (
		{
			existingProfsActor,
			formData,
		},
	) {
		if (!formData?.data?.itemMasteries) return new ActorUpdateFillerChosen();

		const existingUpdate = MiscUtil.get(this._actorData, "traits", "weaponProf", "mastery", "value") || [];

		const value = new Set([...(existingProfsActor?.value || []), ...existingUpdate]);
		const chosen = [];
		Object.entries(formData.data.itemMasteries)
			.forEach(([uid, isSelected]) => {
				if (!isSelected) return;

				const mapped = UtilActors.getMappedWeaponProficiency(uid) || uid;

				if (!value.has(mapped)) chosen.push(mapped);
				value.add(mapped);
			});

		MiscUtil.set(this._actorData, "traits", "weaponProf", "mastery", "value", [...value].sort(SortUtil.ascSortLower));

		return new ActorUpdateFillerChosen({
			itemMasteriesChosenFvtt: chosen,
		});
	}

	async pPromptAndFill (
		{
			existingProfsActor,
			proficiencies,
		},
	) {
		if (!proficiencies?.length) return new ActorUpdateFillerChosen();
		proficiencies = Charactermancer_OtherProficiencySelect.getMappedItemMasteries(proficiencies);

		const formData = await Charactermancer_OtherProficiencySelect.pGetUserInput({
			titlePrefix: this._titlePrefix,
			existingFvtt: {
				itemMasteries: existingProfsActor,
			},
			available: proficiencies,
			availableProficiencyManager: this._availableProficiencyManager,
		});
		if (!formData) {
			if (this._dataBuilderOpts) this._dataBuilderOpts.isCancelled = true;
			return new ActorUpdateFillerChosen();
		}
		if (formData === VeCt.SYM_UI_SKIP) return new ActorUpdateFillerChosen();

		return this.doFill({
			existingProfsActor,
			formData,
		});
	}
}

