/**
 * Note the use of caching -- we expect that currency config won't change without reload,
 *   and prefer to avoid performance implications.
 */
class Dnd5eCurrencyUtil {
	static _CACHE_CURRENCY_DENOMINATIONS = null;

	static _getCurrencyDenominations () {
		return Object.keys(CONFIG.DND5E.currencies);
	}

	static getCurrencyDenominations () {
		return (this._CACHE_CURRENCY_DENOMINATIONS ??= this._getCurrencyDenominations());
	}

	/* -------------------------------------------- */

	static _CACHE_CURRENCY_CONVERSION_TABLE = null;

	static _getCurrencyConversionTable () {
		// dnd5e conversions are expressed as coins per GP; 5etools values are CP
		const conversionCopper = CONFIG.DND5E.currencies.cp?.conversion ?? 100;

		return Object.entries(CONFIG.DND5E.currencies)
			.filter(([, currencyMeta]) => currencyMeta.conversion != null && currencyMeta.conversion > 0)
			.map(([coin, currencyMeta]) => ({
				coin,
				mult: currencyMeta.conversion / conversionCopper,
			}))
			.sort((a, b) => SortUtil.ascSort(b.mult, a.mult));
	}

	static getCurrencyConversionTable () {
		return (this._CACHE_CURRENCY_CONVERSION_TABLE ??= this._getCurrencyConversionTable());
	}

	/* -------------------------------------------- */

	static getDefaultCurrencyDenomination () {
		return CONFIG.DND5E.defaultCurrency;
	}
}

class EquipmentCompBase extends BaseComponent {
	/**
	 *
	 * @param opts
	 * @param opts.compEquipmentAvailable
	 * @param opts.compCurrency
	 * @param [opts.actor]
	 */
	constructor (opts) {
		super();
		this._compEquipmentAvailable = opts.compEquipmentAvailable;
		this._compCurrency = opts.compCurrency;
		this._actor = opts.actor;
	}

	static _getHumanReadableCoinage (copper) {
		const currencyConversionTable = Dnd5eCurrencyUtil.getCurrencyConversionTable();
		const asCoins = CurrencyUtil.doSimplifyCoins(
			{cp: copper},
			{currencyConversionTable},
		);
		return currencyConversionTable
			.reverse().map(({coin}) => asCoins[coin] ? `${asCoins[coin].toLocaleString()} ${coin}` : null)
			.filter(Boolean)
			.join(", ") || `0 ${Dnd5eCurrencyUtil.getDefaultCurrencyDenomination()}`;
	}

	async _pIsIgnoreGoldWarning ({htmlDescription}) {
		if (!Object.keys(this._compCurrency.startingEquipment || {}).length || this._compCurrency.hasShownGoldWarning) return true;

		const isUseGold = await InputUiUtil.pGetUserBoolean({
			title: `Are you sure?`,
			htmlDescription,
			textYes: "Yes",
			textNo: "Cancel",
		});
		if (!isUseGold) return false;

		this._compCurrency.hasShownGoldWarning = true;
		return true;
	}

	_getBtnRollStartingGold () {
		return veT`<button class="ve-btn ve-btn-5et ve-btn-default ve-btn-xs">Roll Starting Gold</button>`
			.vee.onn("click", async () => {
				if (
					!(
						await this._pIsIgnoreGoldWarning({
							htmlDescription: `Using gold to buy starting equipment is an alternative to standard starting equipment.<br>Are you sure you want to use gold?`,
						})
					)
				) return;

				const roll = new CONFIG.Dice.BasicRoll(this._compCurrency.rollableExpressionGold);
				await roll.evaluate();
				this._compCurrency.cpRolled = roll.total * 100;

				const optsToMessage = {sound: null};
				if (this._actor) {
					optsToMessage.speaker = {actor: this._actor.id};
					optsToMessage.flavor = `<div>${this._actor.name} rolls starting gold!</div>`;
				}

				roll
					.toMessage(optsToMessage)
					.then(null);
			});
	}

	_getBtnEnterStartingGold () {
		return veT`<button class="ve-btn ve-btn-5et ve-btn-default ve-btn-xs"></button>`
			.vee.onn("click", async () => {
				if (
					!(
						await this._pIsIgnoreGoldWarning({
							htmlDescription: `Entering a custom gold amount will prevent standard starting equipment from being added to your sheet.<br>Are you sure you want to use a custom gold amount?`,
						})
					)
				) return;

				const opts = {
					min: 0,
					title: "Enter Gold Amount",
					int: true,
				};
				if (this._compCurrency.cpRolled != null) opts.default = Math.round(this._compCurrency.cpRolled / 100);

				const amount = await InputUiUtil.pGetUserNumber(opts);
				if (amount == null) return;

				this._compCurrency.cpRolled = amount * 100;
			});
	}

	_getDispRolledGold () {
		const dispRolled = veT`<div></div>`;

		const hkRolled = () => {
			if (this._compCurrency.cpRolled == null && this._compCurrency.rollableExpressionGold != null) dispRolled.vee.html(`<i class="ve-muted">${this._compCurrency.rollableExpressionGold}</i>`);
			else dispRolled.vee.html(this.constructor._getHumanReadableCoinage(this._compCurrency.cpRolled || 0));
		};
		hkRolled();
		this._compCurrency.addHookRollableExpressionGold(hkRolled);
		this._compCurrency.addHookCpRolled(hkRolled);

		return dispRolled;
	}

	_getBtnClearRolledGold () {
		return veT`<button class="ve-btn ve-btn-5et ve-btn-default ve-btn-xs ve-ml-1" title="Reset"><span class="glyphicon glyphicon-refresh"></span></button>`
			.vee.onn("click", async () => {
				if (
					!(await InputUiUtil.pGetUserBoolean({
						title: `Are you sure?`,
						htmlDescription: `This will discard your current starting gold roll or value.`,
					}))
				) return;
				this._compCurrency.cpRolled = null;
			});
	}

	_getWrpRollOrManual ({btnRoll, dispRollOrManual, btnManual, dispRolled, btnClearRolled}) {
		const stgDispRolled = dispRolled ? veT`<div class="ve-m-1"> = </div>${dispRolled}${btnClearRolled}` : null;
		return veT`<div class="ve-flex-v-center">${btnRoll}${dispRollOrManual}${btnManual}${stgDispRolled}</div>`;
	}

	_doBindRollableExpressionHooks ({dispRollOrManual, btnRoll, btnManual, wrpRollOrManual}) {
		const hkRollableExpressionGold = () => {
			// Only show the "roll" controls if we have a rollable expression (which implies we also have starting equipment)
			dispRollOrManual.vee.toggle(this._compCurrency.rollableExpressionGold);
			btnRoll
				.vee.toggle(this._compCurrency.rollableExpressionGold)
				.vee.tooltip(`Rolling ${this._compCurrency.rollableExpressionGold}`);

			// Show the manual controls if we have any starting equipment
			btnManual
				.vee.toggle(this._compCurrency.startingEquipment)
				.vee.tooltip(
					this._compCurrency.rollableExpressionGold
						? `Manually enter a starting gold amount, as an alternate to rolling.`
						: `Manually enter a starting gold amount`,
				)
				.vee.txt(
					this._compCurrency.rollableExpressionGold
						? `Enter Starting Gold`
						: `Enter Custom Starting Gold`,
				);

			// Show the roll/manual controls if we have any starting equipment; specific parts may be hidden as per the above
			wrpRollOrManual.vee.toggle(this._compCurrency.startingEquipment);
		};
		this._compCurrency.addHookStartingEquipment(hkRollableExpressionGold);
		this._compCurrency.addHookRollableExpressionGold(hkRollableExpressionGold);
		hkRollableExpressionGold();
	}
}

class EquipmentUtilCost {
	static isUseRarityValue () {
		return VetoolsConfig$1.get("styleSwitcher", "style") === SITE_STYLE__ONE
			&& Config.get("equipmentShop", "isUseRarityPricing");
	}

	/* -------------------------------------------- */

	static getItemCost (item, {isUseRarityValue = null} = {}) {
		isUseRarityValue ??= this.isUseRarityValue();

		const valueBase = UtilEntityItem.getItemValue({item, isUseRarityValue}) || 0;
		return valueBase * Config.get("equipmentShop", "priceMultiplier");
	}

	static getItemDisplayListCostInfo (item, {isUseRarityValue = null} = {}) {
		isUseRarityValue ??= this.isUseRarityValue();

		const optsValue = {isShortForm: true, multiplier: Config.get("equipmentShop", "priceMultiplier")};

		const fromValue = Parser.itemValueToFullMultiCurrency(item, optsValue);
		if (fromValue) return {text: fromValue, isFromRarity: false};

		if (!UtilDocumentItemItem.isUseRarityValue()) return {text: fromValue, isFromRarity: false};

		return {
			text: Parser.itemValueToFullMultiCurrency({value: UtilEntityItem.getItemValue({item, isUseRarityValue}), currencyConversion: item.currencyConversion}, optsValue),
			isFromRarity: true,
		};
	}
}

class ModalFilterEquipment extends ModalFilterBase {
	static _getFilterColumnHeaders (btnMeta) {
		return super._getFilterColumnHeaders(btnMeta).map(btn => btn.vee.addClass(`ve-btn-5et`));
	}

	constructor (compStartingEquipment) {
		super({
			pageFilter: new PageFilterItems({
				filterOpts: {
					"Category": {
						deselFn: (it) => it === "Generic Variant",
					},
				},
			}),
			namespace: "ImportListCharacter_modalFilterEquipment",
			sortByInitial: "type",
		});
		this._compParent = compStartingEquipment;
		this._previewButtonHandler = new ListUiPreviewButtonHandlerStatsFluff({page: UrlUtil.PG_ITEMS});
	}

	_getColumnHeaders () {
		const btnMeta = [
			{sort: "name", text: "Name", width: "3-2"},
			{sort: "type", text: "Type", width: "3-2"},
			{sort: "cost", text: "Cost", width: "1-8"},
			{sort: "source", text: "Source", width: "1-8"},
		];
		return this.constructor._getFilterColumnHeaders(btnMeta);
	}

	async _pLoadAllData () { return []; }

	_getWrpList () { return veT`<div class="veapp__list ve-mb-1 ve-h-100 ve-min-h-0"></div>`; }

	_getColumnHeaderPreviewAll (opts) {
		return super._getColumnHeaderPreviewAll(opts)
			.vee.addClass("ve-btn-5et")
			.vee.addClass("ve-muted");
	}

	_getListItem (pageFilter, item, itI) {
		if (item.noDisplay) return null;

		const isUseRarityValue = EquipmentUtilCost.isUseRarityValue();

		Renderer.item.enhanceItem(item);
		pageFilter.mutateAndAddToFilters(item);

		const eleRow = document.createElement("div");
		eleRow.className = "px-0 w-100 veapp__list-row ve-flex-col no-shrink";

		const hash = UrlUtil.URL_TO_HASH_BUILDER[UrlUtil.PG_ITEMS](item);
		const source = Parser.sourceJsonToAbv(item.source);
		const type = item._textTypes.join(", ");
		const costInfo = EquipmentUtilCost.getItemDisplayListCostInfo(item, {isUseRarityValue});

		eleRow.innerHTML = `<div class="ve-w-100 veapp__list-row-hoverable ve-flex-v-center">
			<div class="ve-col-1 ve-flex-vh-center">
				<div class="ve-ui-list__btn-inline" title="Toggle Preview (SHIFT to Toggle Info Preview)">${ListUiPreviewButtonHandlerBase.HTML_GLYPHICON_EXPAND}</div>
			</div>

			<span class="ve-col-3-2">${item.name}</span>
			<span class="ve-col-3-2">${item._textTypes.join(", ").toTitleCase()}</span>
			<span class="ve-col-1-8 ve-text-right ve-px-1 ${costInfo.isFromRarity ? "ve-italic ve-muted" : ""}" ${costInfo.isFromRarity ? `title="Price based on item rarity"` : ""}>${costInfo.text.replace(/ +/g, "\u00A0")}</span>
			<span class="ve-col-1-8 ve-text-center ${Parser.sourceJsonToSourceClassname(item.source)} ve-pr-0" title="${Parser.sourceJsonToFull(item.source)}">${source}</span>
			<div class="ve-col-1 ve-flex-vh-center ve-btn-group ve-py-1p ">
				<button class="ve-btn ve-btn-5et ve-btn-xxs ve-btn-default" title="Add (SHIFT to add 5; CTRL to ignore price)"><span class="glyphicon glyphicon-plus ve-ml-1p ve-top-2p"></span></button>
				<button class="ve-btn ve-btn-5et ve-btn-xxs ve-btn-default" title="Remove (SHIFT to remove 5; CTRL to ignore price)"><span class="glyphicon glyphicon-minus ve-top-2p"></span></button>
			</div>
		</div>`;

		const btnShowHidePreview = eleRow.firstElementChild.firstElementChild.firstElementChild;

		const listItem = new ListItem({
			id: itI,
			ele: eleRow,
			name: item.name,
			values: {
				source,
				sourceJson: item.source,
				cost: EquipmentUtilCost.getItemCost(item, {isUseRarityValue}),
				type,
			},
			data: {
				hash,
				btnAdd: eleRow.firstElementChild.lastElementChild.firstElementChild,
				btnSubtract: eleRow.firstElementChild.lastElementChild.lastElementChild,
				btnShowHidePreview,
			},
		});

		this._previewButtonHandler.bindPreviewButton({entity: item, listItem, btnShowHidePreview});

		return listItem;
	}

	setDataList (itemDatas) {
		this._list.removeAllItems();

		const isUseRarityValue = EquipmentUtilCost.isUseRarityValue();

		this._allData = (itemDatas || [])
			.filter(ent => {
				if (UtilEntityItem.isTreasureItem(ent)) return false;
				if (ent.value != null) return true;

				if (
					ent._valueFromRarity != null
					&& isUseRarityValue
				) return true;

				return false;
			});

		this._allData.forEach((it, i) => {
			this._pageFilter.mutateAndAddToFilters(it);

			const filterListItem = this._getListItem(this._pageFilter, it, i);
			this._list.addItem(filterListItem);

			const itemUid = `${it.name}|${it.source}`;

			const onClickAdd = evt => {
				evt.preventDefault();
				evt.stopPropagation();

				const isIgnoreCost = EventUtil.isCtrlMetaKey(evt);

				if (evt.shiftKey) this._compParent.addBoughtItem(itemUid, {quantity: 5, isIgnoreCost});
				else this._compParent.addBoughtItem(itemUid, {isIgnoreCost});
			};

			const onClickSubtract = evt => {
				evt.preventDefault();
				evt.stopPropagation();

				const isIgnoreCost = EventUtil.isCtrlMetaKey(evt);

				if (evt.shiftKey) this._compParent.subtractBoughtItem(itemUid, {quantity: 5, isIgnoreCost});
				else this._compParent.subtractBoughtItem(itemUid, {isIgnoreCost});
			};

			veE({ele: filterListItem.ele})
				.vee.onn("click", evt => onClickAdd(evt))
				.vee.onn("contextmenu", evt => onClickSubtract(evt));

			veE({ele: filterListItem.data.btnAdd})
				.vee.onn("click", evt => onClickAdd(evt))
				.vee.onn("contextmenu", evt => onClickSubtract(evt));

			veE({ele: filterListItem.data.btnSubtract})
				.vee.onn("click", evt => onClickSubtract(evt))
				.vee.onn("contextmenu", evt => onClickAdd(evt));
		});

		// Wipe the source filter, as we assume the user should be able to see everything they either selected
		//   or were given (in the case of a predefined item list)
		this._pageFilter.sourceFilter.setFromValues({"Source": {}});

		this._pageFilter.filterBox.render();
		this._list.update();
		this._handleFilterChange();
	}
}

