class UtilAdvancementsFeatureFormData {
	static _PROFICIENCY_METAS = [
		{
			propEntity: "skillProficiencies",
			propFormDatas: "formDatasSkillProficiencies",
			fnGetAdvancement: ({proficiencies, formData, level}) => UtilAdvancements.getAdvancementSkills({
				skillProficiencies: proficiencies,
				skillsChosenFvtt: Object.keys(formData.data?.skillProficiencies || {})
					.map(name => Parser._parse_bToA(SKILL_ABV_TO_FULL, name))
					.filter(Boolean),
				level,
			}),
		},
		{
			propEntity: "savingThrowProficiencies",
			propFormDatas: "formDatasSavingThrowProficiencies",
			fnGetAdvancement: ({proficiencies, formData, level}) => UtilAdvancements.getAdvancementSaves({
				savingThrowProficiencies: proficiencies,
				savingThrowsChosenFvtt: Object.keys(formData.data?.savingThrowProficiencies || {}),
				level,
			}),
		},
	];

	static getAdvancementMetas ({formData, level}) {
		const out = [];
		const features = formData.data?.features || [];

		for (const proficiencyMeta of this._PROFICIENCY_METAS) {
			const formDatas = formData.data?.[proficiencyMeta.propFormDatas] || [];
			let ixFormData = 0;

			for (const {entity, type} of features) {
				const proficiencies = entity?.[proficiencyMeta.propEntity] || entity?.entryData?.[proficiencyMeta.propEntity];
				if (!proficiencies) continue;

				const formDataProficiency = formDatas[ixFormData++];
				if (!formDataProficiency) continue;

				const advancement = proficiencyMeta.fnGetAdvancement({
					proficiencies,
					formData: formDataProficiency,
					level: entity.level ?? level,
				});
				if (!advancement) continue;
				advancement.name = `${entity.name}: ${advancement.name}`;

				out.push({advancement, type});
			}
		}

		return out;
	}
}

