/* -------------------------------------------- */

class CompendiumTokenFetcher {
	constructor ({ent, props, taskRunner}) {
		this._ent = ent;
		this._props = props;
		this._taskRunner = taskRunner;
	}

	async pGetCompendiumTokenInfo () {
		for (const prop of this._props) {
			const dataFromCompendium = await CompendiumCache.pGetAdditionalDataDoc(prop, this._ent, {taskRunner: this._taskRunner});
			const tokenUrl = dataFromCompendium?.prototypeToken?.texture?.src;

			// Avoid using the default "mystery-man" image
			if (tokenUrl && !UtilImage.isDefaultActorImage(tokenUrl)) {
				const scale = dataFromCompendium?.prototypeToken?.texture?.scaleX;
				const dimensions = dataFromCompendium?.prototypeToken?.width;

				return new TokenInfo({
					img: tokenUrl,
					scale: scale == null || scale === 1 ? null : scale,
					dimensions: dimensions == null || dimensions === 1 ? null : dimensions,
				});
			}
		}
		return null;
	}
}

/* -------------------------------------------- */

/** @abstract */
class TokenFetcherBase {
	static get _PROPS () { throw new Error("Unimplemented!"); }

	/* -------------------------------------------- */

	static _getTokenInfoGetterEntityClazz () { throw new Error("Unimplemented!"); }

	static _getTokenInfoGetterClazzes ({isPreferFoundryOverride = null} = {}) {
		const standardGetters = [
			TokenInfoGetterPlutonium,
			TokenInfoGetterFoundry,
		];

		if (
			isPreferFoundryOverride != null
				? !!isPreferFoundryOverride
				: Config.get("import", "isPreferFoundryTokens")
		) {
			standardGetters.reverse();
		}

		return [
			this._getTokenInfoGetterEntityClazz(),
			...this._getTokenInfoGetterClazzesAdditional(),
			...standardGetters,
		];
	}

	static _getTokenInfoGetterClazzesAdditional () { return []; }

	/* -------------------------------------------- */

	static _getSubjectInfoGetters () {
		return [
			SubjectInfoGetterEntity,
			...this._getSubjectInfoGettersAdditional(),
		];
	}

	static _getSubjectInfoGettersAdditional () { return []; }

	/* -------------------------------------------- */

	/**
	 * @param ent
	 * @param {?AppTaskRunner} taskRunner
	 * @param {?boolean} isPreferFoundryOverride
	 */
	static async pGetAppearanceInfo (ent, {taskRunner = null, isPreferFoundryOverride = null} = {}) {
		const out = new AppearanceInfo();
		out.tokenInfo = await this.pGetTokenInfo(ent, {taskRunner, isPreferFoundryOverride});
		out.subjectInfo = await this._pGetSubjectInfo(ent, {taskRunner, isPreferFoundryOverride});
		return out;
	}

	/* -------------------------------------------- */

	/**
	 * @param ent
	 * @param {?AppTaskRunner} taskRunner
	 * @param {?boolean} isPreferFoundryOverride
	 */
	static async pGetTokenInfo (ent, {taskRunner = null, isPreferFoundryOverride = null} = {}) {
		const tokenGetters = this._getTokenInfoGetterClazzes({isPreferFoundryOverride})
			.map(Clazz => new Clazz({parent: this, ent, props: this._PROPS, taskRunner}));

		for (const tokenGetter of tokenGetters) {
			const tokenInfo = await tokenGetter.pGetTokenInfo();
			if (tokenInfo) return tokenInfo;
		}

		return new TokenInfo({
			img: this._getFallbackImg(),
			isFallback: true,
		});
	}

	static _getFallbackImg () { return VetoolsTokenAdapter.getBlankTokenUrl(); }

	/* -------------------------------------------- */

	/**
	 * @param ent
	 * @param {?AppTaskRunner} taskRunner
	 * @param {?boolean} isPreferFoundryOverride
	 */
	static async _pGetSubjectInfo (ent, {taskRunner = null, isPreferFoundryOverride = null} = {}) {
		const subjectGetters = this._getSubjectInfoGetters()
			.map(Clazz => new Clazz({parent: this, ent, props: this._PROPS, taskRunner}));

		for (const subjectGetter of subjectGetters) {
			const subjectInfo = await subjectGetter.pGetSubjectInfo();
			if (subjectInfo) return subjectInfo;
		}

		return null;
	}

	/* -------------------------------------------- */

	static async pGetCompendiumTokenInfo (ent, {taskRunner = null} = {}) {
		return new CompendiumTokenFetcher({ent, props: this._PROPS, taskRunner}).pGetCompendiumTokenInfo();
	}
}

// TODO(Future) support dynamic ring tokens defined in the lookup
class IntegrationPf2eTokensBestiaries {
	static _P_LOAD_PATHFINDER_TOKEN_BESTIARIES = null;

	// Match by: slugged name -> split on `-` -> alphabetically sort tokens
	static _getLookupName (name) {
		return name.toLowerCase()
			.slugify({strict: true})
			.split("-")
			.map(it => it.trim())
			.filter(Boolean)
			.sort(SortUtil.ascSortLower)
			.join("-");
	}

	static _getTokenInfoExpanded (tokenInfo) {
		if (!tokenInfo) return null;

		if (typeof tokenInfo === "string") {
			return {
				imgToken: tokenInfo,
				tokenScale: null,
			};
		}

		const scaleRaw = tokenInfo.texture?.scaleX; // (Assume X/Y scale are the same)
		const scale = scaleRaw != null && scaleRaw !== 1 ? scaleRaw : null;
		return {
			imgToken: tokenInfo.texture?.src,
			tokenScale: scale,
		};
	}

	static async pGetPathfinderTokenPackBestiariesMeta (imp) {
		this._P_LOAD_PATHFINDER_TOKEN_BESTIARIES = this._P_LOAD_PATHFINDER_TOKEN_BESTIARIES || (async () => {
			// Order matters (later = higher priority); prefer the dnd5e version for name mappings
			const pathsIndexArt = [
				game.modules.get(UtilCompat.MODULE_PF2E_TOKENS_BESTIARIES).flags?.["compendiumArtMappings"]?.["pf2e"]?.["mapping"],
				game.modules.get(UtilCompat.MODULE_PF2E_TOKENS_BESTIARIES).flags?.[UtilCompat.MODULE_PF2E_TOKENS_BESTIARIES]?.["dnd5e-art"],
			]
				.filter(Boolean);

			if (!pathsIndexArt.length) {
				console.warn(...LGT, `Failed to index "Pathfinder Tokens: Bestiaries" tokens \u2014 could not find compendium art mappings!`);
				return {};
			}

			const indexesArt = await pathsIndexArt.pMap(url => DataUtil.loadJSON(url));

			const out = {};

			for (const indexArt of indexesArt) {
				for (const [packId, indexPack] of Object.entries(indexArt)) {
					const pack = game.packs.get(packId);
					const packIndex = pack ? await pack.getIndex() : null;

					Object.entries(indexPack)
						.forEach(([packDocId, {actor: actorInfo, token: tokenInfo}]) => {
							// Based on `Actor5e.prototype._initializeSource`, `actorInfo` is a string, and `tokenInfo` is
							//   a string or an object.
							const actorInfoExpanded = actorInfo ? {path: actorInfo} : null;
							const tokenInfoExpanded = this._getTokenInfoExpanded(tokenInfo);

							if (!actorInfoExpanded && !tokenInfoExpanded) return;

							const ptName = packIndex && packIndex.get(packDocId)
								? this._getLookupName(packIndex.get(packDocId).name)
								: this._getLookupName((actorInfoExpanded || tokenInfoExpanded).path.split("/").last().split(".")[0]);

							out[ptName] = {
								imgToken: tokenInfoExpanded?.imgToken,
								tokenScale: tokenInfoExpanded?.tokenScale,
								imgPortrait: actorInfoExpanded?.path,
							};
						});
				}
			}

			return out;
		})();

		return (await this._P_LOAD_PATHFINDER_TOKEN_BESTIARIES)[this._getLookupName(imp.name || "")];
	}
}

class UtilTokenFetcher {
	/**
	 * As of 2025-10-13, core settings clobber ring "enabled" data during
	 *   document create/update. Therefore, if we are functionally unable
	 *   to use the ring, avoid fetching subject info.
	 */
	static isEnableDynamicRing (
		{
			configGroup,
			actorType,
		},
	) {
		if (!Config.get(configGroup, "isEnableDynamicRing")) return false;

		const tokenSettings = UtilGameSettings.getSafe("core", "prototypeTokenOverrides");

		// Actor-type-specific setting is designed to override the "base" setting
		const forActorType = tokenSettings?.[actorType]?.ring?.enabled;
		if (forActorType === true) return true;
		if (forActorType === false) return false;

		if (tokenSettings?.base?.ring?.enabled === false) return false;

		return true;
	}
}

