class TokenInfoGetterCreaturePf2eTokensBestiary extends TokenInfoGetterBase {
	async pGetTokenInfo () {
		const tokenInfo = await new CompendiumTokenFetcher({
			ent: this._ent,
			props: this._props,
			taskRunner: this._taskRunner,
		})
			.pGetCompendiumTokenInfo();
		if (tokenInfo?.img?.includes(`modules/${UtilCompat.MODULE_PF2E_TOKENS_BESTIARIES}/`)) return tokenInfo;

		const pfMeta = await IntegrationPf2eTokensBestiaries.pGetPathfinderTokenPackBestiariesMeta(this._ent);
		if (!pfMeta) return null;

		return new TokenInfo({
			img: pfMeta.imgToken,
			scale: pfMeta.tokenScale,
		});
	}
}

