	_getExistingClassItems (cls, importOpts) { return Charactermancer_Class_Util.getExistingClassItems(importOpts.actor, cls); }
	_getExistingSubclassItems (cls, sc, importOpts) { return Charactermancer_Class_Util.getExistingSubclassItems(importOpts.actor, cls, sc); }

