		const {existingClassItem, existingSubclassItem} = await this._pImportEntry_pGetUserExistingClassSubclassItem({cls, sc, importOpts, dataBuilderOpts});
		if (dataBuilderOpts.isCancelled) return;

		dataBuilderOpts.classItem = existingClassItem;
