					level: dataBuilderOpts.targetLevelThisClass,
					// Re-pick all masteries if none are in use
					previousLevel: [...(existingMasteries?.value || [])].length ? dataBuilderOpts.currentLevelThisClass : 0,
					availableProficiencyManager: importOpts.availableProficiencyManager,
