class DataConverterBackground extends DataConverter {
	static _configGroup = "importBackground";

	static _SideDataInterface = SideDataInterfaceBackground;
	static _ImageFetcher = ImageFetcherBackground;

	/**
	 * Note: there is no "get from SRD," as the single SRD background (as of 2022-04-28) has no data we are
	 * interested in.
	 * @param ent
	 * @param [opts] Options object.
	 * @param [opts.isAddDefaultOwnershipFromConfig]
	 * @param [opts.defaultOwnership]
	 * @param [opts.userOwnership]
	 * @param [opts.filterValues] Pre-baked filter values to be re-used when importing this from the item.
	 * @param [opts.fluff]
	 * @param [opts.actor]
	 * @param [opts.isActorItem]
	 * @param [opts.backgroundFeatureUuids]
	 * @param {AppTaskRunner} [opts.taskRunner]
	 */
	static async pGetDocumentJson (ent, opts) {
		opts = opts || {};
		if (opts.actor) opts.isActorItem = true;

		const idObj = UtilFoundryId.getIdObj({id: ent._foundryId});

		Renderer.get().setFirstSection(true).resetHeaderIndex();

		const fluff = opts.fluff || await Renderer.background.pGetFluff(ent);

		const documentType = "background";

		const description = await this._pGetBackgroundDescription(ent, fluff, opts);
		const advice = await UtilAdvice.pGetRenderedAdvice(await this._SideDataInterface.pGetAdviceSideLoaded(ent, {documentType}));
		const img = await this._ImageFetcher.pGetSaveImagePath(ent, {propCompendium: "background", fluff, taskRunner: opts.taskRunner});

		const systemBase = {
			description: {value: description + advice},
			source: UtilDocumentSource.getSourceObjectFromEntity(ent),

			wealth: UtilStartingEquipment.getWealth(ent.startingEquipment),

			advancement: UtilAdvancements.getAdvancementsObject([
				...UtilAdvancementsEntry.getGenericAdvancements(ent, opts),
				...(await this._SideDataInterface.pGetAdvancementSideLoaded(ent, {documentType}) || []),
			]),
		};

		const system = await this._pGetMergedActivitiesSystem({ent, systemBase, idObj, actorMultiImportHelper: opts.actorMultiImportHelper, documentType});

		const additionalFlags = await this._SideDataInterface.pGetFlagsSideLoaded(ent, {documentType});

		const effectsSideTuples = await this._SideDataInterface.pGetEffectsSideLoadedTuples({ent, img, actor: opts.actor, sheetItemStub: {...idObj}}, {documentType});
		effectsSideTuples.forEach(({effect, effectRaw}) => UtilActiveEffects.mutEffectDisabledTransfer(effect, "importBackground", UtilActiveEffects.getDisabledTransferHintsSideData(effectRaw)));

		const out = {
			...idObj,
			name: UtilApplications.getCleanEntityName(UtilEntityGeneric.getNameWithSourcePart(ent)),
			type: documentType,
			system,
			ownership: {default: 0},
			flags: {
				...this._getBackgroundFlags(ent, opts),
				...additionalFlags,
			},
			effects: UtilActiveEffects.getEffectsMutDedupeId(effectsSideTuples.map(it => it.effect)),
			img,
		};

		this._mutPostProcessDocumentData(Item, out, opts);

		return out;
	}

	static _pGetBackgroundDescription (ent, fluff, opts) {
		if (!Config.get(this._configGroup, "isImportDescription")) return "";

		return DescriptionRenderer.pGetWithDescriptionPlugins(async () => {
			const rendered = [
				fluff?.entries?.length ? Renderer.get().setFirstSection(true).render({type: "entries", entries: fluff?.entries}) : "",
				Renderer.get().setFirstSection(true).render({type: "entries", entries: ent.entries}),
			].filter(Boolean);

			const ptFeatures = this._pGetBackgroundDescription_features(ent, opts);

			return `<div>${rendered.join("<hr>")}${ptFeatures}</div>`;
		});
	}

	static _pGetBackgroundDescription_features (ent, opts) {
		// If importing to an actor directly, avoid populating feature text, as the features themselves will include it
		if (!opts.isActorItem) return "";

		if (!opts.actor || !opts.backgroundFeatureUuids?.length) return "";

		return `<div class="ve-mt-2">${opts.backgroundFeatureUuids.map(f => `<p>${f}</p>`).join("")}</div>`;
	}

	static _getBackgroundFlags (bg, opts) {
		const out = {
			[SharedConsts.MODULE_ID]: {
				page: UrlUtil.PG_BACKGROUNDS,
				source: bg.source,
				hash: UrlUtil.URL_TO_HASH_BUILDER[UrlUtil.PG_BACKGROUNDS](bg),
				propDroppable: "background",
				filterValues: opts.filterValues,
			},
		};

		if (opts.isActorItem) out[SharedConsts.MODULE_ID].isDirectImport = true;

		return out;
	}

	static getBackgroundStub () {
		return MiscUtil.copyFast(DataConverterBackground.STUB_BACKGROUND);
	}
}

