class _FolderInfo {
	constructor (
		{
			displayName,
			folder,
		},
	) {
		this.displayName = displayName;
		this.folder = folder;
	}
}

class FolderPathBuilderUi extends BaseComponent {
	static _TYPE_TO_CLS_ROW = {
		[PART_TYPE_TEXT_ONLY]: FolderPathBuilderRowTextOnly,
		[PART_TYPE_CONFIGURABLE]: FolderPathBuilderRowConfigurable,
	};

	static _getInitialFolderPathSpec ({folderPathBuilderStateManager, defaultFolderPathSpec, folderPathStrategies, typeDefault, isTextOnly}) {
		if (defaultFolderPathSpec) {
			return defaultFolderPathSpec
				.map(pt => FolderPathBuilderPartRegistry.getValidState({
					state: pt,
					typeDefault,
					folderPathStrategies,
					isForceTypeDefault: isTextOnly,
				}));
		}

		return folderPathBuilderStateManager
			? MiscUtil.copyFast(folderPathBuilderStateManager.getFolderPathSpec())
				.map(pt => FolderPathBuilderPartRegistry.getValidState({
					state: pt,
					typeDefault,
					folderPathStrategies,
					isForceTypeDefault: isTextOnly,
				}))
			: [];
	}

	/**
	 *
	 * @param folderPathBuilderStateManager
	 * @param defaultFolderPathSpec
	 * @param fnOnRowKeydown
	 * @param folderType
	 * @param {?Object<string, FolderPathBuilderPartStrategy>} folderPathStrategies
	 * @param isTextOnly
	 */
	constructor (
		{
			folderPathBuilderStateManager = null,
			defaultFolderPathSpec = null,
			fnOnRowKeydown = null,
			folderType,
			folderPathStrategies = null,
			isTextOnly = false,
		},
	) {
		super();

		this._folderPathBuilderStateManager = folderPathBuilderStateManager;
		this._folderType = folderType;
		this._fnOnRowKeydown = fnOnRowKeydown;
		this._folderPathStrategies = folderPathStrategies;
		this._isTextOnly = !!isTextOnly;
		this._typeDefault = FolderPathBuilderPartRegistry.getTypeDefault({
			isTextOnly: this._isTextOnly,
			folderPathStrategies: this._folderPathStrategies,
		});

		this._initialFolderPathSpec = FolderPathBuilderUi._getInitialFolderPathSpec({
			folderPathBuilderStateManager,
			defaultFolderPathSpec,
			folderPathStrategies: this._folderPathStrategies,
			typeDefault: this._typeDefault,
			isTextOnly: this._isTextOnly,
		});

		this._lock = new VeLock();
		this._childComps = [];
		this._wrpRows = null;
		this._fnsCleanup = [];
	}

	/* -------------------------------------------- */

	_isJournalEntryNamer () {
		const fromStateManager = this._folderPathBuilderStateManager?.getFolderPathForceLeafEntryName();
		if (fromStateManager != null) return fromStateManager;

		return UtilFolderPathBuilder.isJournalEntryNamer({
			folderType: this._folderType,
		});
	}

	_getMaxDepth () {
		let out = CONST.FOLDER_MAX_DEPTH__ORIGINAL ?? CONST.FOLDER_MAX_DEPTH;
		if (this._isJournalEntryNamer()) return out + 1;
		return out;
	}

	/* -------------------------------------------- */

	_getFolderPathSpec () { return this._childComps.map(it => MiscUtil.copyFast(it._state)); }

	getFolderPathStrings ({entity = null, folderPathSpec = null} = {}) {
		folderPathSpec ||= this._getFolderPathSpec();

		return UtilFolderPathBuilder.getFolderPathStrings({entity, folderPathSpec, folderPathStrategies: this._folderPathStrategies});
	}

	/* -------------------------------------------- */

	static _SEL_EXISTING_BASE_OPTION = `<option value="-1" selected>Select Existing...</option>`;

	_getSelExistingFolder (
		{
			folderType,
			fnOnAccept,
		},
	) {
		let folderMetas;

		const doUpdateFolderMetas = () => {
			folderMetas = game.folders.contents
				.filter(folder => folder.type === folderType)
				.map(folder => {
					const path = HelpersFolderPath.getFolderPath(folder, {isAddTrailingSlash: true});
					return new _FolderInfo({
						displayName: `${path || ""}${folder.name}`,
						folder,
					});
				})
				.sort((a, b) => SortUtil.ascSortLower(a.displayName, b.displayName));

			selExisting
				.vee.html(
					this.constructor._SEL_EXISTING_BASE_OPTION
					+ folderMetas
						.map((folderMeta, ix) => `<option value="${ix}">${folderMeta.displayName}</option>`)
						.join(""),
				);
		};

		const selExisting = veT`<select class="ve-w-140p ve-input-xs ve-form-control ve-italic ve-mr-1" title="Select Existing Folder Path">
			${this.constructor._SEL_EXISTING_BASE_OPTION}
		</select>`
			.vee.onn("pointerdown", () => {
				selExisting.vee.removeClass("ve-italic");
			})
			.vee.onn("change", () => {
				const meta = folderMetas[selExisting.vee.val()];
				fnOnAccept(meta);
				selExisting.vee.val("-1").vee.addClass("ve-italic");
			})
			.vee.onn("blur", () => {
				selExisting.vee.val("-1").vee.addClass("ve-italic");
			});

		doUpdateFolderMetas();

		this._fnsCleanup.push((() => {
			const hk = Hooks.on("deleteFolder", docHook => {
				if (docHook.type !== folderType) return;
				doUpdateFolderMetas();
			});

			return () => Hooks.off("deleteFolder", hk);
		})());

		this._fnsCleanup.push((() => {
			const hk = Hooks.on("createFolder", () => doUpdateFolderMetas());

			return () => Hooks.off("createFolder", hk);
		})());

		this._fnsCleanup.push((() => {
			const hk = Hooks.on("updateFolder", docHook => {
				if (docHook.type !== folderType) return;
				doUpdateFolderMetas();
			});

			return () => Hooks.off("updateFolder", hk);
		})());

		return selExisting;
	}

	render (parent) {
		const eleParent = veE({ele: parent});
		eleParent.vee.empty();

		const pod = this.getPod();

		this._wrpRows = veT`<div class="ve-flex-col ve-w-100 ve-h-100 ve-overflow-y-auto ve-relative"></div>`;
		this._childComps.forEach(it => it.render(this._wrpRows, pod));
		this._render_checkAddEmptyMessage();

		const selExisting = this._getSelExistingFolder({
			folderType: this._folderType,
			fnOnAccept: folderInfo => {
				if (!folderInfo) return;
				const folders = [
					...HelpersFolderPath.getFolderPathFolders(folderInfo.folder),
					folderInfo.folder,
				];

				this._removeAllRows();

				folders.forEach(fld => {
					this._render_addRow(pod, FolderPathBuilderPartRegistry.getStateFromFolder({folder: fld, type: this._typeDefault}));
				});
			},
		});

		const btnAdd = veT`<button class="ve-btn ve-btn-5et ve-btn-default ve-btn-xs"><span class="fas fa-fw fa-folder-plus"></span> Add Path Part</button>`
			.vee.onn("click", () => {
				const maxDepth = this._getMaxDepth();
				if (this._childComps.length >= maxDepth) return ui.notifications.warn(`Foundry currently supports a maximum of ${Parser.numberToText(maxDepth)} levels of directory nesting. T-too deep!`);
				this._render_addRow(pod);
			});

		this._initialFolderPathSpec.forEach(state => this._render_addRow(pod, state));

		veT(eleParent)`
			<div class="ve-w-100 ve-split-v-center ve-mb-1">
				<div>Folder Path:</div>
				<div class="ipt-group ve-flex-vh-center">
					${selExisting}
					${btnAdd}
				</div>
			</div>
			${this._wrpRows}
		`;
	}

	async _render_updateParentPath () {
		if (!this._folderPathBuilderStateManager) return;

		await (this._lock.pLock());
		try {
			await this._folderPathBuilderStateManager.pSetFolderPathSpec(this._getFolderPathSpec());
		} finally {
			this._lock.unlock();
		}
	}

	async pSaveState () {
		await this._render_updateParentPath();
	}

	_render_addRow (pod, state) {
		state = FolderPathBuilderPartRegistry.getValidState({
			state,
			typeDefault: this._typeDefault,
			folderPathStrategies: this._folderPathStrategies,
			isForceTypeDefault: this._isTextOnly,
		});

		const ClsRow = this.constructor._TYPE_TO_CLS_ROW[state.type];
		if (!ClsRow) throw new Error(`No folder path row renderer registered for type "${state.type}"!`);

		const comp = new ClsRow({
			fnOnKeydown: this._fnOnRowKeydown,
			folderPathStrategies: this._folderPathStrategies,
		});
		Object.assign(comp.__state, state);

		comp._addHookAll("state", () => this._render_updateParentPath());

		if (!this._childComps.length) this._wrpRows.vee.empty();

		this._childComps.push(comp);
		comp.render(this._wrpRows, pod);
		this._render_updateJournalEntryNameDisplays();
		this._render_updateParentPath().then(null);
	}

	_swapRowPositions (ixA, ixB) {
		const a = this._childComps[ixA];
		this._childComps[ixA] = this._childComps[ixB];
		this._childComps[ixB] = a;

		this._childComps.forEach(it => it.getEleRow().vee.appendTo(this._wrpRows));
		this._render_updateJournalEntryNameDisplays();
		this._render_updateParentPath().then(null);
	}

	_removeRow (comp) {
		const ix = this._childComps.indexOf(comp);
		if (~ix) {
			this._childComps.splice(ix, 1);
			comp.getEleRow().remove();
			this._render_updateParentPath().then(null);
		}

		this._render_updateJournalEntryNameDisplays();
		this._render_checkAddEmptyMessage();
	}

	_removeAllRows () {
		this._childComps.splice(0, this._childComps.length);
		this._wrpRows.vee.empty();
		this._render_updateParentPath().then(null);
		this._render_checkAddEmptyMessage();
	}

	_render_updateJournalEntryNameDisplays () {
		const isJournalEntryNamer = this._isJournalEntryNamer();
		this._childComps.forEach((comp, i) => comp.isJournalEntryName = isJournalEntryNamer && i === this._childComps.length - 1);
	}

	_render_checkAddEmptyMessage () {
		if (this._childComps.length) return;

		this._wrpRows.vee.appends(veT`<div class="ve-flex-v-center ve-w-100 ve-my-1"><i>(Directory root)</i></div>`);
	}

	/* -------------------------------------------- */

	doTeardown () {
		this._fnsCleanup.splice(0, this._fnsCleanup.length).forEach(fn => fn());
	}

	/* -------------------------------------------- */

	getPod () {
		const pod = super.getPod();
		pod.swapRowPositions = this._swapRowPositions.bind(this);
		pod.removeRow = this._removeRow.bind(this);
		pod.getElesChildren = () => this._childComps.map(it => it.getEleRow());
		return pod;
	}
}

const {HandlebarsApplicationMixin: HandlebarsApplicationMixin$g, ApplicationV2: ApplicationV2$g} = foundry.applications.api;

/**
 * A window-based wrapper around the full component.
 */
class FolderPathBuilderApp extends HandlebarsApplicationMixin$g(ApplicationV2$g) {
	constructor ({folderPathBuilderStateManager, folderType, folderPathStrategies = null, isTextOnly = false, titleSuffix = null}) {
		super({
			id: Consts.DEFAULT_APP_ID,
			classes: ["ve-app"],
			window: {
				title: `Edit Folder Path${titleSuffix ? ` \u2014 ${titleSuffix}` : ""}`,
				resizable: true,
				contentClasses: ["ve-app-window"],
			},
			position: {
				width: 480,
				height: 480,
			},
		});
		this._comp = new FolderPathBuilderUi({
			folderPathBuilderStateManager,
			folderType,
			folderPathStrategies,
			isTextOnly,
		});
	}

	static PARTS = {
		main: {
			template: `${SharedConsts.MODULE_LOCATION}/template/FolderPathBuilder.hbs`,
		},
	};

	_onRender () {
		super._onRender();

		const eleHtml = UtilApplications.getAppContentInner(this);

		const wrpFolderPathBuilder = veT`<div class="ve-w-100 ve-h-100 ve-min-h-0 ve-flex-col"></div>`;

		const btnSave = veT`<button class="ve-btn ve-btn-5et ve-btn-primary ve-w-100">Save</button>`
			.vee.onn("click", async () => {
				if (btnSave.vee.prop("disabled")) return;

				btnSave.vee.prop("disabled", true);
				await this._comp.pSaveState();
				await this.close();
			});

		veT(eleHtml)`<div class="ve-flex-col ve-w-100 ve-h-100 ve-min-h-0">
			${wrpFolderPathBuilder}

			<div class="ve-flex-vh-center ve-pb-1 ve-pr-2">
				${btnSave}
			</div>
		</div>`;

		this._comp.render(wrpFolderPathBuilder);
	}

	_onClose (opts) {
		super._onClose(opts);
		this._comp.doTeardown();
	}

	/* -------------------------------------------- */

	static async pHandleEditFolderPathClick ({folderPathBuilderStateManager, folderType, folderPathStrategies = null, isTextOnly = false, titleSuffix = null}) {
		await folderPathBuilderStateManager.pInit();
		const builderApp = new this({
			folderPathBuilderStateManager,
			folderType,
			folderPathStrategies,
			isTextOnly,
			titleSuffix,
		});
		builderApp.render(true);
	}
}

