			[UrlUtil.PG_PSIONICS]: new ChooseImporterClassInfo({ClsImportList: ImportListPsionic, ClsImporter: ImporterPsionic, isAcceptActor: true}),
			[UrlUtil.PG_OPT_FEATURES]: new ChooseImporterClassInfo({ClsImportList: ImportListOptionalfeature, ClsImporter: ImporterOptionalfeature, isAcceptActor: true}),
			[UrlUtil.PG_CONDITIONS_DISEASES]: new ChooseImporterClassInfo({ClsImportList: ImportListConditionDisease, ClsImporter: ImporterConditionDisease, isAcceptActor: true}),
			[UrlUtil.PG_ACTIONS]: new ChooseImporterClassInfo({ClsImportList: ImportListAction, ClsImporter: ImporterAction, isAcceptActor: true}),
