			[UrlUtil.PG_REWARDS]: new ChooseImporterClassInfo({ClsImportList: ImportListReward, ClsImporter: ImporterReward, isAcceptActor: true}),
			[UrlUtil.PG_CHAR_CREATION_OPTIONS]: new ChooseImporterClassInfo({ClsImportList: ImportListCharCreationOption, ClsImporter: ImporterCharCreationOption, isAcceptActor: true}),
			[UrlUtil.PG_VEHICLES]: new ChooseImporterClassInfo({ClsImportList: ImportListVehicle, ClsImporter: ImporterVehicle}),
			[UrlUtil.PG_OBJECTS]: new ChooseImporterClassInfo({ClsImportList: ImportListObject, ClsImporter: ImporterObject}),
			[UrlUtil.PG_DEITIES]: new ChooseImporterClassInfo({ClsImportList: ImportListDeity, ClsImporter: ImporterDeity}),
			[UrlUtil.PG_RECIPES]: new ChooseImporterClassInfo({ClsImportList: ImportListRecipe, ClsImporter: ImporterRecipe}),
			[UrlUtil.PG_TRAPS_HAZARDS]: new ChooseImporterClassInfo({ClsImportList: ImportListTrap, ClsImporter: ImporterTrap}),
