		["monster", "creature"]
			.forEach(prop => this._IMPORT_LIST_CLASS_META_LOOKUP[prop] = this._IMPORT_LIST_CLASS_META_LOOKUP[UrlUtil.PG_BESTIARY]);

		["class", "subclass"]
			.forEach(prop => this._IMPORT_LIST_CLASS_META_LOOKUP[prop] = this._IMPORT_LIST_CLASS_META_LOOKUP[UrlUtil.PG_CLASSES]);

