		["cult", "boon"]
			.forEach(prop => this._IMPORT_LIST_CLASS_META_LOOKUP[prop] = this._IMPORT_LIST_CLASS_META_LOOKUP[UrlUtil.PG_CULTS_BOONS]);

		this._IMPORT_LIST_CLASS_META_LOOKUP["raceFeature"] = new ChooseImporterClassInfo({ClsImportList: ImportListRaceFeature, ClsImporter: ImporterRaceFeature, isAcceptActor: true});
		this._IMPORT_LIST_CLASS_META_LOOKUP["backgroundFeature"] = new ChooseImporterClassInfo({ClsImportList: ImportListBackgroundFeature, ClsImporter: ImporterBackgroundFeature, isAcceptActor: true});
		this._IMPORT_LIST_CLASS_META_LOOKUP["hazard"] = new ChooseImporterClassInfo({ClsImportList: ImportListHazard, ClsImporter: ImporterHazard});

