		["vehupgrade", "vehicleUpgrade", "vehicleupgrade"]
			.forEach(prop => this._IMPORT_LIST_CLASS_META_LOOKUP[prop] = new ChooseImporterClassInfo({ClsImportList: ImportListVehicleUpgrade, ClsImporter: ImporterVehicleUpgrade}));

