class EncounterBuilderAdjusterBase {
	/**
	 * @param {EncounterPartyMetaBase} partyMeta
	 * @param {EncounterBuilderCacheBase} cache
	 * @param {number} budgetMin An XP or CR budget.
	 * @param {number} budgetMax An XP or CR budget.
	 * @param {"xp" | "cr"} budgetMode
	 */
	constructor (
		{
			partyMeta,
			cache,
			budgetMin,
			budgetMax,
			budgetMode,
		},
	) {
		this._partyMeta = partyMeta;
		this._cache = cache;
		this._budgetMin = budgetMin;
		this._budgetMax = budgetMax;
		this._budgetMode = budgetMode;
	}

	/**
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroups
	 * @return {Promise<?EncounterBuilderOptionalCandidateEncounter>}
	 */
	async pGetAdjustedEncounter ({creatureGroups}) {
		if (!creatureGroups.length) {
			JqueryUtil.doToast({content: `The current encounter contained no creatures! Please add some first.`, type: "warning"});
			return null;
		}

		if (creatureGroups.every(creatureGroup => creatureGroup.getIsLocked())) {
			JqueryUtil.doToast({content: `The current encounter contained only locked creatures! Please unlock or add some other creatures some first.`, type: "warning"});
			return null;
		}

		const creatureGroupsLocked = creatureGroups.filter(creatureGroup => creatureGroup.getIsLocked());
		creatureGroups = creatureGroups.map(creatureGroup => creatureGroup.getCopy());

		const creatureGroupsAdjustable = creatureGroups
			.filter(creatureGroup => !creatureGroup.getIsLocked() && creatureGroup.getCrNumber() != null);

		if (!creatureGroupsAdjustable.length) {
			JqueryUtil.doToast({content: `The current encounter contained only locked creatures, or creatures without XP values! Please unlock or add some other creatures some first.`, type: "warning"});
			return null;
		}

		creatureGroupsAdjustable
			.forEach(creatureGroup => creatureGroup.setCount(1));

		if (this._partyMeta.getEncounterSpendInfo(creatureGroups).adjustedSpend > this._budgetMax) {
			JqueryUtil.doToast({content: `Could not adjust the current encounter, try removing some creatures!`, type: "danger"});
			return null;
		}

		const closestSolution = await this._pGetAdjustedEncounter_getSolution({creatureGroups, creatureGroupsLocked, creatureGroupsAdjustable});

		if (!closestSolution.candidateEncounter) {
			JqueryUtil.doToast({content: closestSolution.message, type: "warning"});
			return null;
		}

		return closestSolution.candidateEncounter.getCreatureGroups();
	}

	/**
	 * @abstract
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroups
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroupsLocked
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroupsAdjustable
	 * @return {Promise<EncounterBuilderOptionalCandidateEncounter>}
	 */
	async _pGetAdjustedEncounter_getSolution ({creatureGroups, creatureGroupsLocked, creatureGroupsAdjustable}) { throw new Error("Unimplemented!"); }
}

class EncounterBuilderTemplaterSeeded extends EncounterBuilderTemplaterBase {
	/**
	 * @param {Array<number>} slotSeeds
	 * @param rest
	 */
	constructor ({slotSeeds, ...rest}) {
		super({...rest});
		this._slotSeeds = slotSeeds;
	}

	getEncounterTemplateInfo () {
		const cntLockedCreatures = this._creatureGroupsLocked
			.map(creatureGroup => creatureGroup.getCount())
			.sum();
		const cntSlotSeeds = this._slotSeeds?.length || 0;

		const lowestSpendAmount = Math.min(...this._slotSeeds);
		const lowestNonFreeSpendAmount = this._slotSeeds.filter(Boolean).length
			? Math.min(...this._slotSeeds.filter(Boolean))
			: null;

		const cntMin = Math.max(1, cntLockedCreatures + cntSlotSeeds);
		const cntMax = this._getMaxCreatureCount({cntMin, cntLockedCreatures});

		if (cntMin > cntMax) return new EncounterTemplateOptions({message: "Too many locked creatures! Unlock some, or add more players."});

		const {encounterSizeInfosBase, encounterSizeInfosAdditional} = new EncounterSizer({
			partyMeta: this._partyMeta,
			budgetMin: this._budgetMin,
			budgetMax: this._budgetMax,
			budgetMode: this._budgetMode,
		})
			.getEncounterSizeInfosGroups({
				creatureGroupsLocked: this._creatureGroupsLocked,
				slotSeeds: this._slotSeeds,
				cntLockedCreatures,
				lowestSpendAmount,
				lowestNonFreeSpendAmount,
				cntMin,
				cntMax,
			});

		if (!encounterSizeInfosBase.length && !encounterSizeInfosAdditional.length) return new EncounterTemplateOptions();

		const creatureSlotBundlesBase = this._getEncounterMetasCreatureSlotBundlesFromSeeds({
			cntLockedCreatures,
			lowestSpendAmount,
			encounterSizeMetas: encounterSizeInfosBase,
		});

		const creatureSlotBundlesAdditional = this._getEncounterMetasCreatureSlotBundlesFromSeeds({
			cntLockedCreatures,
			lowestSpendAmount,
			encounterSizeMetas: encounterSizeInfosAdditional,
		});

		return new EncounterTemplateOptions({
			templateOptions: this._getTemplateOptions({
				categorizedCreatureSlotBundlesBase: this._getCategorizedCreatureSlotBundles({
					creatureSlotBundles: creatureSlotBundlesBase,
				}),
				categorizedCreatureSlotBundlesAdditional: this._getCategorizedCreatureSlotBundles({
					creatureSlotBundles: creatureSlotBundlesAdditional,
				}),
			}),
		});
	}

	/**
	 * @param {number} cntLockedCreatures
	 * @param {Array<_EncounterSizeInfo>} encounterSizeMetas
	 **
	 * @return {Array<Array<CreatureSlot>>}
	 */
	_getEncounterMetasCreatureSlotBundlesFromSeeds (
		{
			cntLockedCreatures,
			encounterSizeMetas,
		},
	) {
		const slotSeeds = [...this._slotSeeds]
			.sort(SortUtil.ascSort);

		const slotSeedsSpendable = [...slotSeeds]
			.reverse()
			.unique();

		return encounterSizeMetas
			.flatMap(({cntCreatures, playerAdjustedSpendMult}) => {
				const spendLocked = this._creatureGroupsLocked
					.map(creatureGroup => creatureGroup.getCount() * creatureGroup.getSpend({budgetMode: this._budgetMode}) * playerAdjustedSpendMult)
					.sum();

				const slots = slotSeeds
					.map(spendAmount => new CreatureSlot({
						spendAmount,
						count: 1,
					}));

				const cntToAdd = cntCreatures - cntLockedCreatures - slotSeeds.length;
				if (cntToAdd < 0) throw new Error(`Should never occur!`);
				if (!cntToAdd) return [slots];

				const spendAmountToSlot = slots
					.reduce((accum, slot) => {
						(accum[slot.spendAmount] ||= []).push(slot);
						return accum;
					}, {});

				const getBudgetSpent = () => slots.map(slot => slot.getTotalSpend({playerAdjustedSpendMult})).sum() - spendLocked;

				const recurseFillSlots = (
					{
						operations,
						cpySlotSeedsSpendable,
						budgetRemaining,
						cntCreaturesAdded,
					},
				) => {
					if (cntCreaturesAdded >= cntToAdd) return cntToAdd - cntCreaturesAdded;
					if (!cpySlotSeedsSpendable.length) return cntToAdd - cntCreaturesAdded;

					for (let ixSlotSeed = 0; ixSlotSeed < cpySlotSeedsSpendable.length; ++ixSlotSeed) {
						const slotSeed = cpySlotSeedsSpendable[ixSlotSeed];
						if ((slotSeed * playerAdjustedSpendMult) > budgetRemaining) continue;

						const slot = RollerUtil.rollOnArray(spendAmountToSlot[slotSeed]);
						slot.count += 1;
						operations.push({slotSeed, slot, ixSlotSeed});

						return recurseFillSlots({
							operations,
							cpySlotSeedsSpendable,
							budgetRemaining: budgetRemaining - (slotSeed * playerAdjustedSpendMult),
							cntCreaturesAdded: cntCreaturesAdded + 1,
						});
					}

					const maxSpend = Math.max(...operations.map(({slotSeed}) => slotSeed));
					const ixUndo = operations.findIndex(({slotSeed}) => slotSeed === maxSpend);

					const [opUndo] = operations.splice(ixUndo, 1);
					if (!opUndo) return cntToAdd - cntCreaturesAdded;

					const {slotSeed, slot} = opUndo;
					slot.count -= 1;

					return recurseFillSlots({
						operations,
						cpySlotSeedsSpendable: cpySlotSeedsSpendable
							.filter(slotSeed_ => slotSeed_ !== slotSeed),
						budgetRemaining: budgetRemaining + (slotSeed * playerAdjustedSpendMult),
						cntCreaturesAdded: cntCreaturesAdded - 1,
					});
				};

				// Try "random spend first", as it produces more interesting results
				const cntToAddUnusedShuffle = recurseFillSlots({
					operations: [],
					cpySlotSeedsSpendable: [...slotSeedsSpendable].shuffle(),
					budgetRemaining: this._budgetMax - getBudgetSpent(),
					cntCreaturesAdded: 0,
				});
				if (!cntToAddUnusedShuffle && getBudgetSpent() >= this._budgetMin) return [slots];

				// If we couldn't find an encounter with "random spend first", reset, and use "largest spend first"
				slots.forEach(slot => slot.count = 1);

				recurseFillSlots({
					operations: [],
					cpySlotSeedsSpendable: [...slotSeedsSpendable],
					budgetRemaining: this._budgetMax - getBudgetSpent(),
					cntCreaturesAdded: 0,
				});

				return [slots];
			});
	}
}

class EncounterbuilderAdjusterTemplated extends EncounterBuilderAdjusterBase {
	/**
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroups
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroupsLocked
	 * @param {Array<EncounterBuilderCreatureGroupBase>} creatureGroupsAdjustable
	 */
	async _pGetAdjustedEncounter_getSolution ({creatureGroups, creatureGroupsLocked, creatureGroupsAdjustable}) {
		const slotSeeds = creatureGroupsAdjustable.map(creatureGroup => creatureGroup.getSpend({budgetMode: this._budgetMode}));

		const templater = new EncounterBuilderTemplaterSeeded({
			partyMeta: this._partyMeta,
			spendKeys: this._cache.getKeys({budgetMode: this._budgetMode}),
			budgetMin: this._budgetMin,
			budgetMax: this._budgetMax,
			budgetMode: this._budgetMode,
			creatureGroupsLocked,
			slotSeeds,
		});

		const templateInfo = templater.getEncounterTemplateInfo();
		if (!templateInfo.templateOptions) return EncounterBuilderOptionalCandidateEncounter.failure({message: templateInfo.message});

		const templateOption = RollerUtil.rollOnArray(templateInfo.templateOptions);

		if (templateOption.length !== creatureGroupsAdjustable.length) throw new Error(`Should never occur!`);

		// The seeded solution is in low-to-high spend order; apply the results to existing creature metas in the same order
		[...creatureGroupsAdjustable]
			.sort((a, b) => SortUtil.ascSort(a.getSpend({budgetMode: this._budgetMode}), b.getSpend({budgetMode: this._budgetMode})))
			.forEach((creatureGroup, i) => {
				creatureGroup.setCount(templateOption[i].count);
			});

		return EncounterBuilderOptionalCandidateEncounter.success({
			candidateEncounter: new EncounterBuilderCandidateEncounter({
				partyMeta: this._partyMeta,
				creatureGroupsLocked,
				creatureGroupsAdjustable,
			}),
		});
	}
}

/**
 * @abstract
 *
 * - Point buy
 * - hit values from save-or-damage calculated as `saveDc - 8 - 4`,
 *     which gives an equivalent chance of a hit vs AC 10/+0 save
 */
class EncounterBuilderTtkBase {
	_approxOutputs;

	constructor ({partyMeta, creatureGroups}) {
		this._partyMeta = partyMeta;
		this._creatureGroups = creatureGroups;
	}

	_getApproxDpt (pcLevel) {
		const approxOutput = this._approxOutputs.map(it => it[pcLevel - 1]);
		return approxOutput.map(it => it.dmg * ((it.hit + 10.5) / 20)).mean(); // 10.5 = average d20
	}

	getApproxTurnsToKill () {
		const playerMetas = this._partyMeta?.levelMetas;
		if (!playerMetas?.length) return 0;

		const totalDpt = playerMetas
			.map(playerMeta => this._getApproxDpt(playerMeta.level) * playerMeta.count)
			.sum();

		const totalHp = this._creatureGroups
			.map(creatureGroup => {
				const approxHp = creatureGroup.getApproxHp();
				const approxAc = creatureGroup.getApproxAc();

				if (approxHp == null || approxAc == null) return 0;

				return (approxHp * (approxAc / 10)) * creatureGroup.getCount();
			})
			.sum();

		return totalHp / totalDpt;
	}
}

