class EncounterBuilderPartyCustom extends EncounterBuilderPartyBase {
	static PARTY_ID = "custom";

	partyId = this.constructor.PARTY_ID;
	displayName = "Basic";

	/* -------------------------------------------- */

	getPartyPlayerMetas () {
		return this._state.playersSimple
			.map(it => new EncounterPartyPlayerMeta({count: it.entity.count, level: it.entity.level}));
	}

	/* -------------------------------------------- */

	_mutValidateLoadedState (loadedState) {
		const defaultState = this._getDefaultState();

		if (!loadedState.playersSimple?.length) loadedState.playersSimple = MiscUtil.copyFast(defaultState.playersSimple);

		// (Future-proof)
		Object.entries(defaultState)
			.filter(([, v]) => v == null)
			.forEach(([k, v]) => loadedState[k] = v);
	}

	setStateFrom (toLoad, isOverwrite = false) {
		if (toLoad?.state) this._mutValidateLoadedState(toLoad.state);
		return super.setStateFrom(toLoad, isOverwrite);
	}

	/* -------------------------------------------- */

	_doAddPlayer () {
		const prevRowLevel = this._state.playersSimple.at(-1)?.entity?.level;

		this._state.playersSimple = [
			...this._state.playersSimple,
			this.constructor.getDefaultPlayerRow_simple({
				level: prevRowLevel,
			}),
		];
	}

	render ({stgGroup}) {
		const btnAddPlayers = veT`<button class="ve-btn ve-btn-primary ve-btn-xs"><span class="glyphicon glyphicon-plus"></span> Add Players</button>`
			.vee.onn("click", () => this._doAddPlayer());

		const wrpRows = veT`<div class="ve-flex-col ve-w-100"></div>`;

		const stg = veT`<div class="ve-flex-col">
			<div class="ve-flex">
				<div class="ve-w-80p">Players:</div>
				<div class="ve-w-80p">Level:</div>
			</div>

			${wrpRows}

			<div class="ve-mb-1 ve-flex">
				<div class="ecgen__wrp_add_players_btn_wrp">
					${btnAddPlayers}
				</div>
			</div>
		</div>`
			.vee.appendTo(stgGroup);

		const collectionPlayersSimple = new EncounterBuilderRenderableCollectionPlayersSimple({
			comp: this,
			rdState: {
				wrpRowsSimple: wrpRows,
			},
		});

		this._addHookBase("playersSimple", () => collectionPlayersSimple.render())();

		return {
			eles: [stg],
		};
	}

	/* -------------------------------------------- */

	mutDeExternalize ({out}) {
		if (out.playersSimple) {
			out.playersSimple = out.playersSimple
				.map(it => this.constructor.getDefaultPlayerRow_simple(it));
		}
	}

	/* -------------------------------------------- */

	static getDefaultPlayerRow_simple (
		{
			count = 4,
			level = 1,
		} = {},
	) {
		return {
			id: CryptUtil.uid(),
			entity: {
				count,
				level,
			},
		};
	}

	_getDefaultState () {
		return {
			playersSimple: [
				this.constructor.getDefaultPlayerRow_simple(),
			],
		};
	}
}

class EncounterBuilderPartyFvtt extends EncounterBuilderPartyBase {
	static PARTY_ID = "foundryPartySheet";

	partyId = this.constructor.PARTY_ID;
	displayName = "Party Sheet";

	_fnsOnUpdateActorIds = [];
	_fnsCleanup = [];

	/* -------------------------------------------- */

	doRefreshActorIds () {
		if (!this._fnsOnUpdateActorIds.length) return;

		const actorIds = this._getGroupActorIds();
		this._fnsOnUpdateActorIds
			.forEach(fn => fn(actorIds));
	}

	setGroupActorId (actorId) {
		this.doRefreshActorIds();
		this._state.groupActorId = actorId;
	}

	/* -------------------------------------------- */

	_getGroupActorIds () {
		return game.actors
			.filter(act => act.type === "group")
			.map(act => act.id);
	}

	/* -------------------------------------------- */

	getPartyPlayerMetas () {
		const actor = game.actors.get(this._state.groupActorId);
		if (!actor) return [];

		const actorsPlayerCharacters = actor.system?.playerCharacters;
		if (!actorsPlayerCharacters?.length) return [];

		const cnts = {};

		actorsPlayerCharacters
			.forEach(actor => {
				const lvl = actor.system?.details?.level || 0;
				if (!lvl) return;
				cnts[lvl] = (cnts[lvl] ?? 0) + 1;
			});

		return Object.entries(cnts)
			.map(([lvlRaw, cnt]) => new EncounterPartyPlayerMeta({count: cnt, level: Number(lvlRaw)}));
	}

	/* -------------------------------------------- */

	_mutValidateLoadedState (loadedState) {
		const defaultState = this._getDefaultState();

		if (!game.actors.get(loadedState.groupActorId)) loadedState.groupActorId = defaultState.groupActorId;

		// (Future-proof)
		Object.entries(defaultState)
			.filter(([, v]) => v == null)
			.forEach(([k, v]) => loadedState[k] = v);
	}

	setStateFrom (toLoad, isOverwrite = false) {
		if (toLoad?.state) this._mutValidateLoadedState(toLoad.state);
		return super.setStateFrom(toLoad, isOverwrite);
	}

	/* -------------------------------------------- */

	render ({stgGroup}) {
		const {
			wrp: wrpSelActorId,
			setValues: setValuesActorIds,
		} = ComponentUiUtil.getSelSearchable(this, "groupActorId", {
			values: this._getGroupActorIds(),
			fnDisplay: actorId => game.actors.get(actorId)?.name || "(Unknown)",
			isAllowNull: true,
			asMeta: true,
		});
		this._fnsOnUpdateActorIds.push(actorIds => setValuesActorIds(actorIds));

		const btnRefresh = veT`<button class="ve-btn ve-btn-xs ve-btn-default" title="Refresh Selection"><i class="fa fa-rotate-left ve-mr-0"></i></button>`
			.vee.onn("click", () => {
				this.doRefreshActorIds();
				this._state.pulseGroupActorUpdate = !this._state.pulseGroupActorUpdate;
			});

		const dispActor = veT`<div class="ve-mt-2 ve-flex-v-center"></div>`;
		this._addHookBase("groupActorId", async () => {
			if (!this._state.groupActorId) return dispActor.vee.empty().vee.toggle(false);

			const actor = game.actors.get(this._state.groupActorId);
			dispActor
				.vee.html(
					this._state.groupActorId
						? `<span class="ve-muted ve-italic ve-mr-1 ve-pt-1">Sheet:</span> ${await UtilJournalEntries.pGetConvertedFoundryLinks(`@UUID[${actor.uuid}]{${actor.name}}`)}`
						: "",
				)
				.vee.toggle(!!this._state.groupActorId);
		})();

		this._fnsCleanup.push((() => {
			const hk = Hooks.on("deleteActor", docHook => {
				if (docHook.id !== this._state.groupActorId) return;

				this._state.groupActorId = null;
			});
			return () => Hooks.off("deleteActor", hk);
		})());

		this._fnsCleanup.push((() => {
			const hk = Hooks.on("createActor", () => this.doRefreshActorIds());
			return () => Hooks.off("createActor", hk);
		})());

		this._fnsCleanup.push((() => {
			const hk = Hooks.on("updateActor", docHook => {
				if (docHook.id !== this._state.groupActorId) return;

				this._state.pulseGroupActorUpdate = !this._state.pulseGroupActorUpdate;
			});
			return () => Hooks.off("updateActor", hk);
		})());

		const stg = veT`<div class="ve-flex-col">
			<h4 class="ve-mb-2 ve-mt-0 ve-flex-v-center">
				<span class="ve-mr-1">Group Actor</span>
				${btnRefresh}
			</h4>
			${wrpSelActorId}
			${dispActor}
		</div>`
			.vee.appendTo(stgGroup);

		return {
			eles: [stg],
		};
	}

	/* -------------------------------------------- */

	doCleanup () {
		this._fnsOnUpdateActorIds
			.splice(0, this._fnsOnUpdateActorIds.length);

		this._fnsCleanup
			.splice(0, this._fnsCleanup.length)
			.forEach(fn => fn());
	}

	/* -------------------------------------------- */

	_getDefaultState () {
		return {
			groupActorId: game.actors.party?.id || null,

			// The superclass "party change" hook is a hookAll, so toggling this
			//   will pulse everything which cares about party state.
			pulseGroupActorUpdate: false,
		};
	}
}

class RenderableCollectionViewerCreatures extends RenderableCollectionGenericRows {
	constructor (
		{
			comp,
			wrpRows,
			rendererWrapped,
		},
	) {
		super(comp, "creatureGroups", wrpRows);
		if (!rendererWrapped) throw new Error(`Missing required "rendererWrapped" option!`);
		this._rendererWrapped = rendererWrapped;
	}

	/* -------------------------------------------- */

	_getWrpRow () {
		return super._getWrpRow()
			.vee.addClass("ve-py-1p")
			.vee.addClass("ve-px-1")
			.vee.addClass("ve-container-inline");
	}

	_populateRow ({comp, wrpRow, entity}) {
		const {wrp: wrpIptCount} = ComponentUiUtil.getIptNumber(comp, "count", 1, {min: 0, decorationRight: "ticker", asMeta: true});
		wrpIptCount
			.vee.addClass("ve-w-50p")
			.vee.addClass("ve-mr-2")
			.vee.addClass("ve-no-shrink");
		comp._addHookBase("count", () => {
			if (comp._state.count > 0) return;
			if (comp._state.isLocked) return comp._state.count = 1;
			this._utils.doDelete({entity});
		});

		const {
			wrpHovs,
			dispCreature,
			stgCr,
			btnShuffle,
			fnCleanup: fnCleanupRowElements,
		} = entity.getRenderedRowElements({
			comp,
			entity,
			encounterBuilderComp: this._comp,
			rendererWrapped: this._rendererWrapped,
		});

		const btnLock = ComponentUiUtil.getBtnBool(
			comp,
			"isLocked",
			{
				html: `<button title="Lock Monster against Randomizing/Adjusting" class="ve-btn ve-btn-default ve-btn-xs"><span class="glyphicon glyphicon-lock"></span></button>`,
			},
		);

		const btnDelete = veT`<button class="ve-btn ve-btn-danger ve-btn-xs" title="Delete"><span class="glyphicon glyphicon-trash"></span></button>`
			.vee.onn("click", () => {
				if (comp._state.isLocked) return;
				this._utils.doDelete({entity});
			});

		comp._addHookBase("isLocked", () => {
			btnShuffle.vee.toggleClass("ve-disabled", comp._state.isLocked);
			btnDelete.vee.toggleClass("ve-disabled", comp._state.isLocked);
		})();

		veT(wrpRow)`
			${wrpIptCount}
			<div class="ve-flex-v-center ve-grow ecgen-viewer__wrp-creature-info">
				<div class="ve-flex-v-center ve-mx-1 ecgen-viewer__wrp-row-hovers">
					${wrpHovs}
				</div>
				${dispCreature}
			</div>
			${stgCr}
			<div class="ve-btn-group ve-no-wrap ve-no-shrink ve-flex-v-center">
				${btnShuffle}
				${btnLock}
				${btnDelete}
			</div>
		`;

		return {
			fnCleanup: () => {
				if (fnCleanupRowElements) fnCleanupRowElements();
			},
		};
	}

	/* -------------------------------------------- */

	doDeleteExistingRender (renderedMeta) {
		renderedMeta.fnCleanup();
	}
}

