class EncounterBuilderUiFvtt extends EncounterBuilderUi {
	constructor ({...rest}) {
		super({...rest});
		TabUiUtil.decorate(this, {isInitMeta: true});

		this._folderPathBuilderStateManager = _EncounterBuilderUiFvttUtils.getFolderPathBuilderStateManager();
	}

	async pInit () {
		await this._folderPathBuilderStateManager.pInit();
	}

	/* -------------------------------------------- */

	static _RenderState = class extends super._RenderState {
		folderPathBuilderUi;
	};

	/* -------------------------------------------- */

	static async _pImportCreatureGroup ({taskRunner, importer, creatureGroup, encounterMetas}) {
		encounterMetas.push(
			await creatureGroup.getVttAdapter({isRequired: true})
				.pImport({taskRunner, importer}),
		);
	}

	static async _pCreateEncounterActor ({encounterActorFolderNames, taskRunner, creatureGroups, encounterMetas, encounterActorName}) {
		const folderIdMeta = await UtilFolderPathBuilder.pGetCreateFolderIdMeta({
			folderType: "Actor",
			folderNames: encounterActorFolderNames,
		});

		const taskRunnerLineMeta = taskRunner.addLogLine(`Creating encounter &quot;<i>${encounterActorName.qq()}</i>&quot;...`);
		const actorEncounter = await UtilDocuments.pCreateDocument(
			Actor,
			{
				name: encounterActorName,
				img: await new EncounterGeneratorImgFinder().pGetEncounterActorImg({creatureGroups, taskRunner}),
				type: "encounter",
				system: {
					members: encounterMetas
						.map(({actorUuid, count}) => ({
							uuid: actorUuid,
							quantity: {
								value: count,
							},
						})),
				},
				...(folderIdMeta.folderId ? {folder: folderIdMeta.folderId} : {}),
			},
		);
		taskRunner.addLogLine(`Created encounter &quot;<i>${actorEncounter.name.qq()}</i>&quot;.`, {linkedLogLineMeta: taskRunnerLineMeta});

		return actorEncounter;
	}

	static async _pGetDefaultEncounterActorFolderNames () {
		const folderPathBuilderStateManager = _EncounterBuilderUiFvttUtils.getFolderPathBuilderStateManager();
		await folderPathBuilderStateManager.pInit();

		return UtilFolderPathBuilder.getFolderPathStrings({folderPathSpec: folderPathBuilderStateManager.getFolderPathSpec()});
	}

	static async pImportEncounterRivet (
		{
			creatureMetasSerial,
			encounterActorName = null,
		},
	) {
		if (!creatureMetasSerial?.length) return;

		const creatureGroups = creatureMetasSerial
			.map(({count, creature}) => (
				new EncounterBuilderCreatureGroupEntityCreature({
					creature,
					count,
				})
			));

		return this.pImportEncounter({
			creatureGroups,
			encounterActorName,
		});
	}

	static async pImportEncounter (
		{
			creatureGroups,
			encounterActorName = null,
			encounterActorFolderNames = null,
		},
	) {
		if (!creatureGroups?.length) return;

		encounterActorName ||= EncounterGeneratorEncounterNamer.getEncounterName({
			mode: NAMER_MODE_CREATURES,
			creatureGroups,
		});

		encounterActorFolderNames ??= await this._pGetDefaultEncounterActorFolderNames();

		const importer = new ImporterCreature();
		await importer.pInit();

		const encounterMetas = [];

		await (
			new AppTaskRunner({
				tasks: [
					...creatureGroups
						.map(creatureGroup => new TaskClosure({
							fnGetPromise: ({taskRunner}) => this._pImportCreatureGroup({
								taskRunner,
								importer,
								creatureGroup,
								encounterMetas,
							}),
						})),
					new TaskClosure({
						fnGetPromise: ({taskRunner}) => this._pCreateEncounterActor({
							encounterActorFolderNames,
							taskRunner,
							creatureGroups,
							encounterMetas,
							encounterActorName,
						}),
					}),
				],
				titleInitial: "Importing Encounter...",
				titleComplete: "Import Encounter Complete",
				isStopOnError: true,
			})
		).pRun();
	}

	/* -------------------------------------------- */

	_getEncounterActorName () {
		return EncounterGeneratorEncounterNamer.getEncounterName({
			mode: this._state.encounterNameMode,
			creatureGroups: this._comp.creatureGroups,
			partyMeta: this._state.encounterNameMode === NAMER_MODE_PARTY
				? this._getActiveRulesComp().getEncounterPartyMeta()
				: null,
			customName: this._state.encounterName,
		});
	}

	_getBtnImport ({rdState}) {
		return veT`<button class="ve-btn ve-btn-primary ve-w-100 ve-mr-2">Import</button>`
			.vee.onn("click", async () => {
				await this.constructor.pImportEncounter({
					creatureGroups: this._comp.creatureGroups,
					encounterActorName: this._getEncounterActorName(),
					encounterActorFolderNames: rdState.folderPathBuilderUi.getFolderPathStrings(),
				});
			});
	}

	_getBtnOpenConfig () {
		return veT`<button class="ve-btn ve-btn-5et ve-btn-default" title="Open ${Config.get("ui", "isStreamerMode") ? "" : "Plutonium "}Config for the Encounter Builder"><span class="fas fa-fw fa-gears"></span></button>`
			.vee.onn("click", evt => Config.pOpen({evt, initialVisibleGroup: "encounterBuilder"}));
	}

	_getBtnOpenCreatureImporterFolderPath () {
		return veT`<button class="ve-btn ve-btn-5et ve-btn-default ve-btn-xs"><span class="fas fa-fw fa-sitemap ve-mr-1"></span> Edit Folder Path</button>`
			.vee.onn("click", async () => {
				const importer = new ImporterCreature();
				await importer.pInit();

				await FolderPathBuilderApp.pHandleEditFolderPathClick({
					folderPathBuilderStateManager: await importer.getFolderPathBuilderStateManager(),
					folderType: "Actor",
					isTextOnly: true,
				});
			});
	}

	_render_footer ({rdState, stgFooter}) {
		rdState.folderPathBuilderUi = new FolderPathBuilderUi({
			folderPathBuilderStateManager: this._folderPathBuilderStateManager,
			folderType: "Actor",
			isTextOnly: true,
		});

		const btnImport = this._getBtnImport({rdState});
		const btnOpenConfig = this._getBtnOpenConfig();
		const btnOpenCreatureImporterFolderPath = this._getBtnOpenCreatureImporterFolderPath();

		const iptName = ComponentUiUtil.getIptStr(this, "encounterName", {placeholder: "Encounter Name"})
			.vee.addClass("ve-w-100");

		const dispAutoName = veT`<div class="ve-w-100 ve-h-22p ve-muted ve-text-right ve-overflow-x-hidden ve-overflow-ellipsis ecgen-foundry__disp-name-generated"></div>`;

		const selNameMode = ComponentUiUtil.getSelEnum(
			this,
			"encounterNameMode",
			{
				values: NAMER_MODES,
				fnDisplay: mode => NAMER_MODE_TO_DISPLAY[mode],
			},
		)
			.vee.addClass("ve-w-100");

		const hkName = () => {
			const isCustomName = this._state.encounterNameMode === NAMER_MODE_CUSTOM;

			iptName.vee.toggle(isCustomName);
			dispAutoName
				.vee.toggle(!isCustomName);

			if (isCustomName) return;
			const autoName = this._getEncounterActorName();
			dispAutoName
				.vee.tooltip(autoName)
				.vee.txt(autoName);
		};

		this._addHookBase("activeRulesId", hkName);
		this._addHookBase("activePartyId", hkName);
		this._addHookBase("encounterNameMode", hkName);
		this._comp.addHookCreatureGroups(hkName);
		this._comp.addHookPulseDeriverPartyMeta(hkName);
		hkName();

		const stgFolderPath = veT`<div class="ve-flex-col ve-w-100"></div>`;
		rdState.folderPathBuilderUi.render(stgFolderPath);

		const stgSettingsTabs = veT`<div class="ve-flex-col ve-w-100 ve-mb-2"></div>`;
		const [tabFolderSettings, tabCreatureImporterSettings] = this._renderTabs(
			[
				new TabUiUtil.TabMeta({name: "Actor/Folder Settings", hasBorder: true}),
				new TabUiUtil.TabMeta({name: "Creature Importer Settings", hasBorder: true}),
			],
			{
				eleParent: stgSettingsTabs,
			},
		);

		veT(tabFolderSettings.wrpTab)`
			<div class="ve-flex-col ve-w-100 ve-pt-2">
				<label class="ve-flex-v-center ve-mb-2">
					<div class="ve-no-shrink ve-mr-2 ve-w-140p ve-text-right">Encounter Name Mode:</div>
					${selNameMode}
				</label>

				<label class="ve-flex-v-center">
					<div class="ve-no-shrink ve-mr-2 ve-w-140p ve-text-right">Encounter Name:</div>
					${iptName}
					${dispAutoName}
				</label>

				<hr class="ve-hr-2">

				${stgFolderPath}
			</div>
		`;

		veT(tabCreatureImporterSettings.wrpTab)`
			<div class="ve-flex-col ve-w-100 ve-pt-2">
				<div class="ve-split-v-center">
					<div>Folder Path</div>
					${btnOpenCreatureImporterFolderPath}
				</div>
			</div>
		`;

		veT(stgFooter)`
			<hr class="ve-hr-2 ve-hr--heavy">

			${stgSettingsTabs}

			<hr class="ve-hr-2 ve-mt-auto">

			<div class="ve-w-100 ve-flex-v-center">
				${btnImport}
				${btnOpenConfig}
			</div>
		`;
	}

	/* -------------------------------------------- */

	_getDefaultState () {
		return {
			...super._getDefaultState(),
			encounterName: "Encounter",
			encounterNameMode: NAMER_MODE_PARTY,
		};
	}
}

