class EncounterBuilderCreatureGroupFoundryActor extends EncounterBuilderCreatureGroupBase {
	static TYPE = "foundryActor";
	static _ = EncounterBuilderCreatureGroupRegistry.register({Cls: this});

	constructor (
		{
			id,

			uuid,
			count,

			isLocked = false,
		},
	) {
		super({
			id,

			count,
			uuid,
			isLocked,
		});
	}

	/* -------------------------------------------- */

	getUuid () { return this.entity.uuid; }

	/* -------------------------------------------- */

	getActor () {
		return fromUuidSync(this.entity.uuid);
	}

	/* -------------------------------------------- */

	getCrNumber () {
		const cr = this.getActor().system?.details?.cr;
		if (cr == null) return null;
		if (typeof cr !== "number") {
			console.warn(...LGTD, `Actor CR was not a number for UUID "${this.entity.uuid}" (was ${JSON.stringify(cr)})`);
			return null;
		}
		return cr;
	}

	getXp () {
		const xp = this.getActor().system?.details?.xp?.value;
		if (xp != null && !isNaN(xp)) {
			if (typeof xp !== "number") {
				console.warn(...LGTD, `Actor XP was not a number for UUID "${this.entity.uuid}" (was ${JSON.stringify(xp)})`);
				return null;
			}
			return xp;
		}

		const crNumber = this.getCrNumber();
		if (crNumber == null) return null;

		return Parser.crToXpNumber(Parser.numberToCr(crNumber));
	}

	getApproxHp () {
		const hp = this.getActor().system?.attributes?.hp;
		if (!hp) return null;

		if (hp.max != null && !isNaN(hp.max)) return Number(hp.max);
		if (hp.value != null && !isNaN(hp.value)) return Number(hp.value);

		return null;
	}

	getApproxAc () {
		const acValue = this.getActor().system?.attributes?.ac?.value;
		return acValue != null && !isNaN(acValue) ? Number(acValue) : null;
	}

	getDisplayName () { return this.getActor().name || this.entity.uuid; }

	isSameCreatureGroup (other) {
		if (this.type !== other?.type) return false;
		return this.entity.uuid === other.getUuid();
	}

	/* -------------------------------------------- */

	getRenderedRowElements (
		{
			entity,
			encounterBuilderComp,
		},
	) {
		const dispCreature = veT`<div class="ve-mr-2 ve-mr-auto ve-grow"></div>`;

		UtilJournalEntries.pGetConvertedFoundryLinks(`@UUID[${this.entity.uuid}]`)
			.then(html => dispCreature.vee.html(html));

		const crNumber = this.getCrNumber();
		const crText = crNumber == null ? "?" : Parser.numberToCr(crNumber);

		const stgCr = veT`<div class="ve-mr-2 ve-no-wrap ve-no-shrink ve-flex-v-center">
			<span class="ve-mr-2">CR</span>
			<div class="ve-text-center ve-form-control form-control--minimal ve-input-xs ve-w-50p ve-flex-vh-center ve-bold">${crText}</div>
			<div class="ve-w-24p"></div>
		</div>`;

		return {
			wrpHovs: [
				this._getWrpHoverOuter(),
				this._getWrpHoverOuter(),
				this._getWrpHoverOuter()
					.vee.html(`<img src="icons/anvil.png" class="ecgen-foundry__img-foundry-actor" title="This is a Foundry actor, already present in this world. Some features are therefore unavailable. Note: Foundry actor drop behaviour is controlled by the &quot;Convert Actors On Drop&quot; Config option.">`),
			],
			dispCreature,
			stgCr,
			btnShuffle: this._getRenderedRowElements_getBtnShuffle({encounterBuilderComp, creatureGroup: entity}),
		};
	}
}

class ModalFilterBestiaryEncounterBuilder extends ModalFilterBestiary {
	constructor ({comp, cache}) {
		super({
			namespace: "EncounterGeneratorApp_modalFilterBestiary",
		});
		this._comp = comp;
		this._cache = cache;
		this._pageFilter = new PageFilterBestiaryFvttEncounterBuilder();
	}

	_getColumnHeaders () {
		const btnMeta = [
			{sort: "name", text: "Name", width: "5"},
			{sort: "type", text: "Type", width: "3-5"},
			{sort: "cr", text: "CR", width: "1"},
			{sort: "source", text: "Source", width: "1"},
			{text: "\u00A0", width: "1", disabled: true},
		];
		return ModalFilterBase._getFilterColumnHeaders(btnMeta);
	}

	_getWrpList () {
		return super._getWrpList()
			.vee.addClass("veapp__list-modal-scroll-offset");
	}

	async _pLoadAllData () { return []; }

	_getListItem (pageFilter, mon, itI) {
		Renderer.monster.initParsed(mon);
		pageFilter.mutateAndAddToFilters(mon);

		const eleRow = document.createElement("div");
		eleRow.className = "ve-px-0 ve-w-100 ve-flex-col ve-no-shrink";

		const hash = UrlUtil.URL_TO_HASH_BUILDER[UrlUtil.PG_BESTIARY](mon);
		const source = Parser.sourceJsonToAbv(mon.source);
		const type = mon._pTypes.asText;
		const cr = mon._pCr;

		eleRow.innerHTML = `<div class="ve-w-100 ve-flex-v-center ve-lst__row-border veapp__list-row ve-no-select">
			<div class="ve-col-0-5 ve-pl-0 ve-pr-1 ve-flex-vh-center">
				<div class="ve-ui-list__btn-inline ve-px-2 ve-no-select" title="Toggle Preview (SHIFT to Toggle Info Preview)">[+]</div>
			</div>

			<div class="ve-col-5 ve-px-1 ${mon._versionBase_isVersion ? "ve-italic" : ""}">${mon._versionBase_isVersion ? `<span class="ve-px-3"></span>` : ""}${mon.name}</div>
			<div class="ve-col-3-5 ve-px-1">${type}</div>
			<div class="ve-col-1 ve-px-1 ve-text-center">${cr}</div>
			<div class="ve-col-1 ve-flex-h-center ${Parser.sourceJsonToSourceClassname(mon.source)} ve-pl-1 ve-pr-0" title="${Parser.sourceJsonToFull(mon.source)}">${source}${Parser.sourceJsonToMarkerHtml(mon.source, {isList: true})}</div>
			<div class="ve-col-1 ve-flex-vh-center ve-btn-group ve-py-1p ">
				<button class="ve-btn ve-btn-5et ve-btn-xxs ve-btn-default" title="Add Creature (SHIFT to add 5)"><span class="glyphicon glyphicon-plus ve-ml-1p ve-top-2p"></span></button>
				<button class="ve-btn ve-btn-5et ve-btn-xxs ve-btn-default" title="Remove Creature (SHIFT to remove 5)"><span class="glyphicon glyphicon-minus ve-top-2p"></span></button>
			</div>
		</div>`;

		const btnShowHidePreview = eleRow.firstElementChild.firstElementChild.firstElementChild;

		const listItem = new ListItem({
			id: itI,
			ele: eleRow,
			name: mon.name,
			values: {
				source,
				sourceJson: mon.source,
				...ListItem.getCommonValues(mon),
				type,
				cr,
			},
			data: {
				hash,
				btnAdd: eleRow.firstElementChild.lastElementChild.firstElementChild,
				btnSubtract: eleRow.firstElementChild.lastElementChild.lastElementChild,
				btnShowHidePreview,
			},
		});

		this._previewButtonHandler.bindPreviewButton({entity: mon, listItem, btnShowHidePreview});

		return listItem;
	}

	setDataList (monsterDatas) {
		this._list.removeAllItems();
		this._allData = monsterDatas || [];

		this._allData.forEach((mon, i) => {
			this._pageFilter.mutateAndAddToFilters(mon);

			const filterListItem = this._getListItem(this._pageFilter, mon, i);
			this._list.addItem(filterListItem);

			const onClickAdd = evt => {
				evt.preventDefault();
				evt.stopPropagation();

				this._comp.doAddCreatureGroup({
					creatureGroup: new EncounterBuilderCreatureGroupEntityCreature({
						creature: mon,
						count: evt.shiftKey ? 5 : 1,
					}),
				});
			};

			const onClickSubtract = evt => {
				evt.preventDefault();
				evt.stopPropagation();

				this._comp.doSubtractCreatureGroup({
					creatureGroup: new EncounterBuilderCreatureGroupEntityCreature({
						creature: mon,
						count: evt.shiftKey ? 5 : 1,
					}),
					quantity: evt.shiftKey ? 5 : 1,
				});
			};

			veE({ele: filterListItem.ele})
				.vee.onn("click", evt => onClickAdd(evt))
				.vee.onn("contextmenu", evt => onClickSubtract(evt));

			veE({ele: filterListItem.data.btnAdd})
				.vee.onn("click", evt => onClickAdd(evt))
				.vee.onn("contextmenu", evt => onClickSubtract(evt));

			veE({ele: filterListItem.data.btnSubtract})
				.vee.onn("click", evt => onClickSubtract(evt))
				.vee.onn("contextmenu", evt => onClickAdd(evt));
		});

		this._pageFilter.filterBox.render();
		this._list.update();
		this._handleFilterChange();
	}

	_handleFilterChange () {
		super._handleFilterChange();
		this._cache.reset();
		this._cache.setCreatures(this.getEntitiesMatchingFilterExpression());
	}
}

/**
 * @abstract
 */
class _EncounterBuilderCreatureGroupVttAdapterBase {
	constructor ({creatureGroup}) {
		this._creatureGroup = creatureGroup;
	}

	/**
	 * @abstract
	 * @returns {boolean}
	 */
	isValid () { throw new Error(`Unimplemented!`); }

	/**
	 * @abstract
	 * @returns {Promise<object>}
	 */
	async pImport ({taskRunner, importer}) { throw new Error(`Unimplemented!`); }

	/**
	 * @abstract
	 * @returns {Promise<?string>}
	 */
	async pGetEncounterActorImg ({taskRunner}) { throw new Error(`Unimplemented!`); }
}

class EncounterBuilderCreatureGroupVttAdapterEntityCreature extends _EncounterBuilderCreatureGroupVttAdapterBase {
	isValid () { return true; }

	async pImport ({taskRunner, importer}) {
		const creature = this._creatureGroup.getCreature();

		const importSummary = await importer.pImportEntry(
			creature,
			new ImportOpts({taskRunner}),
		);
		if (!importSummary.getPrimaryDocument()) throw new Error(`Creature import failed for "${UrlUtil.URL_TO_HASH_BUILDER[UrlUtil.PG_BESTIARY](creature)}"!`);

		return {
			actorUuid: importSummary.getPrimaryDocument().uuid,
			count: this._creatureGroup.getCount(),
		};
	}

	async pGetEncounterActorImg ({taskRunner}) {
		const tokenInfo = await TokenFetcherCreature.pGetTokenInfo(this._creatureGroup.getCreature(), {taskRunner});
		return tokenInfo.isFallback ? null : tokenInfo.img;
	}
}

class EncounterBuilderCreatureGroupVttAdapterFoundryActor extends _EncounterBuilderCreatureGroupVttAdapterBase {
	isValid () { return !!this._creatureGroup.getActor(); }

	async pImport ({taskRunner}) {
		taskRunner.addLogLine(`Linked existing actor &quot;<i>${this._creatureGroup.getDisplayName().qq()}</i>&quot;.`);

		return {
			actorUuid: this._creatureGroup.getUuid(),
			count: this._creatureGroup.getCount(),
		};
	}

	async pGetEncounterActorImg ({taskRunner}) {
		const tokenImg = this._creatureGroup.getActor()?.prototypeToken?.texture?.src;

		if (!tokenImg) return null;
		if (UtilImage.isDefaultActorImage(tokenImg)) return null;
		return tokenImg;
	}
}

const {HandlebarsApplicationMixin: HandlebarsApplicationMixin$a, ApplicationV2: ApplicationV2$a} = foundry.applications.api;

const _STORAGE_KEY_STATE_COMP = "encounterGeneratorCompState";
