class EncounterGeneratorSourceSelector extends AppSourceSelectorMulti {
	static prePreInit () {
		this._prePreInit_registerKeybinds();
	}

	static _prePreInit_registerKeybinds () {
		game.keybindings.register(
			SharedConsts.MODULE_ID,
			"EncounterGeneratorSourceSelector__open",
			{
				name: "Open Encounter Builder",
				editable: [],
				onDown: () => {
					this._pOpen().then(null);
					return true;
				},
				restricted: true,
			},
		);
	}

	static async pHandleButtonClick () {
		return this._pOpen();
	}

	static async _pOpen () {
		const appSourceSelector = new EncounterGeneratorSourceSelector({
			title: `Encounter Builder: Select Sources`,
			filterNamespace: `EncounterGeneratorSourceSelector_filter`,
			savedSelectionKey: `EncounterGeneratorSourceSelector_savedSelection`,
			pipelinesToDisplay: await DataPipelinesListCreature.pGetPipelines(),
		});

		const loadedData = await appSourceSelector.pWaitForUserInput();
		if (loadedData == null) return;

		const mergedData = UtilDataSource.getMergedData([loadedData]);

		const app = new EncounterGeneratorApp({
			data: mergedData,
		});
		app.render(true);
	}
}

