class TableResultCleaner extends DocumentEmbeddedDocumentCleaner {
	constructor (table) {
		super({
			title: "Row Cleaner",
			doc: table,
			embedType: "TableResult",
			embedProp: "results",
			displayName: "row",
			displayNamePlural: "rows",
			namespace: `tool-table-result-cleaner`,
		});
	}

	static _sortEntities (a, b, opts) {
		return opts.sortBy === "name"
			? (SortUtil.ascSort(a.rangeLow, b.rangeLow) || super._sortEntities(a, b, opts))
			: super._sortEntities(a, b, opts);
	}

	_prepareContext_getRow (doc, ix) {
		const out = super._prepareContext_getRow(doc, ix);
		out.rangeLow = Math.min(...(doc.range || []));
		if (out.rangeLow === Infinity) out.rangeLow = Number.MIN_SAFE_INTEGER;
		return out;
	}

	_prepareContext_getEmbeddedDocName (doc) {
		return [
			(doc.range || []).filter(it => it != null).join("\u2012"),
			doc.name,
		]
			.filter(Boolean)
			.join(" ");
	}

	_prepareContext_getEmbeddedDocType (doc) {
		switch (doc.type) {
			case CONST.TABLE_RESULT_TYPES.TEXT: return `Text`;
			case CONST.TABLE_RESULT_TYPES.DOCUMENT: return `Document`;
			default: throw new Error(`Unhandled table result type "${doc.type}"`);
		}
	}
}

