class Patcher_CanvasAnimation {
	static init () {
		UtilLibWrapper.addPatch(
			"foundry.canvas.placeables.Token.prototype.animate",
			this._lw_Token_prototype_animate,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
		);
	}

	/**
	 * @see {TokenAnimationOptions}
	 */
	static _lw_Token_prototype_animate (fn, updateData, opts, ...otherArgs) {
		const mult = Config.get("tokens", "animationSpeedMultiplier");
		if (mult == null) return fn(updateData, opts, ...otherArgs);

		opts = {...opts || {}};
		if (opts.movementSpeed == null) opts.movementSpeed = CONFIG.Token.movement.defaultSpeed;
		opts.movementSpeed *= mult;

		return fn(updateData, opts, ...otherArgs);
	}
}

// TODO(v15) review

/* eslint-disable vet-jquery/jquery */
class Patcher_Jquery {
	static init () {
		UtilLibWrapper.addPatch(
			"$.prototype.animate",
			this._lw_$_prototype_animate,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
		);
	}

	static _lw_$_prototype_animate (fn, ...args) {
		return fn(...Patcher_Jquery._getNextArgs(...args));
	}

	static _getNextArgs (...args) {
		let nxtArgs = [...args];

		if (Config.get("ui", "isFastAnimations")) {
			for (let i = 0; i < nxtArgs.length; ++i) {
				const arg = nxtArgs[i];

				// This mysteriously breaks when going to lower numbers
				//   Therefore, limit it to "numbers above 33," in case lower numbers have special meaning
				//   It may be that there exists a race condition between this and e.g. saving sheet state,
				//   which would explain things like "opening a token sheet, closing it, then updating the health of
				//   the token causes the sheet to re-open" existing.
				if (typeof arg === "object" && arg.duration != null) {
					if (arg.duration > 33) arg.duration = 33;
					break;
				} else if (typeof arg === "number") {
					if (arg > 33) nxtArgs[i] = 33;
					break;
				}
			}
		}

		return nxtArgs;
	}
}
/* eslint-enable vet-jquery/jquery */

class IntegrationSimpleCalendar {
	static isSimpleCalendarApp (app) {
		let ele = app.element;
		if (!ele) return false;

		// eslint-disable-next-line vet-jquery/jquery
		if (ele instanceof $) ele = ele[0];

		// Since Simple Calendar has a very generic application name, try to figure out which app it is by CSS
		return ele.classList.contains("simple-calendar") && ele.classList.contains("window-app");
	}

	static isPersistentOpen () {
		return !!UtilGameSettings.getSafe(UtilCompat.MODULE_SIMPLE_CALENDAR, "persistent-open");
	}
}

