/**
 * Note: this "page" version does not persist between closes/page changes, due to the way Foundry's Journal Entry sheet
 * renders pages--it does so by rendering the page and scooping out the HTML, which breaks our iframe.
 *
 * Example video URL: https://www.youtube.com/embed/dQw4w9WgXcQ
 */
class JournalUrlPageSheet extends JournalEntryPageHandlebarsSheet {
	static EDIT_PARTS = {
		header: super.EDIT_PARTS.header,
		content: {
			template: `${SharedConsts.MODULE_LOCATION}/mod-template/journal/page-url-edit.hbs`,
			root: true,
		},
		footer: super.EDIT_PARTS.footer,
	};

	static VIEW_PARTS = {
		content: {
			template: `${SharedConsts.MODULE_LOCATION}/mod-template/journal/page-url-view.hbs`,
			root: true,
		},
	};

	_cached_element = null;
	_cached_elementRemoveAttribute = null;

	_onRender () {
		if (this._cached_element && this.element === this._cached_element) return;

		this._cached_element = this.element;
		const cached = this._cached_elementRemoveAttribute = this.element.removeAttribute.bind(this.element);

		// Override hack, as Foundry strips the `class` attribute from pages :^)
		this.element.removeAttribute = (attr, ...rest) => {
			const res = cached(attr, ...rest);
			if (attr !== "class") return res;
			this.element.classList.add("ve-h-100");
			this.element.classList.add("ve-flex-col");
			// Timing hack, otherwise can't set class on parent element
			setTimeout(() => {
				if (!this.element.parentElement) return;
				this.element.parentElement.classList.add("ve-h-100");
				this.element.parentElement.classList.add("ve-flex-col");
			}, 50);
			return res;
		};
	}
}

// Wrap particular calls to get items from UUID in context to avoid the following:
// - A spell's item data is being `prepare`d on a synthetic `ActorDelta` -- i.e., an unlinked token
// - The spell lacks a usable `compendiumSource`, so D&D5e uses its token-embedded UUID
// - Plutonium calls `fromUuidSync` on that UUID.
// - Resolving it requires Foundry to construct the same synthetic actor again -> spell `getRollData` is called -> loop
//
// Instead, we check if the incoming spell UUID is the same as the last generated spell roll data, and if so, just return
//   the spell we already have.
class Patcher_Item_GetRollDataContext {
	static _ITEM_STACK = [];

	static run ({item, fn}) {
		this._ITEM_STACK.push(item);

		try {
			return fn();
		} finally {
			this._ITEM_STACK.pop();
		}
	}

	static getActiveItem ({uuid} = {}) {
		const item = this._ITEM_STACK.at(-1);

		if (!item) return null;
		if (uuid == null) return item;

		// Match D&D5e's spell-list lookup, which prefers the original compendium UUID
		const itemUuid = item._stats?.compendiumSource ?? item.uuid;
		return itemUuid === uuid ? item : null;
	}
}

class Patcher_Item {
	static init () {
		this._init_tryPatchGetRollData();
	}

	static _init_tryPatchGetRollData () {
		try {
			UtilLibWrapper.addPatch(
				"CONFIG.Item.documentClass.prototype.getRollData",
				this._lw_CONFIG_Item_documentClass_prototype_getRollData,
				UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
			);
		} catch (e) {
			console.error(...LGT, `Failed to bind getRollData handler!`, e);
		}
	}

	static _lw_CONFIG_Item_documentClass_prototype_getRollData (fn, ...args) {
		return Patcher_Item_GetRollDataContext.run({
			item: this,
			fn: () => {
				const out = fn(...args);
				return Patcher_Item._getRollData(this, out);
			},
		});
	}

	static _getRollData (item, rollData) {
		if (!rollData) return rollData;
		Patcher_RollData.addAdditionalRollDataBase(rollData, item);
		return rollData;
	}
}

