		if (UtilGameSettings.getSafe(SharedConsts.SYSTEM_ID_DND5E, "disableAdvancements")) return pFn(...args);

		const [, items] = args;

		if (!items?.some(itm => Dnd5eAdvancementSuppressor.isSuppressableItem(itm))) return pFn(...args);

		return Dnd5eAdvancementSuppressor.pWithSuppression(pFn, args);
