/** Based on Quick Insert's `SearchItem` */
class PlutoniumSearchItem {
	constructor (
		{
			id,
			name,
			hash,
			page,
			source,
			tag,
			uid,
			img,
			extras,
			ClsImportList,
		},
	) {
		this.id = `${id}`.padStart(16, "0");

		this._id = id;
		this._uid = uid;
		this._name = name;
		this._hash = hash;
		this._page = page;
		this._source = source;
		this._tag = tag;
		this._img = img;
		this._extras = extras;
		this._ClsImportList = ClsImportList;
		this._documentType = ClsImportList.FOLDER_TYPE;
	}

	// TODO(Future) remove if/when Quick Insert gates the row `content-link` class behind something else
	get __source () { return "quick-insert"; }

	get name () { return this._name; }
	get documentType () { return this._documentType; }
	get uuid () { return `@${this._tag}[${this._uid}|${this._name}]`; }
	get img () { return this._img; }
	get page () { return this._page; }
	get source () { return this._source; }
	get ClsImportList () { return this._ClsImportList; }

	/**
	 * Used by Quick Insert, but unavailable in Plutonium index.
	 * Approximate by tag.
	 */
	get subType () {
		switch (this._documentType) {
			case "Actor": return this._getSubType_actor();
			case "Item": return this._getSubType_item();
			default: return null;
		}
	}

	_getSubType_actor () {
		switch (this._tag) {
			case "vehicle":
				return "vehicle";

			case "creature":
			case "trap":
				return "npc";
		}

		return null;
	}

	_getSubType_item () {
		if (this._extras?.foundryType) return this._extras.foundryType;

		switch (this._tag) {
			case "spell": return "spell";

			case "race": return "race";

			case "background": return "background";

			case "feat":
			case "classFeature":
			case "subclassFeature":
			case "optfeature":
				return "feat";

			case "item":
				// Use "equipment" as a generic fallback
				return "equipment";

			case "class": {
				if (Hist.util.getHashParts(this._hash).length > 1) return "subclass";
				return "class";
			}
		}

		return null;
	}

	/**
	 * Used by Quick Insert, but unavailable in Plutonium index.
	 */
	get system () {
		if (!this._extras) return null;

		if (this._tag === "spell") {
			return {
				level: this._extras.level ?? 999,
			};
		}

		return {};
	}

	/* -------------------------------------------- */

	serialize () {
		return {
			id: this._id,
			name: this._name,
			hash: this._hash,
			page: this._page,
			source: this._source,
			tag: this._tag,
			uid: this._uid,
			img: this._img,
		};
	}

	static deserialize (json) {
		const {ClsImportList} = ChooseImporter.getImporterClassMeta(json.tag);
		return new this({
			...json,
			ClsImportList,
		});
	}

	/* -------------------------------------------- */

	get dragData () {
		return {
			type: this.documentType,
			subType: UtilEvents.EVT_DATA_SUBTYPE__HOVER,
			page: this._page,
			source: this._source,
			hash: this._hash,
			// Skip the leading `@`, as our content link handler re-adds it
			// Capitalize the first part of the UID (as we assume this to be the name) to better match the Foundry standard
			originalText: `${this._tag}[${this._uid.split("|").map((it, i) => i !== 0 ? it : it.uppercaseFirst()).join("|")}]`,
			uuid: this.uuid,
			tagTag: this._tag,
			tagText: this._uid,
			...ImporterDragDropSuppressor.getDragDataForcePlutoniumImport(),
		};
	}

	get _icon () {
		return CONFIG[this.documentType].sidebarIcon;
	}

	get icon () {
		return `<i class="${this._icon} entity-icon"></i>`;
	}

	get journalLink () {
		return `@${this._tag}[${this._uid}]`;
	}

	get script () {
		return `DataLoader.pCacheAndGet("${this._page}", "${this._source}", "${this._hash}")`;
	}

	get tagline () {
		const ptParen = Config.get("integrationQuickInsert", "isDisplaySource")
			? Parser.sourceJsonToAbv(this._source)
			: Config.get("ui", "isStreamerMode") ? SharedConsts.MODULE_TITLE_FAKE : SharedConsts.MODULE_TITLE;

		return `${this._ClsImportList.DISPLAY_NAME_TYPE_PLURAL} (${ptParen})`;
	}

	async show () {
		(await this.get())?.sheet?.render(true);
	}

	async pImport () {
		const importSummary = await this._pGetImportSummary({isTemp: false});
		if (!importSummary) return;

		importSummary.getPrimaryDocument()?.sheet?.render(true);

		// If we're importing to e.g. an existing sheet, assume the user can see where they've drag-dropped, and don't notify
		if (importSummary.getPrimaryDocument()?.parent) return;

		importSummary.doNotification();
	}

	async _pGetImportSummary ({isTemp = false} = {}) {
		const ent = await DataLoader.pCacheAndGet(this._page, this._source, this._hash);
		if (!ent) {
			console.error(...LGT, `Failed to load "${this._hash}" for page "${this._page}"!`);
			return null;
		}

		const importer = ChooseImporter.getImporter(this._tag) || ChooseImporter.getImporter(this._page);
		await importer.pInit();

		const userOwnership = game.user.isGM ? null : {[game.user.id]: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER};

		return importer.pImportEntry(
			ent,
			new ImportOpts({
				isTemp,
				userOwnership,
				isAddDefaultOwnershipFromConfig: false,
			}),
		);
	}

	async get () {
		return (await this._pGetImportSummary({isTemp: true})).getPrimaryDocument();
	}

	async getPermanent () {
		return (await this._pGetImportSummary({isTemp: false})).getPrimaryDocument();
	}

	get tooltip () {
		const type = game.i18n.localize(CONFIG[this.documentType].typeLabels?.[this.subType])
			|| game.i18n.localize(CONFIG[this.documentType]?.documentClass?.metadata?.label);

		return `${type} - ${this.tagline}`;
	}

	/* -------------------------------------------- */

	getFromFactory (ClsFactory) {
		return ClsFactory.from(this);
	}
}

class UtilIntegrationFauxCompendium {
	static _NO_INDEX_CATS = new Set([
		Parser.CAT_ID_SKILLS,
		Parser.CAT_ID_SENSES,
		Parser.CAT_ID_ADVENTURE,
		Parser.CAT_ID_BOOK,
	]);

	static _P_LOADER = null;

	static pGetPlutoniumIndex () {
		this._P_LOADER = this._P_LOADER || this._pGetPlutoniumIndex();
		return this._P_LOADER;
	}

	static async _pGetPlutoniumIndex () {
		const data = Omnidexer.decompressIndex(await DataUtil.loadJSON(`${Renderer.get().baseUrl}search/index-foundry.json`));

		const out = [];

		let id = 0;

		for (const d of data) {
			if (!d.h) continue; // If the thing is not hoverable, we probably don't want it

			if (this._NO_INDEX_CATS.has(d.c)) continue;

			const page = UrlUtil.categoryToHoverPage(d.c);
			if (!page) continue;

			const importerMeta = ChooseImporter.getImporterClassMeta(d.t);
			if (!importerMeta?.ClsImporter) continue;

			if (await this._isIndexItemBlocklisted(d)) continue;

			const {ClsImportList} = importerMeta;

			const searchItem = new PlutoniumSearchItem({
				// region General index
				id: d.id,
				name: d.n,
				hash: d.u,
				page,
				source: d.s,
				// endregion
				// region Unique to Plutonium
				tag: d.t,
				uid: d.uu,
				img: VetoolsSaverUtils.getEntryImageInternalUrl(d.m, {isSkipEncode: true}),
				extras: FoundryOmnidexerUtils.unpackFoundryExtras(d.xF),
				// endregion
				ClsImportList,
			});
			id = Math.max(d.id, id);

			out.push(searchItem);
		}

		// If World Data Source Selection is in use, load up brew
		if (!UtilWorldDataSourceSelector.isSourceSelectionActive()) return out;

		const pipelines = await DataPipelinesListSearchIndexPrereleaseBrew.pGetPipelines();

		if (UtilDataSource.isTooManySources({cntSources: pipelines.length})) {
			console.log(...LGT, `Skipped loading prerelease/homebrew\u2014too many sources selected! Increase the "Auto-Selected Source Count Warning Threshold" Data Sources Config option, or reduce the number of sources auto-selected by the "Force Select All for ..." Data Sources Config Option.`);
			return out;
		}

		const dataBundle = await (
			new DataPipelinesBundler({
				pipelines,
				isAutoSelectAll: true,
			})
		).pLoad();
		if (!dataBundle) return out;

		for (const [prop, arr] of Object.entries(dataBundle.dedupedAllContentMergedPrimed)) {
			if (!(arr instanceof Array)) continue;

			if (!UrlUtil.URL_TO_HASH_BUILDER[prop]) continue;

			const tag = Parser.getPropTag(prop);
			const importerMeta = ChooseImporter.getImporterClassMeta(tag);
			if (!importerMeta?.ClsImporter) continue;

			const {ClsImportList} = importerMeta;

			const page = Renderer.tag.getPage(tag);
			if (!page) continue;

			for (const ent of arr) {
				if (this._isEntityBlocklisted({prop, ent})) continue;

				out.push(new PlutoniumSearchItem({
					id: ++id,
					name: ent.name,
					hash: UrlUtil.URL_TO_HASH_BUILDER[prop](ent),
					page,
					source: SourceUtil.getEntitySource(ent),

					tag,
					uid: DataUtil.proxy.getUid(prop, ent),
					img: await this._pGetPrereleaseBrewImageUrl({prop, ent}),
					extras: FoundryOmnidexerUtils.unpackFoundryExtras(
						FoundryOmnidexerUtils.getPackedFoundryExtras({prop, ent}),
					),

					ClsImportList,
				}));
			}
		}

		return out;
	}

	static async _isIndexItemBlocklisted (d) {
		const prop = Parser.pageCategoryToProp(d.c);
		if (prop !== "item") {
			return ExcludeUtil.isExcluded(d.u, prop, d.s, {isNoCount: true});
		}

		const item = await DataLoader.pCacheAndGetHash(UrlUtil.PG_ITEMS, d.u);
		return Renderer.item.isExcluded(item, {hash: d.u});
	}

	static _isEntityBlocklisted ({prop, ent}) {
		const hash = UrlUtil.URL_TO_HASH_BUILDER[prop](ent);

		const source = SourceUtil.getEntitySource(ent);
		if (source == null) return false;

		if (prop !== "item") return ExcludeUtil.isExcluded(hash, prop, source, {isNoCount: true});
		return Renderer.item.isExcluded(ent, {hash});
	}

	static async _pGetPrereleaseBrewImageUrl ({prop, ent}) {
		if (await VetoolsTokenAdapter.pHasTokenUrl(prop, ent, {isSilent: true})) return VetoolsTokenAdapter.pGetTokenUrl(prop, ent);

		const fluff = await Renderer.utils.pGetPredefinedFluff(ent, `${prop}Fluff`);
		return VetoolsSaverImagesFromFluff.pGetImageUrlFromFluff(fluff);
	}

	/* -------------------------------------------- */

	static getIsFilterLegacy (configGroup) {
		const val = Config.get(configGroup, "filterModeLegacy");
		switch (val) {
			case ConfigConsts.C_BOOL_DISABLED: return true;
			case ConfigConsts.C_BOOL_ENABLED: return false;
			case ConfigConsts.C_USE_GAME_DEFAULT: return VetoolsConfig.get("styleSwitcher", "style") === SITE_STYLE__ONE;
		}
	}

	static getIsFilterModern (configGroup) {
		const val = Config.get(configGroup, "filterModeModern");
		switch (val) {
			case ConfigConsts.C_BOOL_DISABLED: return true;
			case ConfigConsts.C_BOOL_ENABLED: return false;
			case ConfigConsts.C_USE_GAME_DEFAULT: return VetoolsConfig.get("styleSwitcher", "style") === SITE_STYLE__CLASSIC;
		}
	}

	static isSearchItemFilterInclude ({searchItem, isFilterUa, isFilterLegacy, isFilterModern}) {
		if (isFilterUa && SourceUtil.isNonstandardSource(searchItem.source)) return false;
		if (isFilterLegacy && SourceUtil.isLegacySourceWotc(searchItem.source)) return false;
		if (isFilterModern && SourceUtil.isSiteSource(searchItem.source) && !SourceUtil.isClassicSource(searchItem.source)) return false;
		return true;
	}

	/* -------------------------------------------- */

	static getPagesHidden (configGroup) {
		return Config.get(configGroup, game.user.isGM ? "pagesHiddenGm" : "pagesHidden");
	}
}

// TODO(Future)
//  - images are inconsistent with the rest of the module--make a unified path for e.g. `DataConverter` plus this
class Patcher_QuickInsert {
	static init () {
		if (!UtilCompat.isQuickInsertActive()) return;
		if (!Config.get("integrationQuickInsert", "isEnabled")) return;

		this._init_doPatch();
	}

	static _init_doPatch () {
		if (!globalThis.QuickInsert) {
			console.warn(...LGT, `Quick Insert is active, but "globalThis.QuickInsert" was not available! This should never occur.`);
			return;
		}

		let value = null;

		Object.defineProperty(
			globalThis.QuickInsert,
			"searchLib",
			{
				get () { return value; },
				set (valueNxt) {
					const cache = valueNxt.indexCompendiums.bind(valueNxt);
					valueNxt.indexCompendiums = async function (...args) {
						const out = await cache(...args);
						await Patcher_QuickInsert._pDoIndexPlutoniumData();
						return out;
					};
					value = valueNxt;
				},
			},
		);
	}

	static async _pDoIndexPlutoniumData () {
		const index = await UtilIntegrationFauxCompendium.pGetPlutoniumIndex();

		const quickInsertIndexingDisabled = UtilGameSettings.getSafe(UtilCompat.MODULE_QUICK_INSERT, "indexingDisabled");

		const isFilterUa = Config.get("integrationQuickInsert", "isFilterSourcesUa");
		const isFilterLegacy = UtilIntegrationFauxCompendium.getIsFilterLegacy("integrationQuickInsert");
		const isFilterModern = UtilIntegrationFauxCompendium.getIsFilterModern("integrationQuickInsert");
		const pagesHidden = UtilIntegrationFauxCompendium.getPagesHidden("integrationQuickInsert");

		const clsBuilderFaux = {
			from (indexItem) { return indexItem; },
		};

		const seenUuids = new Set();
		for (const indexItem of index) {
			const searchItem = indexItem.getFromFactory(clsBuilderFaux);
			if (pagesHidden[searchItem.page]) continue;
			if (!UtilIntegrationFauxCompendium.isSearchItemFilterInclude({searchItem, isFilterUa, isFilterLegacy, isFilterModern})) continue;
			if (this._isDocumentTypeIgnored({quickInsertIndexingDisabled, ClsImportList: searchItem.ClsImportList})) continue;

			// Quick Insert doesn't like duplicate UUIDs, so avoid adding them to prevent crashing the UI.
			if (seenUuids.has(searchItem.uuid)) {
				console.error(`Duplicate UUID: ${searchItem.uuid}`);
				continue;
			}

			seenUuids.add(searchItem.uuid);

			QuickInsert.searchLib.addItem(searchItem);
		}
	}

	static _isDocumentTypeIgnored ({quickInsertIndexingDisabled, ClsImportList}) {
		// As of 2023-11-15, cards are not supported
		if (ClsImportList.FOLDER_TYPE === "Cards") return true;
		return quickInsertIndexingDisabled?.entities?.[ClsImportList.FOLDER_TYPE]?.includes
			&& quickInsertIndexingDisabled.entities[ClsImportList.FOLDER_TYPE].includes(game.user?.role);
	}
}

class Patcher_Migration {
	// TODO(v15) remove
	static async _pDoMigrationFixJunkSourceId () {
		let cntActors = 0;
		let cntItems = 0;
		for (const act of game.actors) {
			let isModified = false;
			for (const itm of act.items) {
				const sourceId = UtilDocument.getDocumentSourceReadOnly(itm).flags?.dnd5e?.sourceId;
				if (!sourceId?.startsWith(".")) continue;

				isModified = true;
				cntItems++;
				await itm.setFlag("dnd5e", "sourceId", `Actor.${act.id}.Item${sourceId}`);
			}
			if (isModified) cntActors++;
		}

		if (!cntActors || !cntItems) return;

		ui.notifications.warn(`${Config.get("ui", "isStreamerMode") ? "" : "Plutonium: "}Fixed likely-broken advancements in ${cntItems} item${cntItems === 1 ? "" : "s"} on ${cntActors} actor${cntActors === 1 ? "" : "s"}. You may need to reload.`, {permanent: true});
	}

	// TODO(v15) remove
	static async _pDoMigrationFixJunkAdvancementItemUuid () {
		const isUnwantedUuid = (uuid) => {
			// blank/missing uuid
			if (!uuid) return true;

			// relative uuid
			if (uuid.startsWith(".")) return true;

			// embedded uuid
			const parsed = foundry.utils.parseUuid(uuid);
			if (parsed?.embedded.length) return true;

			return false;
		};

		let cntActors = 0;
		let cntItems = 0;
		for (const act of game.actors) {
			let isModified = false;
			for (const itm of act.items) {
				const advancements = UtilDocument.getDocumentSourceReadOnly(itm).system?.advancement;
				if (!Object.values(advancements || {}).some(adv => adv.configuration?.items?.some(info => isUnwantedUuid(info.uuid)))) continue;

				isModified = true;
				cntItems++;
				const cpyAdvancements = MiscUtil.copyFast(advancements);
				Object.values(cpyAdvancements)
					.forEach(adv => {
						if (!adv.configuration?.items?.length) return;
						adv.configuration.items = adv.configuration.items
							.filter(info => !isUnwantedUuid(info.uuid));
					});

				// Avoid sparse-diff as we're intentionally providing complete advancement object
				await itm.update({"system.advancement": cpyAdvancements}, {diff: false});
			}
			if (isModified) cntActors++;
		}

		if (!cntActors || !cntItems) return;

		ui.notifications.warn(`${Config.get("ui", "isStreamerMode") ? "" : "Plutonium: "}Fixed likely-broken advancement item links in ${cntItems} item${cntItems === 1 ? "" : "s"} on ${cntActors} actor${cntActors === 1 ? "" : "s"}. You may need to reload.`, {permanent: true});
	}

	static prePreInit () {
		if (game.system.id !== SharedConsts.SYSTEM_ID_DND5E) return;

		Hooks.once("ready", async () => {
			// (Implement as required)
			await this._pDoMigrationFixJunkSourceId();
			await this._pDoMigrationFixJunkAdvancementItemUuid();
		});
	}
}

// TODO(Future)
//  Ideally, we should enable "rightclick -> Jump to Pin" from journal entry sidebar
//  Unfortunately, as of 2025-04-20, the sidebar context handling is bound at the per-page
//    level. We therefore cannot pull out the anchor link for a heading, and therefore
//    cannot pan to the correct note -- we're stuck with a random "first matching note"
//    selection.
class Patcher_NoteConfig {
	static _LAST_DROP_META = null;

	static init () {
		/**
		 * When double-clicking a note which has a Plutonium-set "header anchor", cancel the standard flow and instead
		 *   directly open the journal to that header.
		 */
		Hooks.on("activateNote", (note, opts) => {
			if (!Config.get("journalEntries", "isEnableNoteHeaderAnchor")) return;

			if (note.page?.type !== "text") return;

			const headerAnchor = note.document.flags[SharedConsts.MODULE_ID]?.journalPageHeaderAnchor;
			if (!headerAnchor) return;

			// N.b.: avoid using `JournalEntryPage.slugifyHeading` as it clobbers the trailing `$1` part
			note.entry.sheet.render(true, {...opts, anchor: headerAnchor});

			// Cancel standard flow
			return false;
		});

		/**
		 * When dropping a journal page to the canvas, stash the anchor with a timer, such that we can populate the next
		 *   note preview (hopefully, the one generated by the drop event) with additional data.
		 */
		Hooks.on("dropCanvasData", (cvs, drop, evt) => {
			if (!Config.get("journalEntries", "isEnableNoteHeaderAnchor")) return;

			if (
				drop.type !== "JournalEntryPage"
				|| !drop.anchor?.slug
			) return;

			const mParts = /^JournalEntry\.(?<idJournalEntry>[^.]+)\.JournalEntryPage\.(?<idPage>[^.$]+)$/.exec(drop.uuid);
			if (!mParts) return;

			Patcher_NoteConfig._LAST_DROP_META = {
				anchorSlug: drop.anchor.slug,
				anchorName: drop.anchor.name,
				uuid: drop.uuid,
				idJournalEntry: mParts.groups.idJournalEntry,
				idPage: mParts.groups.idPage,
				timeDrop: Date.now(),
			};
		});
	}

	/* -------------------------------------------- */

	static handleConfigUpdate ({isInit = false} = {}) {
		try {
			return this._handleConfigUpdate_();
		} catch (e) {
			if (!isInit) throw e;
			Config.handleFailedInitConfigApplication("journalEntries", "isEnableNoteHeaderAnchor", e);
		}
	}

	static _handleConfigUpdate_ () {
		this._handleConfigUpdate_togglePatches();
	}

	static _handleConfigUpdate_togglePatches () {
		UtilLibWrapper.togglePatch(
			"foundry.applications.sheets.NoteConfig.prototype._renderHTML",
			this._lw_NoteConfig_prototype__renderHTML,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
			Config.get("journalEntries", "isEnableNoteHeaderAnchor"),
		);

		UtilLibWrapper.togglePatch(
			"foundry.canvas.layers.NotesLayer.prototype._createPreview",
			this._lw_NotesLayer_prototype__createPreview,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
			Config.get("journalEntries", "isEnableNoteHeaderAnchor"),
		);
	}

	/**
	 * @this {NoteConfig}
	 */
	static async _lw_NoteConfig_prototype__renderHTML (fn, ...args) {
		const renderedOut = await fn(...args);
		const rowPageId = veEs(`[name="pageId"]`, renderedOut.body).vee.closest(`.form-group`);
		rowPageId
			.vee.after(veT`<div class="form-group">
			  <label class="ve-help" title="A sluggified header (with an optional &quot;$&lt;number&gt;&quot; suffix to differentiate between multiple headers with the same name); for example, &quot;1.-introduction-to-the-adventure&quot; or &quot;treasure-and-experience$3&quot;. This can be automatically generated by dragging from a journal entry's contents to the chat (or any other text input), and copying the part after the &quot;#&quot;. Alternatively, this can be copied from the &quot;data-anchor&quot; HTML attribute on a journal entry header.">Header Anchor</label>
			  <div class="form-fields">
					<input type="text" class="ve-code" name="flags.${SharedConsts.MODULE_ID}.journalPageHeaderAnchor" value="${this.document.flags[SharedConsts.MODULE_ID]?.journalPageHeaderAnchor || ""}" placeholder="Header">
			  </div>
		 </div>`);
		return renderedOut;
	}

	static async _lw_NotesLayer_prototype__createPreview (fn, ...args) {
		const [createData] = args;

		if (
			Patcher_NoteConfig._LAST_DROP_META == null
			|| (Date.now() > (Patcher_NoteConfig._LAST_DROP_META.timeDrop + 2000))
			|| Patcher_NoteConfig._LAST_DROP_META.idJournalEntry !== createData?.entryId
			|| Patcher_NoteConfig._LAST_DROP_META.idPage !== createData?.pageId
		) return fn(...args);

		MiscUtil.set(createData, "flags", SharedConsts.MODULE_ID, "journalPageHeaderAnchor", Patcher_NoteConfig._LAST_DROP_META.anchorSlug);

		return fn(...args);
	}

	/* -------------------------------------------- */
}

class Patcher_SpellRegistry {
	static init () {
		if (!Dnd5eUtil.isDnd5e()) return;

		UtilLibWrapper.addPatch(
			"game.system.registry.spellLists.forSpell",
			this._lw_game_system_registry_spellLists_forSpell,
			UtilLibWrapper.LIBWRAPPER_MODE_MIXED,
		);
	}

	static _lw_game_system_registry_spellLists_forSpell (fn, ...args) {
		const [uuid] = args;
		if (!uuid) return fn(...args);

		const spell = Patcher_Item_GetRollDataContext.getActiveItem({uuid}) ?? fromUuidSync(uuid);
		if (!spell?.flags?.[SharedConsts.MODULE_ID]?.spellClassNames?.length) return fn(...args);

		// Wrap into the format dnd5e expects
		return new Set(
			spell.flags[SharedConsts.MODULE_ID].spellClassNames
				.map(className => ({
					metadata: {
						type: "class",
						identifier: UtilDocumentItem.getNameAsIdentifier(className),
					},
					name: className,
				})),
		);
	}
}

class Patcher_Dev {
	static prePreInit () {
		this.handleConfigUpdate({isInit: true});
	}

	/* -------------------------------------------- */

	static _INCLUDE_REGEX = new RegExp(`modules/${SharedConsts.MODULE_ID}`);

	static handleConfigUpdate ({isInit = false} = {}) {
		this._handleConfigUpdate_compatibility({isInit});
		this._handleConfigUpdate_hooks({isInit});
	}

	static _handleConfigUpdate_compatibility () {
		const ixExisting = CONFIG.compatibility.includePatterns
			.indexOf(this._INCLUDE_REGEX);

		if (Config.get("misc", "isFilterCompatibilityWarnings")) {
			if (~ixExisting) return;

			CONFIG.compatibility.includePatterns.push(this._INCLUDE_REGEX);
			return;
		}

		if (!~ixExisting) return;
		CONFIG.compatibility.includePatterns.splice(ixExisting, 1);
	}

	static _IS_RESET_DEBUG_HOOKS = false;

	static _handleConfigUpdate_hooks () {
		if (Config.get("misc", "isDebugHooks")) {
			CONFIG.debug.hooks = true;
			this._IS_RESET_DEBUG_HOOKS = true;
			return;
		}

		// Only reset if we set the flag in the first place
		if (this._IS_RESET_DEBUG_HOOKS) {
			CONFIG.debug.hooks = false;
			this._IS_RESET_DEBUG_HOOKS = false;
		}
	}
}

class UtilClearFlags {
	static async pMutClearFlags (doc) {
		await UtilDocuments.pUpdateDocument(
			doc,
			{
				[`flags.${SharedConsts.MODULE_ID}`]: globalThis._del,
			},
			{isRender: false},
		);

		await this._pMutClearFlags_pMutEmbeds(doc);
	}

	static async _pMutClearFlags_pMutEmbeds (doc) {
		for (const [embedName, propData] of Object.entries(doc.constructor.metadata.embedded)) {
			await UtilDocuments.pUpdateEmbeddedDocuments(
				doc,
				doc[propData]
					.map(embed => ({
						_id: embed.id,
						[`flags.${SharedConsts.MODULE_ID}`]: globalThis._del,
					})),
				{
					ClsEmbed: CONFIG[embedName].documentClass,
				},
			);

			for (const docSub of doc[propData]) {
				await this._pMutClearFlags_pMutEmbeds(docSub);
			}
		}
	}
}

class Patcher_ClientDocument {
	static init () {
		this._init_contentLinks();
	}

	static _init_contentLinks () {
		try {
			this._init_contentLinks_();
		} catch (e) {
			Config.handleFailedInitConfigApplication("text", "isAutoRollActorItemTags");
			Config.handleFailedInitConfigApplication("text", "isJumpToFolderTags", e);
		}
	}

	static _init_contentLinks_ () {
		UtilLibWrapper.addPatch(
			"Folder.prototype._onClickDocumentLink",
			this._lw_Folder_prototype__onClickDocumentLink,
			UtilLibWrapper.LIBWRAPPER_MODE_MIXED,
		);

		UtilLibWrapper.addPatch(
			"Item.prototype._onClickDocumentLink",
			this._lw_Item_prototype__onClickDocumentLink,
			UtilLibWrapper.LIBWRAPPER_MODE_MIXED,
		);
	}

	static _lw_Folder_prototype__onClickDocumentLink (fn, ...args) {
		const [evt] = args;
		if (Patcher_ClientDocument._handleContentLinkClick_folder(evt, this)) return;
		return fn(...args);
	}

	static _lw_Item_prototype__onClickDocumentLink (fn, ...args) {
		const [evt] = args;
		if (Patcher_ClientDocument._handleContentLinkClick_withParentActor(evt, this)) return;
		return fn(...args);
	}

	static _handleContentLinkClick_folder (evt, doc) {
		if (!Config.get("text", "isJumpToFolderTags")) return false;

		if (evt?.shiftKey) return false;

		if (doc.ownership < CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER) {
			ui.notifications.warn(`You do not have sufficient ownership to view this Folder.`);
			return true;
		}

		const sidebarTabName = CONFIG[doc.type]?.documentClass?.metadata?.collection;
		if (!sidebarTabName) return false;

		(async () => {
			await ui.sidebar.changeTab(sidebarTabName, "primary");

			const elesFolder = {};
			[...ui.sidebar.element.querySelectorAll(".directory-item.folder")]
				.forEach(ele => {
					elesFolder[ele.getAttribute("data-uuid")] = ele;
				});

			const recursivelyExpand = (doc_, isAnyExpanded_ = false) => {
				if (!doc_.expanded) {
					const uuid = doc_.uuid;

					// region Based on `SidebarDirectory._toggleFolder`
					elesFolder[uuid].classList.add("expanded");
					game.folders._expanded[uuid] = true;
					// endregion
				}

				if (doc_.folder) {
					const isAnyExpandedSub = recursivelyExpand(doc_.folder, isAnyExpanded_);
					isAnyExpanded_ ||= isAnyExpandedSub;
				}

				return isAnyExpanded_;
			};

			const isAnyExpand = recursivelyExpand(doc);

			if (isAnyExpand && ui.sidebar.popouts[sidebarTabName]) ui.sidebar.popouts[sidebarTabName].setPosition();

			elesFolder[doc.uuid].scrollIntoView({block: "center"});

			// Briefly make the folder contents glow
			// FIXME(Future) this used to also make the folder header glow, but v13 "background"/"border" was breaking
			//   Could e.g.:
			//   - temporarily override the background of the folder header with `transparent` (check if this works when
			//     the folder has a color assigned)
			//   - something else?
			elesFolder[doc.uuid].classList.add("jlnk__folder-pulse-1s");
			setTimeout(() => elesFolder[doc.uuid].classList.remove("jlnk__folder-pulse-1s"), 1000);
		})()
			.then(null);

		return true;
	}

	static _handleContentLinkClick_withParentActor (evt, doc) {
		if (Config.get("text", "isAutoRollActorItemTags") === !!evt?.shiftKey) return false;

		if (!(doc.parent instanceof Actor)) return false;

		if (doc.parent.ownership < CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER) {
			ui.notifications.warn(`You do not have sufficient ownership to view this ${doc.parent.documentName}.`);
			return true;
		}

		if (doc.ownership < CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER) {
			ui.notifications.warn(`You do not have sufficient ownership to view this ${doc.documentName}.`);
			return true;
		}

		doc.use({legacy: false});

		return true;
	}
}

/**
 * This is a bad idea -- UUIDs which are only valid when Plutonium is enabled are
 *   extremely brittle, and would require the user to use e.g. RIC (https://foundryvtt.com/packages/ric)
 *   to repair if they want to stop using the module (or disable after importing content).
 * Avoid leaning on this if possible.
 */
class Patcher_FoundryDataFields {
	static prePreInit () {
		UtilLibWrapper.addPatch(
			"foundry.data.fields.DocumentUUIDField.prototype._validateType",
			this._lw_DocumentUUIDField_prototype___validateType,
			UtilLibWrapper.LIBWRAPPER_MODE_MIXED,
		);
	}

	static _lw_DocumentUUIDField_prototype___validateType (fn, ...args) {
		const [value] = args;
		if (!value) return fn(...args);
		if (typeof value !== "string") return fn(...args);

		// Allow fake Plutonium fake UUIDs
		if (UtilUuid.isCustomUuid(value)) {
			console.warn(...LGT, `Custom UUID "${value}" found! Note that this is not a valid UUID, and should be replaced with a "Compendium. ..." equivalent.`);
			return;
		}

		return fn(...args);
	}
}

class Patcher_CompendiumCollection {
	static init () {
		// Disabled as incomplete
		// Also breaks e.g. "cast" activities on actor sheet items?
		if (game) return;

		UtilLibWrapper.addPatch(
			"game.packs.get",
			this._lw_game_packs_get,
			UtilLibWrapper.LIBWRAPPER_MODE_MIXED,
		);
	}

	static _lw_game_packs_get (fn, ...args) {
		const out = fn(...args);
		if (out) return out;

		const [key] = args;
		if (!key) return out;

		// TODO(Future) aborted attempt at fixing `fromUuidSync` -- doesn't work as imported internally
		if (!UtilUuidFauxCompendium.isCustomUuidPack(key)) return out;

		const fauxCompendiumCollection = new class extends foundry.documents.collections.CompendiumCollection {
			// TODO this doesn't work, as `key` is just `0`s :(
			get (key, options) {
				if (options?.relative) return null;
				if (!key) return null;

				// TODO

				return null;
			}
		}();

		return fauxCompendiumCollection;
	}
}

class Patcher_HtmlDocumentTagsElement {
	static init () {
		UtilLibWrapper.addPatch(
			"foundry.applications.elements.HTMLDocumentTagsElement.prototype._activateListeners",
			this._lw_HTMLDocumentTagsElement_prototype__activateListeners,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
		);
	}

	static _lw_HTMLDocumentTagsElement_prototype__activateListeners (fn, ...args) {
		// Pre-bind our drop listener, such that it takes precedence
		// The Foundry handler calls `stopImmediatePropagation`, which otherwise bricks our handler
		this.addEventListener(
			"drop",
			evt => {
				// Custom handling for drops; see `Patcher_TextEditor`
				const data = foundry.applications.ux.TextEditor.implementation.getDragEventData(evt, {plut_isRetainUuid: true});

				if (!data.tagTag || !data.tagText) {
					// Based on `#onDrop`
					if (!data.uuid) return;

					if (this.single) {
						this._setValue(data.uuid);
					} else {
						const nxt = this._getValue();
						nxt.push(data.uuid);
						this._setValue(nxt);
					}

					this._refresh();
					this.dispatchEvent(new Event("change", { bubbles: true, cancelable: true }));

					return;
				}

				const uuid = UtilUuidFauxCompendium.getCustomUuid({
					tag: data.tagTag,
					text: data.tagText,
				});

				// Based on `#tryAdd`
				this._value[uuid] = data.tagText.split("|")[0];
				this._refresh();
				this.dispatchEvent(new Event("change", { bubbles: true, cancelable: true }));
			},
			{signal: this.abortSignal},
		);

		return fn(...args);
	}
}

class Patcher_HtmlElement {
	static init () {
		UtilLibWrapper.addPatch(
			"HTMLElement.prototype.animate",
			this._lw_HTMLElement_prototype_animate,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
		);
	}

	static _lw_HTMLElement_prototype_animate (fn, ...args) {
		return fn(...Patcher_HtmlElement._getNextArgs(...args));
	}

	static _getNextArgs (...args) {
		let nxtArgs = [...args];

		if (Config.get("ui", "isFastAnimations") && nxtArgs[1] != null) {
			// !! Copied from `Patcher_Jquery`; may not be accurate !!
			//
			// This mysteriously breaks when going to lower numbers
			//   Therefore, limit it to "numbers above 33," in case lower numbers have special meaning
			//   It may be that there exists a race condition between this and e.g. saving sheet state,
			//   which would explain things like "opening a token sheet, closing it, then updating the health of
			//   the token causes the sheet to re-open" existing.
			if (typeof nxtArgs[1] === "object" && nxtArgs[1].duration != null) {
				if (nxtArgs[1].duration > 33) nxtArgs[1].duration = 33;
			} else if (typeof nxtArgs[1] === "number") {
				if (nxtArgs[1] > 33) nxtArgs[1] = 33;
			}
		}

		return nxtArgs;
	}
}

