/**
 * Based on Spotlight's "BaseSearchTerm"
 */
class _PlutoniumBaseSearchTerm extends PlutoniumSearchItem {
	// region Methods
	onClick (evt) {
		return this.show();
	}

	onDragStart (evt) {}
	onDragEnd (evt) {}

	match (query) {
		return this.name.toLowerCase().includes(query) || this.keywords.some((keyword) => keyword.includes(query));
	}
	// endregion

	// region Fields
	get name () { return super.name; }
	get nameExtra () { return ""; }
	get description () { return Parser.sourceJsonToFull(this.source); }
	get query () { return null; }

	// Additional; name is used by default
	get keywords () {
		return [
			Parser.sourceJsonToFull(this.source),
			Parser.sourceJsonToAbv(this.source),
		];
	}

	get type () {
		return [
			this.documentType,
			Config.get("ui", "isStreamerMode") ? "5e" : SharedConsts.MODULE_TITLE,
			UrlUtil.pageToDisplayPage(this.page)
				// Tags are split on space; remove junky "&"s
				.replace(/ & /g, " "),
		]
			.filter(Boolean)
			.join(" ");
	}

	get data () {
		return {
			documentName: this.documentType,
		};
	}

	get actions () {
		return [
			{
				name: "Import",
				icon: UtilUi.getModuleFaIcon(),
				callback: async () => {
					await this.pImport();
				},
			},
		];
	}

	get dragData () { return super.dragData; }
	get img () { return super.img; }
	get icon () { return [UtilUi.getModuleFaIconClass(), this._icon]; }

	set query (val) {}
	// endregion

	static from (indexItem) { return new this(indexItem); }
}

class IntegrationSpotlightOmnisearch {
	static init () {
		if (!UtilCompat.isSpotlightOmnisearchActive()) return;
		if (!Config.get("integrationSpotlightOmnisearch", "isEnabled")) return;

		this._init_doBindIndexBuiltHook();
	}

	static _init_doBindIndexBuiltHook () {
		Hooks.on(
			"spotlightOmnisearch.indexBuilt",
			(INDEX, promises) => {
				promises.push((async () => {
					const index = await UtilIntegrationFauxCompendium.pGetPlutoniumIndex();

					const isFilterUa = Config.get("integrationSpotlightOmnisearch", "isFilterSourcesUa");
					const isFilterLegacy = UtilIntegrationFauxCompendium.getIsFilterLegacy("integrationSpotlightOmnisearch");
					const isFilterModern = UtilIntegrationFauxCompendium.getIsFilterModern("integrationSpotlightOmnisearch");
					const pagesHidden = UtilIntegrationFauxCompendium.getPagesHidden("integrationSpotlightOmnisearch");

					for (const indexItem of index) {
						const searchItem = _PlutoniumBaseSearchTerm.deserialize(indexItem.serialize());

						if (pagesHidden[searchItem.page]) continue;
						if (!UtilIntegrationFauxCompendium.isSearchItemFilterInclude({searchItem, isFilterUa, isFilterLegacy, isFilterModern})) continue;

						INDEX.push(new CONFIG.SpotlightOmnisearch.SearchTerm({
							name: searchItem.name,
							description: searchItem.description,
							query: searchItem.query,
							keywords: searchItem.keywords,
							actions: searchItem.actions,
							dragData: searchItem.dragData,
							type: searchItem.type,
							data: searchItem.data,
							img: searchItem.img,
							icon: searchItem.icon,
							nameExtra: searchItem.nameExtra,
							onClick: searchItem.onClick.bind(searchItem),
							onDragStart: searchItem.onDragStart.bind(searchItem),
							onDragEnd: searchItem.onDragEnd.bind(searchItem),
						}));
					}
				})());
			},
		);
	}
}

