	static init () {
		if (!UtilCompat.isModuleChrisPremadesActive()) return;

		this._init_bindHookPreUpdateItem_avoidFlagClobber();
	}

	/**
	 * As of 2025-06-05 (CPR v1.2.36), the `ItemMedkit.update` function
	 *   removes any non-preserved flags. Add a pre-update hook to preserve
	 *   our "inert" flags, to avoid breaking Charactermancer spell levelling.
	 * @private
	 */
	static _init_bindHookPreUpdateItem_avoidFlagClobber () {
		Hooks.on(
			"preUpdateItem",
			(item, update, options, id) => {
				// CPR does a no-diff update (hence the problem); use this as
				//   an identifier for the bad update
				if (options?.diff !== false) return;

				// Only check items which currently have Plutonium flags
				if (!item?.flags[SharedConsts.MODULE_ID]) return;

				// Only fix updates which appear to be from CPR
				// This avoids killing our own e.g. "Clear Plutonium Flags" updates
				// Note that we *do not* check if the item already had CPR flags,
				//   as CPR includes the ability to re-apply the medkit to change
				//   automations.
				if (!update?.flags[UtilCompat.MODULE_CHRIS_PREMADES]) return;

				update.flags[SharedConsts.MODULE_ID] = item.flags[SharedConsts.MODULE_ID];
			},
		);
	}
